// بيانات السور
Object.assign(quranData, {
    9: { // سورة التوبة
        name: "التوبة",
        verses: [
            { text: "بَرَآءَةٌ مِّنَ ٱللَّهِ وَرَسُولِهِۦٓ إِلَى ٱلَّذِينَ عَٰهَدتُّم مِّنَ ٱلْمُشْرِكِينَ", tafsir: `أي هذه براءة ، على أنها خبر مبتدأ محذوف ، أو « براءة » مبتدأ خبره « إلى الذين » . ومعنى البراءة : انقطاع العصمة ، يقال : « برأ يبرأ من فلان » إذا قطع ما بينهما من الصلة. والمعنى : أن لا عصمة بين المسلمين وبين الذين عاهدوهم من المشركين ، فقد كان بين الرسول صلى‌الله‌عليه‌وآله‌وسلم وبين المشركين معاهدات ، لكنهم غدروا ، ولذا أجّلهم الرسول صلى‌الله‌عليه‌وآله‌وسلم أربعة أشهر ، فمن كان له معاهدة أعلمه الرسول صلى‌الله‌عليه‌وآله‌وسلم أنه يبقى على المعاهدة إلى أربعة أشهر ، ثم هو صلى‌الله‌عليه‌وآله‌وسلم حرب عليه فليتخذ حذره. ولم يكن هذا نقضا من الرسول صلى‌الله‌عليه‌وآله‌وسلم بل نقضا منهم ، ولذا قال سبحانه : ( إِلَّا الَّذِينَ عاهَدْتُمْ مِنَ الْمُشْرِكِينَ ثُمَّ لَمْ يَنْقُصُوكُمْ شَيْئاً وَلَمْ يُظاهِرُوا عَلَيْكُمْ أَحَداً فَأَتِمُّوا إِلَيْهِمْ عَهْدَهُمْ إِلى مُدَّتِهِمْ ) (1) . وقد شاء الله سبحانه أن يطهر الجزيرة التي أصبحت عاصمة الإسلام عن رجس الشرك والنفاق لتتوحد فيها الكلمة ويكون للمسلمين دولة مرهوبة الجانب ليفرغوا إلى الروم والفرس.` },
            { text: "فَسِيحُوا۟ فِى ٱلْأَرْضِ أَرْبَعَةَ أَشْهُرٍ وَٱعْلَمُوٓا۟ أَنَّكُمْ غَيْرُ مُعْجِزِى ٱللَّهِ وَأَنَّ ٱللَّهَ مُخْزِى ٱلْكَٰفِرِينَ", tafsir: `أيها الكفار ( فِي الْأَرْضِ أَرْبَعَةَ أَشْهُرٍ ) معنى « السيح » السير ، يقال : « ساح » إذا سار على مهل. أي : أنتم في مهلة بأن تسيروا آمنين وتتصرفوا في حوائجكم بكل تأن وطمأنينة إلى أربعة أشهر من ابتداء الإعلان ، وهو من يوم النحر إلى العاشر من ربيع الآخر ، فإذا ( 1) التوبة : 4. وَاعْلَمُوا أَنَّكُمْ غَيْرُ مُعْجِزِي اللهِ وَأَنَّ اللهَ مُخْزِي الْكافِرِينَ (2) انقضت هذه المدة فليس لكم عهد ولا أمان ، والمحاربة معكم لا تعتبر غدرا ومباغتة ( وَاعْلَمُوا ) أيها الكفار ( أَنَّكُمْ غَيْرُ مُعْجِزِي اللهِ ) أي لا تتمكنون من أن تعجزوه وتغلبوه ، بل هو القادر على أن يخزيكم بأيدي المسلمين ، فلا تفكروا في محاربة المسلمين ( وَأَنَّ اللهَ مُخْزِي الْكافِرِينَ ) « الخزي » النكال ، أي أنه سبحانه ينكل بهم وينتصر عليهم. روى المفسرون أنه لما نزلت سورة براءة دفعها الرسول صلى‌الله‌عليه‌وآله‌وسلم إلى أبي بكر ليذهب إلى الحج فيقرأها على المشركين ، فلما مضى بعض الطريق جاء جبرئيل عليه‌السلام إلى الرسول صلى‌الله‌عليه‌وآله‌وسلم وقال له : إن السورة لا يبلغها إلا أنت أو رجل من أهل بيتك ، فأمر الرسول صلى‌الله‌عليه‌وآله‌وسلم عليا أن يخرج ويأخذها من أبي بكر ، فرجع أبو بكر وذهب علي عليه‌السلام وقرأ السورة على الكفار في منى ثلاثة أيام ، يوم العاشر من ذي الحجة ، والحادي عشر ، والثاني عشر منه ، فكان يخرط سيفه ويقول : لا يحج بعد عامنا هذا مشرك ، ولا يدخل البيت إلا مؤمن ، ولا يطوف بالبيت عريان ، ومن كانت بينه وبين رسول الله مدة فإن أجله إلى أربعة أشهر (1) . ولما أعلم الكفار بذلك ، أظهروا تبرؤهم ، فلم تبق صلة بينهم ، وقد كان هذا العمل خطرا ، حيث أن الكثرة الغالبة من الحجاج كانوا مشركين ، فالاصطدام بهم بهذه الصورة الخشنة كان مظنة الإيقاع بالإمام عليه‌السلام لكن الله سبحانه عصمه عن ذلك ، وقد كان نزول سورة براءة في السنة التاسعة من الهجرة ، بعد فتح مكة ، وفي العام القابل حج الرسول صلى‌الله‌عليه‌وآله‌وسلم حجة الوداع ، ولما أن رجع عن الحج نصب عليا ( 1) راجع بحار الأنوار : ج 21 ص 266. وَأَذانٌ مِنَ اللهِ وَرَسُولِهِ إِلَى النَّاسِ يَوْمَ الْحَجِّ الْأَكْبَرِ أَنَّ اللهَ بَرِيءٌ مِنَ الْمُشْرِكِينَ وَرَسُولُهُ فَإِنْ تُبْتُمْ فَهُوَ خَيْرٌ لَكُمْ وَإِنْ تَوَلَّيْتُمْ فَاعْلَمُوا أَنَّكُمْ غَيْرُ مُعْجِزِي اللهِ وَبَشِّرِ الَّذِينَ كَفَرُوا بِعَذابٍ أَلِيمٍ (3) خليفة في غدير خم ، وقبض في شهر صفر من تلك السنة.` },
            { text: "وَأَذَٰنٌ مِّنَ ٱللَّهِ وَرَسُولِهِۦٓ إِلَى ٱلنَّاسِ يَوْمَ ٱلْحَجِّ ٱلْأَكْبَرِ أَنَّ ٱللَّهَ بَرِىٓءٌ مِّنَ ٱلْمُشْرِكِينَ وَرَسُولُهُۥ فَإِن تُبْتُمْ فَهُوَ خَيْرٌ لَّكُمْ وَإِن تَوَلَّيْتُمْ فَٱعْلَمُوٓا۟ أَنَّكُمْ غَيْرُ مُعْجِزِى ٱللَّهِ وَبَشِّرِ ٱلَّذِينَ كَفَرُوا۟ بِعَذَابٍ أَلِيمٍ", tafsir: `أي إعلام منهما ( إِلَى النَّاسِ ) من المسلمين والمشركين ( يَوْمَ الْحَجِّ الْأَكْبَرِ ) وهو يوم النحر ، مقابل الحج الأصغر الذي هو العمرة ، وسمي بالأكبر لأن أعماله أكثر ، وإنما كان يوم النحر يوم الحج الأكبر لأن طواف الحج الذي هو أعظم أعماله يأتي فيه ، ويحتمل أن يراد بذلك جميع أيام الحج ، كما يقال : يوم الجمل ، ويوم صفين ، ويراد به الحين والزمان الذي وقعت فيه هذه الحوادث. والمعنى أن الله ورسوله يعلنان في هذا الوقت ( أَنَّ اللهَ بَرِيءٌ مِنَ الْمُشْرِكِينَ ) فلا علاقة له بهم ، ولا عهد له معهم ( وَرَسُولِهِ ) أيضا بريء منهم. وقد تقدم أن ذكره سبحانه هو الأصل ، وذكر الرسول للاحترام ولأنه المنفّذ المواجه ( فَإِنْ تُبْتُمْ ) أي رجعتم عن الشرك أيها المشركون ( فَهُوَ خَيْرٌ لَكُمْ ) في دنياكم حيث تسودون وتبقون مرفهين ( وَإِنْ تَوَلَّيْتُمْ ) أي أعرضتم عن الإيمان وبقيتم على الشرك ( فَاعْلَمُوا ) أنكم في معرض عقاب الله وعذابه و ( أَنَّكُمْ غَيْرُ مُعْجِزِي اللهِ ) أي لا تتمكنون من أن تعجزوه وتغلبوه ، بل هو ينتصر عليكم ويهلككم ويخزيكم ( وَبَشِّرِ ) يا رسول الله ( الَّذِينَ كَفَرُوا بِعَذابٍ أَلِيمٍ ) في الدنيا والآخرة. وتسمية الإنذار بشارة ، من باب الاستهزاء ، وذكر الضد إِلاَّ الَّذِينَ عاهَدْتُمْ مِنَ الْمُشْرِكِينَ ثُمَّ لَمْ يَنْقُصُوكُمْ شَيْئاً وَلَمْ يُظاهِرُوا عَلَيْكُمْ أَحَداً فَأَتِمُّوا إِلَيْهِمْ عَهْدَهُمْ إِلى مُدَّتِهِمْ إِنَّ اللهَ يُحِبُّ الْمُتَّقِينَ (4) فَإِذَا انْسَلَخَ الْأَشْهُرُ الْحُرُمُ مكان الضد ، كما يسمى الزنجي : كافورا ، والأعمى : بصيرا ، ولبيان أن العذاب يأتي مكان انتظار البشارة ، فإن الكفار كانوا ينتظرون بأعمالهم عاقبة حسنة فإذا بها عذاب ونكال. [4] ثم استثنى سبحانه من براءته من المشركين وانتهاء معاهدتهم إلى أربعة أشهر ، المعاهدين الذين وفوا بالعهد ( إِلَّا الَّذِينَ عاهَدْتُمْ ) أيها المسلمون معهم ( مِنَ الْمُشْرِكِينَ ثُمَّ لَمْ يَنْقُصُوكُمْ شَيْئاً ) بل بقوا أوفياء على عهودهم ( وَلَمْ يُظاهِرُوا عَلَيْكُمْ أَحَداً ) أي لم ينضموا إلى أعدائكم حتى يكونوا ظهيرا لهم عليكم ( فَأَتِمُّوا ) أيها المسلمون ( إِلَيْهِمْ ) وإنما قال : « إليهم » كأن الإتمام يبتدئ من المسلمين وينتهي إلى أولئك ( عَهْدَهُمْ إِلى مُدَّتِهِمْ ) المضروبة لهم ، فهم في مدة عهدهم آمنون لا يحاربون ( إِنَّ اللهَ يُحِبُّ الْمُتَّقِينَ ) الذين يتقون نقض العهد. وقد كان جماعة من المشركين كذلك بقوا أوفياء على عهودهم كبني كنانة وبني حمزة ، وقد كانت مدتهم تسعة أشهر ، وكأهل هجر والبحرين وإيلة ودومة الجندل الذين كانت للرسول صلى‌الله‌عليه‌وآله‌وسلم معهم مصالحات.` },
            { text: "إِلَّا ٱلَّذِينَ عَٰهَدتُّم مِّنَ ٱلْمُشْرِكِينَ ثُمَّ لَمْ يَنقُصُوكُمْ شَيْـًٔا وَلَمْ يُظَٰهِرُوا۟ عَلَيْكُمْ أَحَدًا فَأَتِمُّوٓا۟ إِلَيْهِمْ عَهْدَهُمْ إِلَىٰ مُدَّتِهِمْ إِنَّ ٱللَّهَ يُحِبُّ ٱلْمُتَّقِينَ", tafsir: `` },
            { text: "فَإِذَا ٱنسَلَخَ ٱلْأَشْهُرُ ٱلْحُرُمُ فَٱقْتُلُوا۟ ٱلْمُشْرِكِينَ حَيْثُ وَجَدتُّمُوهُمْ وَخُذُوهُمْ وَٱحْصُرُوهُمْ وَٱقْعُدُوا۟ لَهُمْ كُلَّ مَرْصَدٍ فَإِن تَابُوا۟ وَأَقَامُوا۟ ٱلصَّلَوٰةَ وَءَاتَوُا۟ ٱلزَّكَوٰةَ فَخَلُّوا۟ سَبِيلَهُمْ إِنَّ ٱللَّهَ غَفُورٌ رَّحِيمٌ", tafsir: `أي مضت الأشهر الأربعة التي أبيح للناكثين أن يسيحوا فيها ، والتي تنتهي بانتهاء عشرة أيام من ربيع الأول. ومعنى الانسلاخ : المضي ، كما ينسلخ الجلد عن الشاة ، فتبدو فَاقْتُلُوا الْمُشْرِكِينَ حَيْثُ وَجَدْتُمُوهُمْ وَخُذُوهُمْ وَاحْصُرُوهُمْ وَاقْعُدُوا لَهُمْ كُلَّ مَرْصَدٍ فَإِنْ تابُوا وَأَقامُوا الصَّلاةَ وَآتَوُا الزَّكاةَ فَخَلُّوا سَبِيلَهُمْ إِنَّ اللهَ غَفُورٌ رَحِيمٌ (5) وَإِنْ أَحَدٌ مِنَ الْمُشْرِكِينَ اسْتَجارَكَ عارية ظاهرة ، تشبيها للأشهر الحرم بالجلد الواقي لما بعدها من الأيام ( فَاقْتُلُوا الْمُشْرِكِينَ حَيْثُ وَجَدْتُمُوهُمْ ) فقد رفعت الهدنة والعهد بما نقضوا من العهود. وليس المراد قتل كل فرد فرد ، بل المراد وقوع المقاتلة ، وأنهم في حكم المحارب ، والمراد من « حيث وجدتموهم » أينما كانوا في حلّ أو في حرم ، فإن الحرم محترم لمن احترمه ، أما من لم يحترمه فليس بمحترم فيه ( وَخُذُوهُمْ ) أي خذوا من تمكنتم من أخذه ، والأخذ للقتل أو الحبس أو الاسترقاق ( وَاحْصُرُوهُمْ ) امنعوهم عن التصرف في حوائجهم و ( اقْعُدُوا لَهُمْ كُلَّ مَرْصَدٍ ) كل محل للرصد والتطلع كقلل الجبال ، والمضايق ، وقوارع الطرق ( فَإِنْ تابُوا ) عن كفرهم ( وَأَقامُوا الصَّلاةَ وَآتَوُا الزَّكاةَ ) أي التزموا بشرائط الإسلام ، فإن إظهار مجرد الإيمان بدون الرضوخ للأحكام والاستعداد لامتثال أوامر الله والرسول ، لا يعدّ إلا لقلقة لسان ( فَخَلُّوا سَبِيلَهُمْ ) دعوهم يتصرفون في البلاد ، لهم ما للمسلمين وعليهم ما على المسلمين ، لأنهم أصبحوا من زمرتهم ( إِنَّ اللهَ غَفُورٌ ) لذنوبهم ( رَحِيمٌ ) بهم يتفضّل عليهم بلطفه.` },
            { text: "وَإِنْ أَحَدٌ مِّنَ ٱلْمُشْرِكِينَ ٱسْتَجَارَكَ فَأَجِرْهُ حَتَّىٰ يَسْمَعَ كَلَٰمَ ٱللَّهِ ثُمَّ أَبْلِغْهُ مَأْمَنَهُۥ ذَٰلِكَ بِأَنَّهُمْ قَوْمٌ لَّا يَعْلَمُونَ", tafsir: `الذي أمرتك بقتاله بعد انسلاخ الأشهر الحرم ( اسْتَجارَكَ ) أي استأمنك ، بأن طلب الأمان منك ليسمع دعوتك فَأَجِرْهُ حَتَّى يَسْمَعَ كَلامَ اللهِ ثُمَّ أَبْلِغْهُ مَأْمَنَهُ ذلِكَ بِأَنَّهُمْ قَوْمٌ لا يَعْلَمُونَ (6) كَيْفَ يَكُونُ لِلْمُشْرِكِينَ عَهْدٌ عِنْدَ اللهِ وَعِنْدَ رَسُولِهِ إِلاَّ الَّذِينَ عاهَدْتُمْ عِنْدَ الْمَسْجِدِ الْحَرامِ ( فَأَجِرْهُ ) وأعطه الأمان ( حَتَّى يَسْمَعَ كَلامَ اللهِ ) وحيث أن كلام الرسول هو الوحي ، كما قال سبحانه : ( إِنْ هُوَ إِلَّا وَحْيٌ يُوحى ) (1) ، كان كلامه صلى‌الله‌عليه‌وآله‌وسلم كلام الله تعالى ( ثُمَ ) إن أسلم ، كان له ما للمسلمين ، وإن لم يسلم ف ( أَبْلِغْهُ مَأْمَنَهُ ) أي أرجعه إلى محل أمنه ، بأن يكون في حمايتك حتى يبلغ مكانه ، لئلّا يغدر به في الطريق ، وهذا كان كافرا حربيا ، بعد عدم قبوله الإسلام إلّا أنه حيث جاء لغرض صحيح ، لا يجوز قتله حتى يبلغ مأمنه ( ذلِكَ ) الأمان لمريد فهم الإسلام بسبب أنهم ( قَوْمٌ لا يَعْلَمُونَ ) حقيقة الإسلام ، فهذا الأمان سبب لدخول بعضهم في الإسلام. [7] ثم بيّن سبحانه وجه تبرؤ الرسول من العهود بعد أربعة أشهر بقوله : ( كَيْفَ يَكُونُ لِلْمُشْرِكِينَ عَهْدٌ عِنْدَ اللهِ وَعِنْدَ رَسُولِهِ ) وقد غدروا وظاهروا الأعداء ، وهل العهد يبقى مع ذلك ؟ وقد كان ضرب المدة أربعة أشهر من سماحة الإسلام ، وإلّا فقد استحق الغادرون أن يجهز عليهم فور غدرهم ( إِلَّا الَّذِينَ عاهَدْتُمْ ) معهم ( عِنْدَ الْمَسْجِدِ الْحَرامِ ) فإنهم لم يغدروا ، وكان استثناؤهم وحدهم دون سواهم ، وقد كانوا كثيرين ـ كما عرفت ـ لأنهم « الفرد » الظاهر السابق إلى الذهن ، والمراد بأولئك : هم قبائل بكر ، ( 1) النجم : 5. فَمَا اسْتَقامُوا لَكُمْ فَاسْتَقِيمُوا لَهُمْ إِنَّ اللهَ يُحِبُّ الْمُتَّقِينَ (7) كَيْفَ وَإِنْ يَظْهَرُوا عَلَيْكُمْ لا يَرْقُبُوا فِيكُمْ إِلاًّ وَلا ذِمَّةً يُرْضُونَكُمْ بِأَفْواهِهِمْ وَتَأْبى قُلُوبُهُمْ وَأَكْثَرُهُمْ فاسِقُونَ (8) اشْتَرَوْا بِآياتِ اللهِ ثَمَناً قَلِيلاً بنو خزيمة وبنو مدلج وبنو حمزة ، فقد دخلوا في عهد قريش يوم الحديبية ـ اليوم الذي عاهد رسول الله قريش قرب الحرم ـ وهؤلاء لم ينقضوا العهد ، فأمر الرسول صلى‌الله‌عليه‌وآله‌وسلم بإتمام مدتهم وفاء للعهد ( فَمَا اسْتَقامُوا لَكُمْ ) أي مدة استقامة المشركين الذين لم ينقضوا العهد معكم ، بأن لم تظهر منهم أمارات الغدر والخيانة ( فَاسْتَقِيمُوا لَهُمْ ) وابقوا على عهدكم معهم ( إِنَّ اللهَ يُحِبُّ الْمُتَّقِينَ ) الذين يتقون نقض العهد وخلف الوعد.` },
            { text: "كَيْفَ يَكُونُ لِلْمُشْرِكِينَ عَهْدٌ عِندَ ٱللَّهِ وَعِندَ رَسُولِهِۦٓ إِلَّا ٱلَّذِينَ عَٰهَدتُّمْ عِندَ ٱلْمَسْجِدِ ٱلْحَرَامِ فَمَا ٱسْتَقَٰمُوا۟ لَكُمْ فَٱسْتَقِيمُوا۟ لَهُمْ إِنَّ ٱللَّهَ يُحِبُّ ٱلْمُتَّقِينَ", tafsir: `` },
            { text: "كَيْفَ وَإِن يَظْهَرُوا۟ عَلَيْكُمْ لَا يَرْقُبُوا۟ فِيكُمْ إِلًّا وَلَا ذِمَّةً يُرْضُونَكُم بِأَفْوَٰهِهِمْ وَتَأْبَىٰ قُلُوبُهُمْ وَأَكْثَرُهُمْ فَٰسِقُونَ", tafsir: `يكون للمشركين عهد ، وتتورعون عن قتالهم ( وَ ) الحال أنهم ( إِنْ يَظْهَرُوا ) ويظفروا ( عَلَيْكُمْ ) ويتمكّنوا منكم ( لا يَرْقُبُوا فِيكُمْ إِلًّا وَلا ذِمَّةً ) أي لا يحفظوا ولا يرعوا فيكم قرابة ولا عهدا ، فإن « الإل » بمعنى القرابة ، و « الذمة » بمعنى العهد ، أو « الإل » بمعنى الحلف ، أي تذهب المحالفات والعهود بمجرد أن يتمكن هؤلاء منكم ( يُرْضُونَكُمْ ) هؤلاء المعاهدون ( بِأَفْواهِهِمْ ) فيتكلمون بكلام الموالين ( وَتَأْبى قُلُوبُهُمْ ) حبكم وولاءكم ، بل هي مليئة بغضا وعداوة ( وَأَكْثَرُهُمْ فاسِقُونَ ) خارجون عن العهود والمواثيق ، فإن الفسق بمعنى الخروج عن الحق.` },
            { text: "ٱشْتَرَوْا۟ بِـَٔايَٰتِ ٱللَّهِ ثَمَنًا قَلِيلًا فَصَدُّوا۟ عَن سَبِيلِهِۦٓ إِنَّهُمْ سَآءَ مَا كَانُوا۟ يَعْمَلُونَ", tafsir: `هؤلاء الناكثون بمقابل آيات ( اللهِ ) التي كان المفروض الإيمان بها ( ثَمَناً قَلِيلاً ) فقد أعرضوا عن الدين في مقابل دنيا قليلة فَصَدُّوا عَنْ سَبِيلِهِ إِنَّهُمْ ساءَ ما كانُوا يَعْمَلُونَ (9) لا يَرْقُبُونَ فِي مُؤْمِنٍ إِلاًّ وَلا ذِمَّةً وَأُولئِكَ هُمُ الْمُعْتَدُونَ (10) فَإِنْ تابُوا وَأَقامُوا الصَّلاةَ وَآتَوُا الزَّكاةَ فَإِخْوانُكُمْ فِي الدِّينِ وَنُفَصِّلُ الْآياتِ لِقَوْمٍ يَعْلَمُونَ (11) وَإِنْ نَكَثُوا أَيْمانَهُمْ مِنْ بَعْدِ عَهْدِهِمْ وَطَعَنُوا فِي دِينِكُمْ فَقاتِلُوا زائلة تحفظوا عليها ( فَصَدُّوا ) أي منعوا الناس ( عَنْ سَبِيلِهِ ) أي سبيل الله تعالى ( إِنَّهُمْ ساءَ ما كانُوا يَعْمَلُونَ ) أي بئس عملهم ذلك.` },
            { text: "لَا يَرْقُبُونَ فِى مُؤْمِنٍ إِلًّا وَلَا ذِمَّةً وَأُو۟لَٰٓئِكَ هُمُ ٱلْمُعْتَدُونَ", tafsir: `لا يراعون ولا يحفظون ( فِي مُؤْمِنٍ إِلًّا وَلا ذِمَّةً ) وهذا تأكيد لما سبق ، أي أنهم لا يراعون قرابة المؤمنين ولا عهدهم ، بل إن ظفروا بهم قتلوهم وانتقموا منهم ( وَأُولئِكَ ) الكفار الناقضون للعهد ( هُمُ الْمُعْتَدُونَ ) المجاوزون للحد ، حيث لم يراقبوا العهود.` },
            { text: "فَإِن تَابُوا۟ وَأَقَامُوا۟ ٱلصَّلَوٰةَ وَءَاتَوُا۟ ٱلزَّكَوٰةَ فَإِخْوَٰنُكُمْ فِى ٱلدِّينِ وَنُفَصِّلُ ٱلْـَٔايَٰتِ لِقَوْمٍ يَعْلَمُونَ", tafsir: `عن الكفر وقبلوا الإسلام ( وَ ) خضعوا لأوامره بأن ( أَقامُوا الصَّلاةَ وَآتَوُا الزَّكاةَ ) بالنسبة إلى من تمكن منها فهم إخوانكم ( فِي الدِّينِ ) أيها المسلمون ، لهم ما لكم ، وعليهم ما عليكم ( وَنُفَصِّلُ الْآياتِ ) نميّزها ونبيّنها ( لِقَوْمٍ يَعْلَمُونَ ) أي لأهل العلم ، فإنهم هم الذين يستفيدون منها لا الجهلة الذين لا يعرفون شيئا.` },
            { text: "وَإِن نَّكَثُوٓا۟ أَيْمَٰنَهُم مِّنۢ بَعْدِ عَهْدِهِمْ وَطَعَنُوا۟ فِى دِينِكُمْ فَقَٰتِلُوٓا۟ أَئِمَّةَ ٱلْكُفْرِ إِنَّهُمْ لَآ أَيْمَٰنَ لَهُمْ لَعَلَّهُمْ يَنتَهُونَ", tafsir: `أي نقضوا ( أَيْمانَهُمْ ) أي عهودهم والأيمان التي حلفوها بعدم الاعتداء عليكم ( مِنْ بَعْدِ عَهْدِهِمْ ) معكم ، وهذا كالتذكير ببشاعة عملهم ، وإلا فكل نكث يكون بعد العهد ( وَطَعَنُوا فِي دِينِكُمْ ) أي أخذوا يقدحون ويعيبون دينكم ( فَقاتِلُوا ) أيها أَئِمَّةَ الْكُفْرِ إِنَّهُمْ لا أَيْمانَ لَهُمْ لَعَلَّهُمْ يَنْتَهُونَ (12) أَ لا تُقاتِلُونَ قَوْماً نَكَثُوا أَيْمانَهُمْ وَهَمُّوا بِإِخْراجِ الرَّسُولِ وَهُمْ بَدَؤُكُمْ أَوَّلَ مَرَّةٍ المسلمون ( أَئِمَّةَ الْكُفْرِ ) « أئمة » جمع إمام ، وهم قادة الكافرين ، وإنما خصّهم بالذكر لأنهم المضلون لأتباعهم الذين إن استأصلوا ذهبت شوكة الكافرين. ويستفاد من الآية : أن الأولى قصد مراكز انتشار الكفر ومعادنه ( إِنَّهُمْ لا أَيْمانَ لَهُمْ ) أي أن أئمة الكفر لا يحفظون العهود والأيمان ولا وفاء لهم بها ( لَعَلَّهُمْ يَنْتَهُونَ ) أي قاتلوهم لكي ينتهوا عن الكفر. [13] ثم حثّ سبحانه المؤمنين بقتالهم بقوله : ( أَ لا تُقاتِلُونَ ) أي هلّا تقاتلون ( قَوْماً نَكَثُوا أَيْمانَهُمْ ) ونقضوها ، وهذا لا ينافي قوله : « لا أيمان لهم » فإن معنى ذلك : أنهم لا يحفظوها ، ومعنى هذا أنهم عقدوها. والحاصل أنهم عقدوا الأيمان ولكن نقضوها ( وَهَمُّوا بِإِخْراجِ الرَّسُولِ ) حين تآمروا في دار الندوة لإخراجه صلى‌الله‌عليه‌وآله‌وسلم من مكة. ولعل ذكر ذلك مع أنهم همّوا بقتله أيضا ، أوقع في النفس ، وأبلغ في التحريض والحث ، لأن الإخراج الذي قصده المتآمرون كان أسوأ من القتل ، فإنهم قصدوا إخراجه حتى يموت في بيداء خالية من الماء والطعام ، أو المراد بالإخراج : إخراجه من بين أظهرهم بالإثبات أو القتل أو النفي ( وَهُمْ بَدَؤُكُمْ أَوَّلَ مَرَّةٍ ) فإنهم ابتدءوا بقتال المسلمين وإيذائهم والصد عن سبيل الله. إن كل هذه الأمور الثلاثة مما يبيح لكم قتالهم ، فلماذا أَ تَخْشَوْنَهُمْ فَاللهُ أَحَقُّ أَنْ تَخْشَوْهُ إِنْ كُنْتُمْ مُؤْمِنِينَ (13) قاتِلُوهُمْ يُعَذِّبْهُمُ اللهُ بِأَيْدِيكُمْ وَيُخْزِهِمْ وَيَنْصُرْكُمْ عَلَيْهِمْ وَيَشْفِ صُدُورَ قَوْمٍ مُؤْمِنِينَ (14) وَيُذْهِبْ غَيْظَ قُلُوبِهِمْ وَيَتُوبُ اللهُ عَلى مَنْ يَشاءُ وَاللهُ عَلِيمٌ حَكِيمٌ (15) أَمْ حَسِبْتُمْ أَنْ تُتْرَكُوا لا تقاتلونهم أيها المسلمون ؟ ( أَ تَخْشَوْنَهُمْ ) أي هل تخشون هؤلاء الكفار أن تصيبكم منهم أذية ؟ ( فَاللهُ أَحَقُّ أَنْ تَخْشَوْهُ ) فإنكم إن تركتم قتال هؤلاء عذّبكم الله سبحانه ، فهو أحق بالخشية من هؤلاء ( إِنْ كُنْتُمْ مُؤْمِنِينَ ) بالله وبما جاء به الرسول ، أما غير المؤمن فلا يعتقد بعقاب الله سبحانه ولذا لا يخشاه.` },
            { text: "أَلَا تُقَٰتِلُونَ قَوْمًا نَّكَثُوٓا۟ أَيْمَٰنَهُمْ وَهَمُّوا۟ بِإِخْرَاجِ ٱلرَّسُولِ وَهُم بَدَءُوكُمْ أَوَّلَ مَرَّةٍ أَتَخْشَوْنَهُمْ فَٱللَّهُ أَحَقُّ أَن تَخْشَوْهُ إِن كُنتُم مُّؤْمِنِينَ", tafsir: `` },
            { text: "قَٰتِلُوهُمْ يُعَذِّبْهُمُ ٱللَّهُ بِأَيْدِيكُمْ وَيُخْزِهِمْ وَيَنصُرْكُمْ عَلَيْهِمْ وَيَشْفِ صُدُورَ قَوْمٍ مُّؤْمِنِينَ", tafsir: `أي قاتلوا الكفار أيها المسلمون ، إن تقاتلوهم ( يُعَذِّبْهُمُ اللهُ بِأَيْدِيكُمْ ) بالقتل والأسر ( وَيُخْزِهِمْ ) أي يذلهم ويحطّم شوكتهم ( وَيَنْصُرْكُمْ عَلَيْهِمْ ) حتى تكون كلمتكم هي العليا وتكون الغلبة لكم ( وَيَشْفِ صُدُورَ قَوْمٍ مُؤْمِنِينَ ) فإن صدور المؤمنين كانت ممتلئة غيظا وكمدا ، وكل من انتصر شفي صدره وذهبت فرحة النصر بغيظه.` },
            { text: "وَيُذْهِبْ غَيْظَ قُلُوبِهِمْ وَيَتُوبُ ٱللَّهُ عَلَىٰ مَن يَشَآءُ وَٱللَّهُ عَلِيمٌ حَكِيمٌ", tafsir: `الله ( غَيْظَ قُلُوبِهِمْ ) الذي تجمع فيها من كثرة ما رأوا من الاضطهاد والظلم ( وَيَتُوبُ اللهُ عَلى مَنْ يَشاءُ ) من هؤلاء الكفار إذا آمنوا مع فرط تعدّيهم وعتوّهم ، فإن الإسلام يجبّ ما قبله ( وَاللهُ عَلِيمٌ ) بالمصلحة حيث يأمركم بقتال هؤلاء ، فلا يأمر اعتباطا ( حَكِيمٌ ) فأمره عن حكمة ودراية.` },
            { text: "أَمْ حَسِبْتُمْ أَن تُتْرَكُوا۟ وَلَمَّا يَعْلَمِ ٱللَّهُ ٱلَّذِينَ جَٰهَدُوا۟ مِنكُمْ وَلَمْ يَتَّخِذُوا۟ مِن دُونِ ٱللَّهِ وَلَا رَسُولِهِۦ وَلَا ٱلْمُؤْمِنِينَ وَلِيجَةً وَٱللَّهُ خَبِيرٌۢ بِمَا تَعْمَلُونَ", tafsir: `« أم » أداة استفهام وعطف ، فقد عطفت هذه وَلَمَّا يَعْلَمِ اللهُ الَّذِينَ جاهَدُوا مِنْكُمْ وَلَمْ يَتَّخِذُوا مِنْ دُونِ اللهِ وَلا رَسُولِهِ وَلا الْمُؤْمِنِينَ وَلِيجَةً وَاللهُ خَبِيرٌ بِما تَعْمَلُونَ (16) الجملة على قوله : « ألا تقاتلون » أي : هل ظننتم أيها المسلمون أن تتركوا آمنين في دياركم من دون أن تكلّفوا الجهاد في سبيل الله سبحانه ؟ ( وَلَمَّا يَعْلَمِ اللهُ الَّذِينَ جاهَدُوا مِنْكُمْ ) « لمّا » حرف نفي مع تقريب وقوع الفعل الذي لم يقع بعد ، أي لم يتعلق علم الله سبحانه بالمجاهدين ، فإنه لم يصدر منكم جهاد ، حتى يكون علم الله واقعا خارجيا ، فإن العلم إنما يكون خارجيا ، إذا وجد متعلقه ، فإذا علم الإنسان أن زيدا سيجيء غدا ، يقال : لمّا يعلم فلان مجيء زيد ، بمعنى أنه لم يقع متعلق علمه ( وَ ) لمّا يعلم الله الذين ( لَمْ يَتَّخِذُوا مِنْ دُونِ اللهِ وَلا رَسُولِهِ وَلَا الْمُؤْمِنِينَ وَلِيجَةً ) « الوليجة » هي البطانة التي يخفي الإنسان لديها أسراره ، كأنه يلج فيها بسره ، فإن حبّ الشخص لا يمتحن في أيام الرخاء ، وإنما يمتحن في أيام الشدة والبلاء ، فالصديق لا يتّخذ غير صديقه وليجة ، بخلاف ضعيف الصداقة. ولذا نرى أن كثيرا من المسلمين اتخذوا الولائج ، وبدت ضمائرهم السيئة عند الجهاد ( وَاللهُ خَبِيرٌ ) أي عليم ( بِما تَعْمَلُونَ ) أيها المسلمون. والحاصل أنه لا بد من امتحانكم أيها المسلمون بالجهاد ليتبين المجاهد منكم من غيره ، ويتبين الذي يخلص في النية لله والرسول ، من غيره.` },
            { text: "مَا كَانَ لِلْمُشْرِكِينَ أَن يَعْمُرُوا۟ مَسَٰجِدَ ٱللَّهِ شَٰهِدِينَ عَلَىٰٓ أَنفُسِهِم بِٱلْكُفْرِ أُو۟لَٰٓئِكَ حَبِطَتْ أَعْمَٰلُهُمْ وَفِى ٱلنَّارِ هُمْ خَٰلِدُونَ", tafsir: `إِنَّما يَعْمُرُ مَساجِدَ اللهِ مَنْ آمَنَ بِاللهِ وَالْيَوْمِ الْآخِرِ مساوئنا وتكتمون محاسننا. فقالوا : أولكم محاسن ؟ قالوا : نعم ، إنا نعمر المسجد الحرام ، ونحجب الكعبة ، ونسقي الحجيج ، ونفك العاني (1) . فنزلت هذه الآيات : ( ما كانَ لِلْمُشْرِكِينَ أَنْ يَعْمُرُوا مَساجِدَ اللهِ ) سواء المسجد الحرام أو غيره حال كونهم ( شاهِدِينَ عَلى أَنْفُسِهِمْ بِالْكُفْرِ ) أي حال شهادتهم بكفر أنفسهم ، فكيف يجتمع الإذعان لله والكفر بآياته ، إنك إن أهنت شخصا وعمّرت داره كان تعمير داره سيئة لا حسنة ، فكيف يمكن الافتخار بأنه من المحاسن ؟ ومعنى « ما كان » : أنه ليس لهم ذلك. ولعلّ وجه الارتباط أنه لمّا نهي المشركون عن زيارة البيت بيّن سبحانه السبب ، بأن الشرك وعمارة المسجد ـ ماديا ومعنويا ـ لا يجتمعان. ( أُولئِكَ ) الذين كفروا ( حَبِطَتْ أَعْمالُهُمْ ) أي بطلت فلا قيمة لحسناتهم التي يزعمون أنها حسنة ، فإن الحسنة لا تقبل إلّا مع الإسلام والإخلاص ( وَفِي النَّارِ هُمْ خالِدُونَ ) أبد الآبدين ، بمعنى أنهم لو ماتوا كافرين لم تنفعهم الحسنة في نجاتهم من النار.` },
            { text: "إِنَّمَا يَعْمُرُ مَسَٰجِدَ ٱللَّهِ مَنْ ءَامَنَ بِٱللَّهِ وَٱلْيَوْمِ ٱلْـَٔاخِرِ وَأَقَامَ ٱلصَّلَوٰةَ وَءَاتَى ٱلزَّكَوٰةَ وَلَمْ يَخْشَ إِلَّا ٱللَّهَ فَعَسَىٰٓ أُو۟لَٰٓئِكَ أَن يَكُونُوا۟ مِنَ ٱلْمُهْتَدِينَ", tafsir: `بناءها وإقامة العبادة فيها ( مَنْ آمَنَ بِاللهِ وَالْيَوْمِ الْآخِرِ ) بأن أقرّ بالوحدانية واعترف بيوم القيامة ، إنه هو الذي ( 1) بحار الأنوار : ج 41 ص 63. وَأَقامَ الصَّلاةَ وَآتَى الزَّكاةَ وَلَمْ يَخْشَ إِلاَّ اللهَ فَعَسى أُولئِكَ أَنْ يَكُونُوا مِنَ الْمُهْتَدِينَ (18) أَجَعَلْتُمْ سِقايَةَ الْحاجِّ وَعِمارَةَ الْمَسْجِدِ الْحَرامِ كَمَنْ آمَنَ بِاللهِ وَالْيَوْمِ الْآخِرِ يجوز له تعمير المسجد ، وهو الذي يقبل منه ( وَأَقامَ الصَّلاةَ ) بمعنى التزم بشرائع الإسلام ، فإن الاعتراف اللفظي بدون الخضوع والانصياع لأوامر الإسلام لا يعدّ إلا لقلقة لسان ( وَآتَى الزَّكاةَ ) بالنسبة إلى من وجدها ( وَلَمْ يَخْشَ إِلَّا اللهَ ) أي خشية من نوع الخشية التوحيدية ، فإن المشرك يخشى من إلهين ، والمؤمن يخشى من إله واحد. وليس النفي مطلقا كما هو واضح ، قال سبحانه بالنسبة إلى النبي صلى‌الله‌عليه‌وآله‌وسلم ( وَتَخْشَى النَّاسَ ) (1) ، ( فَعَسى أُولئِكَ ) أي لعلّ الذين آمنوا بالله واليوم الآخر والتزموا بشرائطه ( أَنْ يَكُونُوا مِنَ الْمُهْتَدِينَ ) أي في زمرتهم ، وإنما قال « فعسى » لأن المرء لا يعرف مستقبله ، فربما كان مؤمنا عاملا ، ثم ينقلب كافرا ، فلا يكون من المهتدين ـ بما للكلمة من معنى ـ.` },
            { text: "أَجَعَلْتُمْ سِقَايَةَ ٱلْحَآجِّ وَعِمَارَةَ ٱلْمَسْجِدِ ٱلْحَرَامِ كَمَنْ ءَامَنَ بِٱللَّهِ وَٱلْيَوْمِ ٱلْـَٔاخِرِ وَجَٰهَدَ فِى سَبِيلِ ٱللَّهِ لَا يَسْتَوُۥنَ عِندَ ٱللَّهِ وَٱللَّهُ لَا يَهْدِى ٱلْقَوْمَ ٱلظَّٰلِمِينَ", tafsir: `« السقاية » مصدر سقي الماء ، و « الحاج » بمعنى القاصد إلى مكة ، بعد ما كان في اللغة بمعنى مطلق القصد ( وَعِمارَةَ الْمَسْجِدِ الْحَرامِ ) تعميرا بالبناء ، أو بالعبادة ، والأول هنا أقرب ( كَمَنْ آمَنَ ) الاستفهام إنكاري ، وفي الكلام حذف تقديره « أهل سقاية » أي ليس الساقي العامر للمسجد الحرام كالمؤمن ( بِاللهِ وَالْيَوْمِ الْآخِرِ ) وذلك لأن الإيمان هو أصل الفضائل ، أما السقاية والعمارة ( 1) الأحزاب : 38. وَجاهَدَ فِي سَبِيلِ اللهِ لا يَسْتَوُونَ عِنْدَ اللهِ وَاللهُ لا يَهْدِي الْقَوْمَ الظَّالِمِينَ (19) فهما أمران شكليان ، إذا لم تنضم إليهما روح الإيمان لن ينفعا شيئا ( وَجاهَدَ فِي سَبِيلِ اللهِ ) لإعلاء كلمته سبحانه ( لا يَسْتَوُونَ عِنْدَ اللهِ ) أولئك وهؤلاء ( وَاللهُ لا يَهْدِي الْقَوْمَ الظَّالِمِينَ ) فإن من ظلم نفسه بالكفر لا يكون مهديا ، فلا يكون عمله عن اهتداء حتى يترتب عليه فضل. روي أن العباس وشيبة أنهما تفاخرا ، فمر بهما أمير المؤمنين علي عليه‌السلام فقال : بماذا تتفاخران ؟ فقال العباس : لقد أوتيت من الفضل ما لم يؤت أحد ، سقاية الحاج. وقال شيبة : أوتيت عمارة المسجد الحرام. فقال علي عليه‌السلام : استحييت لكما ، فقد أوتيت على صغري ما لم تؤتيا. فقالا : وما أوتيت يا علي ؟ قال : ضربت خراطيمكما بالسيف حتى آمنتما بالله ورسوله ، فقام العباس مغضبا يجرّ ذيله حتى دخل على رسول الله صلى‌الله‌عليه‌وآله‌وسلم وقال : أما ترى إلى ما يستقبلني به علي ؟ فقال : ادعوا لي عليا فدعي له ، فقال الرسول صلى‌الله‌عليه‌وآله‌وسلم : ما حملك على ما استقبلت به عمك فقال : يا رسول الله صدمته بالحق فمن شاء فليغضب ومن شاء فليرض. فنزل جبرائيل عليه‌السلام فقال : يا محمد إن ربك يقرأ عليك السلام ويقول : اتل عليهم ( أَ جَعَلْتُمْ سِقايَةَ الْحاجِّ .. ) . فقال العباس : إنا قد رضينا « ثلاث مرات » (1) . وقد كانت سقاية الحاج عبارة عن تهيئة دلاء وأواني قبل الموسم فتملأ ماء من بئر زمزم ، فإذا جاء الحجاج سقوا منها ، حيث أن البئر ( 1) بحار الأنوار : ج 36 ص 39. الَّذِينَ آمَنُوا وَهاجَرُوا وَجاهَدُوا فِي سَبِيلِ اللهِ بِأَمْوالِهِمْ وَأَنْفُسِهِمْ أَعْظَمُ دَرَجَةً عِنْدَ اللهِ وَأُولئِكَ هُمُ الْفائِزُونَ (20) يُبَشِّرُهُمْ رَبُّهُمْ بِرَحْمَةٍ مِنْهُ وَرِضْوانٍ وَجَنَّاتٍ لَهُمْ فِيها نَعِيمٌ مُقِيمٌ (21) خالِدِينَ فِيها أَبَداً إِنَّ اللهَ عِنْدَهُ أَجْرٌ عَظِيمٌ (22) كانت لا تتحمل اجتماع خلق كثير عليها.` },
            { text: "ٱلَّذِينَ ءَامَنُوا۟ وَهَاجَرُوا۟ وَجَٰهَدُوا۟ فِى سَبِيلِ ٱللَّهِ بِأَمْوَٰلِهِمْ وَأَنفُسِهِمْ أَعْظَمُ دَرَجَةً عِندَ ٱللَّهِ وَأُو۟لَٰٓئِكَ هُمُ ٱلْفَآئِزُونَ", tafsir: `بالله وبرسوله ( وَهاجَرُوا ) من مكة إلى المدينة لأجل الإسلام ( وَجاهَدُوا فِي سَبِيلِ اللهِ ) بأن تحملوا المشاق ( بِأَمْوالِهِمْ وَأَنْفُسِهِمْ ) فبذلوا المال والنفس لإعلاء كلمة الله سبحانه ( أَعْظَمُ دَرَجَةً عِنْدَ اللهِ ) من الذين لم يفعلوا ذلك ، وإن سقوا الحجيج وعمروا المسجد ( وَأُولئِكَ هُمُ الْفائِزُونَ ) الظافرون المفلحون.` },
            { text: "يُبَشِّرُهُمْ رَبُّهُم بِرَحْمَةٍ مِّنْهُ وَرِضْوَٰنٍ وَجَنَّٰتٍ لَّهُمْ فِيهَا نَعِيمٌ مُّقِيمٌ", tafsir: `أي من عنده. والإتيان بكلمة « منه » لتعظيم قدر البشارة ( وَرِضْوانٍ ) أي رضاه سبحانه عنهم ، وهو أعظم بشارة ، فإن الإنسان إذا علم أن الملك ـ مثلا ـ راض عنه كان مرتاح الضمير مسرور الخاطر ، أما إذا علم أنه غاضب عليه كان بالعكس ، وإن أغدق عليه في العطاء ( وَجَنَّاتٍ لَهُمْ فِيها ) أي في تلك الجنات ( نَعِيمٌ مُقِيمٌ ) دائم لا يزول ولا يتحول.` },
            { text: "خَٰلِدِينَ فِيهَآ أَبَدًا إِنَّ ٱللَّهَ عِندَهُۥٓ أَجْرٌ عَظِيمٌ", tafsir: `فالجنات والنعيم كلاهما خالدان إلى ما لا نهاية ( إِنَّ اللهَ عِنْدَهُ أَجْرٌ عَظِيمٌ ) فليرغب الراغبون فيه. [23] وحيث ذكر سبحانه وجوب الجهاد في سبيله ، والهجرة من دار الكفر لأجله ، بيّن أنه يجب أن يتجرّد الإنسان من أقرب العلاقات إلى نفسه يا أَيُّهَا الَّذِينَ آمَنُوا لا تَتَّخِذُوا آباءَكُمْ وَإِخْوانَكُمْ أَوْلِياءَ إِنِ اسْتَحَبُّوا الْكُفْرَ عَلَى الْإِيمانِ وَمَنْ يَتَوَلَّهُمْ مِنْكُمْ فَأُولئِكَ هُمُ الظَّالِمُونَ (23) لأجله تعالى فقال : ( يا أَيُّهَا الَّذِينَ آمَنُوا لا تَتَّخِذُوا آباءَكُمْ وَإِخْوانَكُمْ أَوْلِياءَ ) بأن تتولّونهم ولاء صادرا من الأعماق ، وإن استحبّت معاشرتهم في الظاهر لقوله سبحانه : ( وَصاحِبْهُما فِي الدُّنْيا مَعْرُوفاً ) (1) ، ( إِنِ اسْتَحَبُّوا الْكُفْرَ عَلَى الْإِيمانِ ) أي آثروا الكفر واختاروه ( وَمَنْ يَتَوَلَّهُمْ ) أي الآباء والإخوان ( مِنْكُمْ ) فيقدّم ولايتهم على ولاية الله والرسول والمؤمنين ( فَأُولئِكَ هُمُ الظَّالِمُونَ ) الذين ظلموا أنفسهم حيث أوجبوا لها خزي الدنيا وعذاب الآخرة. و في بعض الأحاديث : إن الآية وردت في « حاطب بن أبي بلتعة » (2) فإن الرسول صلى‌الله‌عليه‌وآله‌وسلم لما أراد فتح مكة ، أمر أصحابه بكتمان الأمر حتى يفاجئ المسلمون الكفار ولا تراق الدماء ، فكتب حاطب إلى أهل مكة يخبرهم بخبر الرسول صلى‌الله‌عليه‌وآله‌وسلم وأطلع الله رسوله بالخبر ، فوبخ حاطبا ثم عفا عنه ، وأرجع الرسول الذي كان بيده الكتاب ، فكان كما أراد الرسول صلى‌الله‌عليه‌وآله‌وسلم من عدم وصول الخبر إليهم ، وقد قال حاطب معتذرا أن له أهلا في مكة فخاف أن تكون الدائرة على المسلمين ، فيكون له يد على الكفار ، ويسلم أهله من عقابهم وعذابهم. [24] ثم بيّن سبحانه ميزان الإيمان الصحيح ، وأنه لا يكون إلا بأن يرجّح ( 1) لقمان : 16. ( 2) راجع مجمع البيان : ج 5 ص 30. قُلْ إِنْ كانَ آباؤُكُمْ وَأَبْناؤُكُمْ وَإِخْوانُكُمْ وَأَزْواجُكُمْ وَعَشِيرَتُكُمْ وَأَمْوالٌ اقْتَرَفْتُمُوها وَتِجارَةٌ تَخْشَوْنَ كَسادَها وَمَساكِنُ تَرْضَوْنَها أَحَبَّ إِلَيْكُمْ مِنَ اللهِ وَرَسُولِهِ وَجِهادٍ فِي سَبِيلِهِ فَتَرَبَّصُوا حَتَّى يَأْتِيَ اللهُ بِأَمْرِهِ وَاللهُ لا يَهْدِي المؤمن كفّة الإيمان على جميع الشؤون والاعتبارات ( قُلْ ) يا رسول الله للمسلمين : ( إِنْ كانَ آباؤُكُمْ وَأَبْناؤُكُمْ ) واللفظان يشملان الأجداد والأحفاد ( وَإِخْوانُكُمْ ) الأعم من الأخوات ( وَأَزْواجُكُمْ ) اللاتي عقدتم عليهن ( وَعَشِيرَتُكُمْ ) أقاربكم غير من ذكروا ، كالأعمام والأخوال ومن أشبههما ( وَأَمْوالٌ اقْتَرَفْتُمُوها ) جمعتموها وكسبتموها ( وَتِجارَةٌ تَخْشَوْنَ كَسادَها ) تخشون أن تكسد ولا تدار ، إن اشتغلتم بطاعة الله سبحانه ( وَمَساكِنُ تَرْضَوْنَها ) بأن تحبون المقام فيها ، سواء كانت بلادا أو بيوتا ( أَحَبَّ إِلَيْكُمْ ) وأقرب إلى نفوسكم ( مِنَ اللهِ وَرَسُولِهِ ) من طاعته وطاعة رسوله ( وَ ) أحب إليكم من ( جِهادٍ فِي سَبِيلِهِ ) أي سبيل الله ، فإذا دار الأمر بين ترجيح رضاه سبحانه أو رضا رسوله وبين ذلك المحبوب لديكم من مال وقرابة قدمتموه عليها ( فَتَرَبَّصُوا ) انتظروا. وهذا تهديد ، أي انتظروا العقاب فإنكم لستم من الله في شيء. وكيف يدّعي الإنسان الإيمان وهو يقدّم تلك الأمور على أمر الله تعالى ( حَتَّى يَأْتِيَ اللهُ بِأَمْرِهِ ) فإنكم لا خير فيكم ، وإنما يأتي بأمر الله غيركم ، كما يقال : « إن كنت لا تفعل هذا فانتظر حتى يأتي غيرك ليفعله » ، فإن الله سبحانه غني عنكم فهو القادر على أن ينفذ أوامره بواسطة أناس غيركم ( وَاللهُ لا يَهْدِي الْقَوْمَ الْفاسِقِينَ (24) الْقَوْمَ الْفاسِقِينَ ) فإن من خرج عن طاعة الله بالفسق ، بعد العلم والعرفان ، يطبع على قلبه فلا يلطف به سبحانه ألطافه الخاصة. [25] ثم بيّن سبحانه مصداقا من مصاديق إتيان الله بأمره ، بعد ما اختار المسلمون الحياة ، وفرّوا من الله والرسول ، في وقعة « حنين » التي كانت قريبة إلى مشاعرهم وأفكارهم عند نزول هذه السورة. وقصة هذه الغزوة باختصار : أن الرسول صلى‌الله‌عليه‌وآله‌وسلم لما فتح مكة خاف الكفار الذين كانوا مبثوثين في الجزيرة أن يأتي الرسول صلى‌الله‌عليه‌وآله‌وسلم على آخرهم فاجتمع هناك جموع كثيرة من هوازن وغيرها ربما بلغ عددهم ثلاثين ألفا ، وساقوا معهم أموالهم ونساءهم وذراريهم ومروا حتى بلغوا « أوطاس » يريدون قتال الرسول صلى‌الله‌عليه‌وآله‌وسلم فبلغه صلى‌الله‌عليه‌وآله‌وسلم خبر اجتماعهم هناك ، فجمع القبائل ورغّبهم في الجهاد ووعدهم النصر وأن الله وعده أن يغنمهم أموالهم ونساءهم وذراريهم ، فرغب الناس وخرجوا كل قبيلة وفئة تحت راية ، وعقد اللواء الأكبر للإمام أمير المؤمنين عليه‌السلام وخرج صلى‌الله‌عليه‌وآله‌وسلم في اثني عشر ألف رجل. فلمّا صلّى الغداة انحدر في وادي حنين والجو لا زال مظلما ، وقد كانت هوازن قد سبقوا المسلمين من الليل وكمنوا في أطراف الجبال ، وحنين واد كثير الانحدار ، فلما انحدر جيش الرسول صلى‌الله‌عليه‌وآله‌وسلم في الوادي ، وقد كان أول من انحدر بنو سليم معهم خالد بن الوليد ، وكانوا غافلين عن اختفاء هوازن ، وإذا بهم يرشقون بالسهام كقطر المطر من كل جانب دون أن يروا أحدا وظهرت كتائب هوازن من كل ناحية ، فانهزم بنو سليم ، وكسرت بانكسارهم سائر جيوش الرسول صلى‌الله‌عليه‌وآله‌وسلم وفروا صعدا في الجبال والوديان ، وبقي الرسول صلى‌الله‌عليه‌وآله‌وسلم وأمير المؤمنين وجماعة يعدون بالأصابع من أولاد العباس وغيرهم. و أخذ الرسول صلى‌الله‌عليه‌وآله‌وسلم ينادي : يا معشر الأنصار إليّ وأنا رسول الله. وقد التفت كتائب هوازن به يريدون قتله والإمام يضرب بالسيف يمنة ويسرة ، فلم يبق من المسلمين أحد فقال صلى‌الله‌عليه‌وآله‌وسلم للعباس : اصعد هذا الطرب وناد : « يا أصحاب سورة البقرة » و « يا أصحاب بيعة الشجرة » إلى أين تفرون هذا رسول الله ؟ وقد كان العباس رفيع الصوت ، ثم رفع يده فقال صلى‌الله‌عليه‌وآله‌وسلم : اللهم لك الحمد ، وإليك المشتكى ، وأنت المستعان ، فنزل جبرائيل فقال : دعوت بما دعا به موسى حيث فلق الله له البحر ونجاه من فرعون ، ثم أخذ كفا من حصى فرماه في وجوه المشركين قائلا : « شاهت الوجوه ، ثم رفع رأسه إلى السماء وقال : اللهم إن تهلك هذه العصابة لم تعبد ، وإن شئت أن لا تعبد لا تعبد » ، فلما سمعت الأنصار نداء العباس عطفوا وكسروا جفون سيوفهم وهم يقولون : لبيك ، ومروا برسول الله واستحيوا أن يرجعوا إليه. فالتحقوا بالراية ونزل النصر من السماء وانهزمت هوازن وكانوا يسمعون قعقعة السلاح في الجو ، ولما فر الكفار غنم المسلمون غنائم كثيرة من أموالهم ونسائهم وذراريهم ، وقسمها الرسول صلى‌الله‌عليه‌وآله‌وسلم (1) . أقول : المراد ب « أصحاب سورة البقرة » إشارة إلى قوله تعالى في سورة البقرة : ( أَ لَمْ تَرَ إِلَى الْمَلَإِ مِنْ بَنِي إِسْرائِيلَ مِنْ بَعْدِ مُوسى ) (2) ، الذين طلبوا ( 1) بحار الأنوار : ج 21 ص 149. ( 2) البقرة : 247. لَقَدْ نَصَرَكُمُ اللّهُ فِي مَوَاطِنَ كَثِيرَةٍ وَيَوْمَ حُنَيْنٍ إِذْ أَعْجَبَتْكُمْ كَثْرَتُكُمْ فَلَمْ تُغْنِ عَنكُمْ شَيْئًا وَضَاقَتْ عَلَيْكُمُ الأَرْضُ بِمَا رَحُبَتْ ثُمَّ وَلَّيْتُم مُّدْبِرِينَ (25) جهاد الكفار ثم ( فَلَمَّا كُتِبَ عَلَيْهِمُ الْقِتالُ تَوَلَّوْا ) (1) يعني : أنكم أيها المسلمون صرتم كأولئك ، والمراد ب « أصحاب بيعة الشجرة » أن الرسول صلى‌الله‌عليه‌وآله‌وسلم حين صلح الحديبية اتكأ على شجرة وبايع المسلمين من جديد ، ليمتثلوا أوامره ، كأنه ما كانت كما قال سبحانه : ( إِذْ يُبايِعُونَكَ تَحْتَ الشَّجَرَةِ ) (2) . ( لَقَدْ نَصَرَكُمُ اللهُ ) أيها المسلمون ( فِي مَواطِنَ كَثِيرَةٍ ) في بعض الأخبار أنها كانت ثمانين ( وَيَوْمَ حُنَيْنٍ ) أي : ونصركم في يوم حنين ، وتخصيصه بالذكر لأنه لو لا نصرة الله سبحانه لم يكن لهم نصر حسب الظاهر بعد فرارهم وانهزامهم ( إِذْ أَعْجَبَتْكُمْ كَثْرَتُكُمْ ) فإنه لم يتفق لجيش المسلمين أن يكونوا اثني عشر ألفا قبل ذلك ، وقد قال بعضهم : لن نغلب اليوم من قلة ، لما رأوا من كثرتهم المدهشة في الجيش ( فَلَمْ تُغْنِ ) الكثرة ( عَنْكُمْ شَيْئاً ) أي لم تفدكم الكثرة ( وَضاقَتْ عَلَيْكُمُ الْأَرْضُ بِما رَحُبَتْ ) أي برحبها وسعتها ، و « الباء » بمعنى مع ، أي مع كونها وسيعة فسيحة ضاقت عليكم ، فإن الإنسان إذا خاف ، يرى في نفسه ضيق الأرض ، بالإضافة إلى أنهم لم يجدوا موضعا للفرار ، لاحتمال وجود العدو في كل مكان ( ثُمَّ وَلَّيْتُمْ مُدْبِرِينَ ) أي انهزمتم من عدوكم ، وأعطيتم أدباركم للعدو ، وقد كان الخطأ من المسلمين ( 1) البقرة : 247. ( 2) الفتح : 19. ثُمَّ أَنْزَلَ اللهُ سَكِينَتَهُ عَلى رَسُولِهِ وَعَلَى الْمُؤْمِنِينَ وَأَنْزَلَ جُنُوداً لَمْ تَرَوْها أنهم لم يثبتوا أول الأمر ، فإن الثبات أول الأمر خليق بأن يكشف النازلة ، كما أنهم أخطئوا حين اغتروا بكثرتهم ، فإن الإنسان إذا رأى كثرة من معه تقوى فيه روح الاتكالية ، وذلك خليق بانهزامه. ثم إن مقدمة الجيش لم تتخذ احتياطاتها اللازمة ، فإن دخول مثل هذا الموضع مما يحيط به الجبال يحتاج إلى إرسال بعض القوات الاستطلاعية.` },
            { text: "يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تَتَّخِذُوٓا۟ ءَابَآءَكُمْ وَإِخْوَٰنَكُمْ أَوْلِيَآءَ إِنِ ٱسْتَحَبُّوا۟ ٱلْكُفْرَ عَلَى ٱلْإِيمَٰنِ وَمَن يَتَوَلَّهُم مِّنكُمْ فَأُو۟لَٰٓئِكَ هُمُ ٱلظَّٰلِمُونَ", tafsir: `` },
            { text: "قُلْ إِن كَانَ ءَابَآؤُكُمْ وَأَبْنَآؤُكُمْ وَإِخْوَٰنُكُمْ وَأَزْوَٰجُكُمْ وَعَشِيرَتُكُمْ وَأَمْوَٰلٌ ٱقْتَرَفْتُمُوهَا وَتِجَٰرَةٌ تَخْشَوْنَ كَسَادَهَا وَمَسَٰكِنُ تَرْضَوْنَهَآ أَحَبَّ إِلَيْكُم مِّنَ ٱللَّهِ وَرَسُولِهِۦ وَجِهَادٍ فِى سَبِيلِهِۦ فَتَرَبَّصُوا۟ حَتَّىٰ يَأْتِىَ ٱللَّهُ بِأَمْرِهِۦ وَٱللَّهُ لَا يَهْدِى ٱلْقَوْمَ ٱلْفَٰسِقِينَ", tafsir: `` },
            { text: "لَقَدْ نَصَرَكُمُ ٱللَّهُ فِى مَوَاطِنَ كَثِيرَةٍ وَيَوْمَ حُنَيْنٍ إِذْ أَعْجَبَتْكُمْ كَثْرَتُكُمْ فَلَمْ تُغْنِ عَنكُمْ شَيْـًٔا وَضَاقَتْ عَلَيْكُمُ ٱلْأَرْضُ بِمَا رَحُبَتْ ثُمَّ وَلَّيْتُم مُّدْبِرِينَ", tafsir: `` },
            { text: "ثُمَّ أَنزَلَ ٱللَّهُ سَكِينَتَهُۥ عَلَىٰ رَسُولِهِۦ وَعَلَى ٱلْمُؤْمِنِينَ وَأَنزَلَ جُنُودًا لَّمْ تَرَوْهَا وَعَذَّبَ ٱلَّذِينَ كَفَرُوا۟ وَذَٰلِكَ جَزَآءُ ٱلْكَٰفِرِينَ", tafsir: `أي السكون النفسي الذي يزول الخوف معه ، فإن أقوى أسباب الهزيمة في كل ميدان ، تزلزل النفس وعدم اطمئنانها بالنصر ، أما إذا قويت النفس على تحمّل المكروه كان الإنسان خليقا بالنصر ( وَعَلَى الْمُؤْمِنِينَ ) الذين بقوا معه ولم ينهزموا. فقد بقي مع الرسول تسعة من بني هاشم أولهم أمير المؤمنين عليه‌السلام كما بقي ابن أم أيمن وقد قتل في ذلك اليوم ، أو المراد : المؤمنين حين رجوعهم إلى الرسول ، فإن الجيش الذي يفر إذا فكر في العاقبة تقوى نفسه بإذن الله سبحانه ( وَأَنْزَلَ جُنُوداً لَمْ تَرَوْها ) فقد أنزل الله سبحانه أفواجا من الملائكة لنصرة المؤمنين. وهذا ليس بغريب ، فقد وعد سبحانه بنصرة الملائكة لكل من استقام فكيف بالنبي صلى‌الله‌عليه‌وآله‌وسلم قال سبحانه : ( الَّذِينَ قالُوا رَبُّنَا اللهُ ثُمَّ اسْتَقامُوا تَتَنَزَّلُ عَلَيْهِمُ الْمَلائِكَةُ ) (1) . وقد ورد : أن رجلا من المشركين قال للمؤمنين ، وهو أسير في أيديهم : أين الخيل البلق والرجال عليهم الثياب البيض ، فإنما كان قتلنا ( 1) فصلت : 31. وَعَذَّبَ الَّذِينَ كَفَرُوا وَذلِكَ جَزاءُ الْكافِرِينَ (26) ثُمَّ يَتُوبُ اللهُ مِنْ بَعْدِ ذلِكَ عَلى مَنْ يَشاءُ وَاللهُ غَفُورٌ رَحِيمٌ (27) يا أَيُّهَا الَّذِينَ آمَنُوا إِنَّمَا الْمُشْرِكُونَ نَجَسٌ بأيديهم وما كنا نراكم فيهم إلا كهيئة الشامة. قالوا : تلك الملائكة ( وَعَذَّبَ ) الله ( الَّذِينَ كَفَرُوا ) بالقتل والأسر ( وَذلِكَ ) العذاب ( جَزاءُ الْكافِرِينَ ) الذين يكفرون بالله وآياته.` },
            { text: "ثُمَّ يَتُوبُ ٱللَّهُ مِنۢ بَعْدِ ذَٰلِكَ عَلَىٰ مَن يَشَآءُ وَٱللَّهُ غَفُورٌ رَّحِيمٌ", tafsir: `بعد تمام الأمر ( يَتُوبُ اللهُ مِنْ بَعْدِ ذلِكَ عَلى مَنْ يَشاءُ ) من الكفار إذا أسلموا ، وذكر « على من يشاء » لإفادة أن التوبة ليست واجبة ، أو المراد : من يشاء من المنهزمين ، فإن الفرار من الزحف كبيرة موبقة ، وقد شاء سبحانه أن يتوب على المؤمنين دون المنافقين ( وَاللهُ غَفُورٌ ) يستر الذنوب ( رَحِيمٌ ) يتفضّل بالرحمة عليهم.` },
            { text: "يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِنَّمَا ٱلْمُشْرِكُونَ نَجَسٌ فَلَا يَقْرَبُوا۟ ٱلْمَسْجِدَ ٱلْحَرَامَ بَعْدَ عَامِهِمْ هَٰذَا وَإِنْ خِفْتُمْ عَيْلَةً فَسَوْفَ يُغْنِيكُمُ ٱللَّهُ مِن فَضْلِهِۦٓ إِن شَآءَ إِنَّ ٱللَّهَ عَلِيمٌ حَكِيمٌ", tafsir: `النجاسة في الشريعة هي القذارة التي توجب الغسل للشيء الذي يباشره برطوبة ، وهذه النجاسة قد تكون لأضرار خارجية كالبول والغائط ، وقد تكون لأضرار معنوية كالكافر ، فإنه وإن كان نظيف الجسم إلا أن معتقده الباطل أوجب الحكم بنجاسته. وذلك خير وقاية للمسلمين من أن يتلوثوا بعقيدته ، فإنهم إذا عرفوه نجسا حتى أنه يجب الاجتناب عنه في المأكل والملبس وأنه مهما باشر شيئا برطوبة تنجس فورا منه ، اجتنبوا عنه ، فلا يتعدّى إليهم ما انطوى عليه من العقيدة الباطلة ، وهو ـ بدوره ـ إذ يعرف أنه عند المسلمين نجس لا بد وأن يسأل عن السبب ويريد إزالة هذه الوصمة ، ولدي تحقيق ذلك تظهر له خرافة معتقده مما يدعوه أن يتركها ويعتقد بالعقيدة الصحيحة. فَلا يَقْرَبُوا الْمَسْجِدَ الْحَرامَ بَعْدَ عامِهِمْ هذا وَإِنْ خِفْتُمْ عَيْلَةً فَسَوْفَ يُغْنِيكُمُ اللهُ وهناك بعض المتفلسفين يقولون : كيف يحكم بنجاسة إنسان ، ولزوم الاجتناب عنه ، لمجرد انحراف عقيدة ، وهذا مناف لحرية الآراء ؟ والجواب : إنه كيف يحكم بالاجتناب عن إنسان لمجرد أنه مصاب بالجذام ونحوه ، لمجرد انحراف مزاج ، وهذا مناف لكرامة الإنسان ، فإذا كان الخوف على الجسم يبيح الاجتناب فالخوف على الروح أولى بالإباحة. ( فَلا يَقْرَبُوا الْمَسْجِدَ الْحَرامَ ) والمراد : عدم دخوله ، والمسجد الحرام من باب المورد ، فإن عليا عليه‌السلام أمر بحكم الرسول صلى‌الله‌عليه‌وآله‌وسلم أن ينادي : « لا يحج بعد هذا العام مشرك» (1) . وإن قيل : فكيف دخل وفد نجران مسجد الرسول صلى‌الله‌عليه‌وآله‌وسلم ؟ نقول : إنه قبل نزول هذا الحكم ، فإن الأحكام نزلت تدريجا ، أما القول بأن النصارى ليسوا بمشركين. فهو خلاف قوله تعالى : ( سُبْحانَهُ عَمَّا يُشْرِكُونَ ) (2) ، وقوله : ( لَقَدْ كَفَرَ الَّذِينَ قالُوا إِنَّ اللهَ ثالِثُ ثَلاثَةٍ ) (3) ، وقوله : ( أَ أَنْتَ قُلْتَ لِلنَّاسِ اتَّخِذُونِي وَأُمِّي إِلهَيْنِ ) (4) . ( بَعْدَ عامِهِمْ هذا ) في السنين المقبلة ( وَإِنْ خِفْتُمْ عَيْلَةً ) أي فقرا ، فقد كان المنع عن المشركين يضر باقتصاد أهل مكة حيث أن كثيرا من وارداتهم كانت من الحجاج المشركين ( فَسَوْفَ يُغْنِيكُمُ اللهُ ( 1) وسائل الشيعة : ج 13 ص 400. ( 2) التوبة : 31. ( 3) المائدة : 74. ( 4) المائدة : 117. مِنْ فَضْلِهِ إِنْ شاءَ إِنَّ اللهَ عَلِيمٌ حَكِيمٌ (28) قاتِلُوا الَّذِينَ لا يُؤْمِنُونَ بِاللهِ وَلا بِالْيَوْمِ الْآخِرِ وَلا يُحَرِّمُونَ ما حَرَّمَ اللهُ وَرَسُولُهُ وَلا يَدِينُونَ دِينَ الْحَقِّ مِنَ الَّذِينَ أُوتُوا الْكِتابَ مِنْ فَضْلِهِ ) وقد وفى سبحانه بما وعد ، فقد أسلم أهل اليمن وحملوا إليهم الميرة والطعام عوض المشركين ، كما أسلم أهل الآفاق وحجوا وأغنوا أهل مكة أكثر من إغناء المشركين. أما هذه الأيام فإن آبار الذهب الأسود قد أوصلت مستواهم الاقتصادي إلى علوّ مدهش ( إِنْ شاءَ ) للدلالة على أن الأمور بيده سبحانه ، ولسوقهم إلى رجائه والسؤال منه والخضوع والضراعة إليه. ( إِنَّ اللهَ عَلِيمٌ ) بالمصالح ، فإن منعه عن حج المشركين إنما هو عن علم ( حَكِيمٌ ) يضع الأمور في مواضعها ويأمر بها حسب المصالح الكامنة ، وإن لم يعرف الناس تلك المصالح فورا.` },
            { text: "قَٰتِلُوا۟ ٱلَّذِينَ لَا يُؤْمِنُونَ بِٱللَّهِ وَلَا بِٱلْيَوْمِ ٱلْـَٔاخِرِ وَلَا يُحَرِّمُونَ مَا حَرَّمَ ٱللَّهُ وَرَسُولُهُۥ وَلَا يَدِينُونَ دِينَ ٱلْحَقِّ مِنَ ٱلَّذِينَ أُوتُوا۟ ٱلْكِتَٰبَ حَتَّىٰ يُعْطُوا۟ ٱلْجِزْيَةَ عَن يَدٍ وَهُمْ صَٰغِرُونَ", tafsir: `أيها المسلمون ( الَّذِينَ لا يُؤْمِنُونَ بِاللهِ ) إيمانا صحيحا ، وإن آمنوا به إيمان شرك ونحوه ( وَلا بِالْيَوْمِ الْآخِرِ ) إيمانا صحيحا ، وإن آمنوا به إيمانا منحرفا ، كأهل الكتاب الذين قالوا : ( لَنْ تَمَسَّنَا النَّارُ إِلَّا أَيَّاماً مَعْدُودَةً ) (1) ، ( وَلا يُحَرِّمُونَ ما حَرَّمَ اللهُ وَرَسُولُهُ ) المراد بالرسول : إما الأعم ، فإنهم لا يحرّمون المحرمات التي أتى بها موسى وعيسى عليهما‌السلام ، أو الأخص يعني محمدا صلى‌الله‌عليه‌وآله‌وسلم ( وَلا يَدِينُونَ دِينَ الْحَقِ ) أي لا يتخذونه دينا ، والمراد به الإسلام ( مِنَ الَّذِينَ أُوتُوا الْكِتابَ ) ( 1) البقرة : 81. حَتَّى يُعْطُوا الْجِزْيَةَ عَنْ يَدٍ وَهُمْ صاغِرُونَ (29) وصف ل « الذين لا يؤمنون » ( حَتَّى يُعْطُوا الْجِزْيَةَ ) هي « فعلة » من « جزى يجزي » مثل « العقدة » و « الجلسة » ، وهي عطية مخصوصة ، كأنها جزاء لهم على بقائهم على الكفر ، أو جزاء للمسلمين عوض حمايتهم لهم ، فإن الذمي في بلاد الإسلام يكون محترم المال والنفس موفّر الحرمة والكرامة ( عَنْ يَدٍ ) أي يسلمونها بأيديهم ، كما يقال : « كلمته وجها بوجه » ( وَهُمْ صاغِرُونَ ) أي أذلاء من « الصغار » . إن أهل الكتاب حيث انحرفت عقيدتهم حتى جعلوا الخرافة في معتقدهم ، وحيث حرفوا كتبهم حتى نسبوا الزنا والكفر وشرب الخمر والقسوة وشبهها إلى أنبيائهم ، وحيث هدموا نظم الله سبحانه ليجعلوا مكانها أنظمة مخترعة ، استحق الإسلام أن يشعرهم بشيء من الذلة ليتركوا الباطل إلى الحق ، فإن الإنسان لا يرضى أن يبقى ذليلا ، لكنه احترمهم حيث أقرّ بهم وسمح لهم بالبقاء تحت ظله ، باحترام اسم الكتاب ، وهذا الإذلال لا ينافي الحرية في شيء ، أ رأيت من ينحرف في سلوك أو أخلاق هل يستحق ما يستحقه المستقيم ؟ وليس الميزان في تقييم الإنسان الذي يراعي جهتي المادة والروح واقعا ، هو النظر إلى صورته البشرية ، بل الصورة والسيرة ، فمن انحرفت سيرته لم تنفعه صورته. فهرب بعض المفسرين ومن إليهم عن الحكم على طبق هذه الآية أو ما أشبهها خروج عن الواقع الإسلامي ، كما هو خروج عن الموازين البشرية الرفيعة التي تجعل للروح قسطا في تقييم الإنسان كما أن للبدن قسطا. [30] ثم بيّن سبحانه طرفا من أقوال أهل الكتاب وافتراءاتهم على الله وَقالَتِ الْيَهُودُ عُزَيْرٌ ابْنُ اللهِ وَقالَتِ النَّصارى الْمَسِيحُ ابْنُ اللهِ ذلِكَ قَوْلُهُمْ بِأَفْواهِهِمْ يُضاهِؤُنَ قَوْلَ الَّذِينَ كَفَرُوا مِنْ قَبْلُ قاتَلَهُمُ اللهُ أَنَّى يُؤْفَكُونَ (30) سبحانه ( وَقالَتِ الْيَهُودُ عُزَيْرٌ ابْنُ اللهِ وَقالَتِ النَّصارى الْمَسِيحُ ابْنُ اللهِ ) وبهذا الانحراف خرجوا عن زمرة الموحّدين ، فإن الله لا يمكن أن يكون له ولد إذ ليس جسما يلد ، كما وصف تعالى نفسه بقوله : ( قُلْ هُوَ اللهُ أَحَدٌ* اللهُ الصَّمَدُ* لَمْ يَلِدْ وَلَمْ يُولَدْ* وَلَمْ يَكُنْ لَهُ كُفُواً أَحَدٌ ) (1) ( ذلِكَ قَوْلُهُمْ بِأَفْواهِهِمْ ) إن ألسنتهم اخترعت هذا القول بلا استناد إلى كتاب منزل أو دليل مبين. و « أفواه » جمع « فوه » ، بمعنى : الفم ( يُضاهِؤُنَ ) أي يشبه قول هؤلاء اليهود والنصارى ، في هذه المقالة ( قَوْلَ الَّذِينَ كَفَرُوا ) الذين يجعلون لله شريكا ، فإن كلا القولين تشبيه لا يليق بجلال الله سبحانه ، فإن من له شريك إنما هو كمن له ولد في أنه مخلوق ليس بإله ، وإنما كان التشبيه شركا لأن الشبيه يشارك شبهه في أمر جامع ويفترق عنه في أمور مميزة ، وبذلك يكون مركبا ، والمركب ليس بإله ( مِنْ قَبْلُ ) وهذا توبيخ لهم ، فإن الأنبياء يأتون لقلع جذور الكفر فإذا ارتدت الأمة إلى مقالة الكفار الذين جاء الأنبياء لمحقهم ، كانت معرضة عن الأنبياء ، وتبيّن أن كلام الأنبياء لم يؤثر فيهم ( قاتَلَهُمُ اللهُ ) دعاء عليهم بالهلاك ، فإن المفسد يدعى عليه بالموت ليستريح الناس من شره ( أَنَّى يُؤْفَكُونَ ) أي كيف يصرفون عن ( 1) سورة الإخلاص : 2 ـ 5. اتَّخَذُوا أَحْبارَهُمْ وَرُهْبانَهُمْ أَرْباباً مِنْ دُونِ اللهِ وَالْمَسِيحَ ابْنَ مَرْيَمَ وَما أُمِرُوا الحق إلى الإفك الذي هو الكذب. [31] ثم بيّن سبحانه سببا آخر لكفرهم ، أنهم أعطوا حق التشريع أي التحليل والتحريم إلى علمائهم ، مع العلم أن هذا الحق خاص بالله سبحانه ( وَمَنْ لَمْ يَحْكُمْ بِما أَنْزَلَ اللهُ فَأُولئِكَ هُمُ الْكافِرُونَ ) (1) ، ( اتَّخَذُوا ) أي اتخذ اليهود والنصارى ( أَحْبارَهُمْ ) جمع « حبر » وهو العالم ( وَرُهْبانَهُمْ ) جمع « راهب » وهو العابد ( أَرْباباً مِنْ دُونِ اللهِ ) أي مع الله ، فإن أخذ الغير يعبّر عنه « من دون » وإن كان مع الأصل. قال عدي بن حاتم : أتيت رسول الله وفي عنقي صليب من ذهب ، فقال لي : يا عدي اطرح هذا الوثن من عنقك ، قال : فطرحته ثم انتهيت إليه وهو يقرأ من سورة براءة هذه الآية : ( اتَّخَذُوا أَحْبارَهُمْ وَرُهْبانَهُمْ أَرْباباً .. ) حتى فرغ منها. فقلت له : إنا لسنا نعبدهم. فقال : أليس يحرمون ما أحل الله فتحرمونه ، ويحلّون ما حرم الله فتستحلونه ؟ قال فقلت : بلى قال : فتلك عبادتهم (2) . أقول الشرك على أربعة أقسام : الشرك في ذات الله ، والشرك في صفاته ، والشرك في أفعاله ، والشرك في أمره ونهيه. فمن قال : إن له شريكا ، أو أن صفاته لغيره ، أو أن قسما من الخلق لسواه ، أو أنه يحق الأمر والنهي لغيره ، فهو مشرك. ( وَ ) اتخذوا ( الْمَسِيحَ ابْنَ مَرْيَمَ ) ربا من دون الله ( وَما أُمِرُوا ( 1) المائدة : 45. ( 2) بحار الأنوار : ج 9 ص 98. إِلاَّ لِيَعْبُدُوا إِلهاً واحِداً لا إِلهَ إِلاَّ هُوَ سُبْحانَهُ عَمَّا يُشْرِكُونَ (31) يُرِيدُونَ أَنْ يُطْفِؤُا نُورَ اللهِ بِأَفْواهِهِمْ وَيَأْبَى اللهُ إِلاَّ أَنْ يُتِمَّ نُورَهُ وَلَوْ كَرِهَ الْكافِرُونَ (32) هُوَ الَّذِي أَرْسَلَ رَسُولَهُ بِالْهُدى وَدِينِ الْحَقِّ إِلَّا لِيَعْبُدُوا إِلهاً واحِداً ) لا شريك له ، فقد كان أنبياؤهم يأمرونهم بذلك ( لا إِلهَ إِلَّا هُوَ ) أي ليس في الكون إله غيره ( سُبْحانَهُ ) أي أنزهه تنزيها ( عَمَّا يُشْرِكُونَ ) أي عن شركهم ، وجعلهم لله شريكا. [32] ومن صفات هؤلاء أنهم ( يُرِيدُونَ أَنْ يُطْفِؤُا نُورَ اللهِ ) القرآن الكريم أو أحكامه. وسمي نورا لأنه كما يهتدى بالنور في الظلمات ، كذلك يهتدى بالقرآن في دروب الحياة المظلمة ، فإن النور الظاهر لنفسه المظهر لغيره ، كذلك أحكام الله سبحانه وكتابه الحكيم ، ومعنى إرادتهم إطفائه ، أنهم يريدون أن ينطفئ فلا يضيء العالم به ( بِأَفْواهِهِمْ ) فكما يطفأ النور بالفم بسبب النفخ ، فإنهم يريدون إبطال كتاب الله بما يتقولون عليه ( وَيَأْبَى اللهُ إِلَّا أَنْ يُتِمَّ نُورَهُ ) أي يمنع الله ذلك إلا أن يظهر أمره ، وذلك بإظهار الكتاب والإسلام في جميع المجالات ( وَلَوْ كَرِهَ الْكافِرُونَ ) أي حتى مع كرههم وعدم إرادتهم. [33] وكيف يتمكن هؤلاء من إطفاء نور الإسلام والقرآن والحال أن الله سبحانه ( هُوَ الَّذِي أَرْسَلَ رَسُولَهُ ) أي محمدا صلى‌الله‌عليه‌وآله‌وسلم ( بِالْهُدى ) أي مع الهداية والإرشاد ، فإن الرسول حامل مشعل الهدى ( وَ ) ب ( دِينِ الْحَقِ ) لِيُظْهِرَهُ عَلَى الدِّينِ كُلِّهِ وَلَوْ كَرِهَ الْمُشْرِكُونَ (33) يا أَيُّهَا الَّذِينَ آمَنُوا إِنَّ كَثِيراً مِنَ الْأَحْبارِ وَالرُّهْبانِ لَيَأْكُلُونَ أَمْوالَ النَّاسِ بِالْباطِلِ وَيَصُدُّونَ عَنْ سَبِيلِ اللهِ الذي هو الإسلام ( لِيُظْهِرَهُ عَلَى الدِّينِ كُلِّهِ ) فيكون هو الدين الوحيد الذي له الغلبة والحجة على سائر الأديان. و في الأحاديث : إن تأويل هذه الآية عند خروج الإمام المهدي عليه‌السلام الذي يملأ الأرض قسطا وعدلا بعد أن تملأ ظلما وجورا (1) . ويكون عند ذلك الإسلام وحده دين العالم لا دين سواه ( وَلَوْ كَرِهَ الْمُشْرِكُونَ ) بأن كرهوا إعلاء هذا الدين على سائر الأديان. [34] ثم بيّن سبحانه بعض الصفات الذميمة الأخرى لأهل الكتاب بقوله : ( يا أَيُّهَا الَّذِينَ آمَنُوا ) وجّه الكلام إليهم لأنهم الذين يصدّقون بذلك ، أما سائر أهل الكتاب فإنهم يكذبون الخبر ، وإن علموا به باطنا ( إِنَّ كَثِيراً مِنَ الْأَحْبارِ ) وهم علماء أهل الكتاب ( وَالرُّهْبانِ ) وهم عبّادهم ( لَيَأْكُلُونَ أَمْوالَ النَّاسِ بِالْباطِلِ ) المراد ب « الأكل » التصرف ، فإن معظم التصرف لما كان بالأكل غلب على سائر التصرفات بعلاقة الجزء والكل ، والمراد ب « الباطل » بالرشوة ونحوها مما لا يحق لهم أكل الأموال بتلك الصور ( وَيَصُدُّونَ ) أي يمنعون ( عَنْ سَبِيلِ اللهِ ) فلا يتركون الناس أن يسلموا ويؤمنوا بالرسول صلى‌الله‌عليه‌وآله‌وسلم . ثم إن الأحبار والرهبان يكنزون الذهب والفضة فليحذر المسلمون ( 1) بحار الأنوار : ج 51 ص 50. وَالَّذِينَ يَكْنِزُونَ الذَّهَبَ وَالْفِضَّةَ وَلا يُنْفِقُونَها فِي سَبِيلِ اللهِ فَبَشِّرْهُمْ بِعَذابٍ أَلِيمٍ (34) يَوْمَ يُحْمى عَلَيْها فِي نارِ جَهَنَّمَ فَتُكْوى بِها جِباهُهُمْ وَجُنُوبُهُمْ وَظُهُورُهُمْ هذا ما كَنَزْتُمْ لِأَنْفُسِكُمْ فَذُوقُوا ما كُنْتُمْ تَكْنِزُونَ (35) أن يكونوا مثلهم فيجازوا بجزائهم ( وَ ) ذلك فإن ( الَّذِينَ يَكْنِزُونَ الذَّهَبَ وَالْفِضَّةَ ) أي يجمعونها ولا يؤدون حقوقهما ـ لا الكنز المصطلح ـ ( وَلا يُنْفِقُونَها ) أي الكنوز ( فِي سَبِيلِ اللهِ ) كما أمر من إعطاء الزكاة والخمس ( فَبَشِّرْهُمْ بِعَذابٍ أَلِيمٍ ) أي مؤلم موجع ، وأتى بالبشارة مكان الإنذار استهزاء من استعمال الضد في ضده. [35] في ( يَوْمَ ) أي ذلك العذاب إنما هو في يوم ( يُحْمى عَلَيْها ) أي يوقد على تلك الكنوز ، فإن الشيء إذا أريد انصهاره إما يوقد تحته أو يوقد فوقه ( فِي نارِ جَهَنَّمَ ) فهي في النار وتوقد عليها النار ، حيث تنصهر تماما ( فَتُكْوى بِها ) أي بتلك الكنوز المحماة ( جِباهُهُمْ ) جمع « جبهة » ( وَجُنُوبُهُمْ ) جمع « جنب » ( وَظُهُورُهُمْ ) جمع « ظهر » ، وإنما خصّصت هذه المواضع لأن الجبهة محل الوسم ، والجنب محل الألم ، والظهر محل الحدود. وقيل : لأن صاحب المال إذا رأى الفقير قبض جبهته وطوى عنه كشحه ـ أي جنبه ـ وولّاه ظهره. ويقال لهم في حال الكي تعنيفا وتوبيخا : ( هذا ما كَنَزْتُمْ لِأَنْفُسِكُمْ ) هذا جزاؤه ، حيث لم تنفقوها في سبيل الله ( فَذُوقُوا ما كُنْتُمْ تَكْنِزُونَ ) أي ذوقوا عقابه ووباله وعاقبته. إِنَّ عِدَّةَ الشُّهُورِ عِنْدَ اللهِ اثْنا عَشَرَ شَهْراً فِي كِتابِ اللهِ يَوْمَ خَلَقَ السَّماواتِ وَالْأَرْضَ مِنْها أَرْبَعَةٌ حُرُمٌ ذلِكَ الدِّينُ الْقَيِّمُ [36] ولما أوجب سبحانه قتال الكفار وأهل الكتاب الذين انحرفوا ، بيّن أنه لا يحل القتال في الأشهر الحرم التي هي : ذو القعدة ، وذو الحجة ، ومحرم ، ورجب. فقد قرّر الله سبحانه السلام في هذه الأشهر ليستريح الناس فيها وليكونوا في أمن ، كما قرر السلام في الحرم ليكون مكانا للسلام ، وقد قدم على ذلك مقدمة هي عدة الشهور ، وأنها مرتبطة بدورة الفلك ( إِنَّ عِدَّةَ الشُّهُورِ عِنْدَ اللهِ ) حسب أمره وتقديره ( اثْنا عَشَرَ شَهْراً ) محرم ، وصفر ، وربيع الأول ، وربيع الثاني ، وجمادى الأولى ، وجمادى الآخرة ، ورجب ، وشعبان ، ورمضان ، وشوال ، وذو القعدة ، وذو الحجة ( فِي كِتابِ اللهِ ) أي ما كتبه وقرره ، وذلك طبق ناموس خلق الكون حيث دورة الفلك وسير الشمس والقمر ، وقد كانت الكتابة ( يَوْمَ خَلَقَ السَّماواتِ وَالْأَرْضَ ) فإنه من ذلك اليوم أجرى النيّرين المعدلين للشهور والسنوات. والظاهر من الأشهر ، الأشهر القمرية ، لأنها المتبادر لدى الشرع والمتشرعة. ( مِنْها ) أي من تلك الأشهر ( أَرْبَعَةٌ حُرُمٌ ) سمّي الشهر حراما ، لحرمة القتل والقتال فيه ، ولما له من الاحترام ، وقد كان كذلك قبل الإسلام أيضا ، حتى أن ولي الدم لو رأى قاتل أبيه لم يهجم عليه بسوء حتى ينقضي الشهر الحرام ( ذلِكَ ) الترتيب للأشهر ، والحرم منها ( الدِّينُ الْقَيِّمُ ) أي الطريقة القويمة المستقيمة ، لأنها مطابقة لناموس الخلق وحركة النيّرين ، ولأن السلام لا بد وأن يسود فترة من الزمن ، فَلا تَظْلِمُوا فِيهِنَّ أَنْفُسَكُمْ وَقاتِلُوا الْمُشْرِكِينَ كَافَّةً كَما يُقاتِلُونَكُمْ كَافَّةً وَاعْلَمُوا أَنَّ اللهَ مَعَ الْمُتَّقِينَ (36) حتى تهدأ النفوس ، وتزول الهموم منها ، فإن فترة الأشهر بغير ذلك فإنها لا تلائم الفطرة والخلق ( فَلا تَظْلِمُوا فِيهِنَ ) في تلك الأشهر الحرم ( أَنْفُسَكُمْ ) بخرق حرمتها ، فإن خرق حرمتها يوجب عقابا ونكالا. ( وَقاتِلُوا ) أيها المسلمون ( الْمُشْرِكِينَ كَافَّةً ) من غير فرق بين أقسامهم وأصنافهم ، و « كافة » بمعنى الإحاطة ، مأخوذة من « كافة الشيء » وهي حرفه ، وإذا انتهى الشيء إلى ذلك كفّ عن الزيادة ، وأصل الكف : المنع ، و « كافة » منصوبة على المصدر ( كَما يُقاتِلُونَكُمْ كَافَّةً ) أي أن قتالكم لهم إنما هو في مقابلة قتالهم لكم ( وَاعْلَمُوا أَنَّ اللهَ مَعَ الْمُتَّقِينَ ) فلا تفعلوا في الحرب ما ينافي التقوى ، فإن الله سبحانه مع الذين يتقون معاصيه ، ويمتثلون أوامره. [37] لما بيّن سبحانه حرمة أشهر الحرم الأربعة ، ذكر ما كان يفعله الجاهليون حيث كانوا يؤخرون تحريم الشهر الحرام إلى صفر حيثما شاءوا ذلك ، فيحرمون صفر ويستحلون المحرم ، ثم إذا انقضت حاجتهم أرجعوا الحرام إلى المحرم ، وكان يقوم بذلك رجل من كنانة يقال له نعيم بن ثعلبة ، وكان رئيس الموسم ، فيقول : أنا الذي لا أعاب ولا أجاب ولا يردّ لي قضاء. فيقولون : نعم صدقت ، أنسئنا شهرا أو أخّر عنا حرمة المحرم واجعلها في صفر ، وأحل المحرم. فيفعل ذلك ، فإنهم بذلك يريدون القتال في الحرم ، وهذا العمل يسمى إِنَّمَا النَّسِيءُ زِيادَةٌ فِي الْكُفْرِ يُضَلُّ بِهِ الَّذِينَ كَفَرُوا يُحِلُّونَهُ عاماً وَيُحَرِّمُونَهُ عاماً لِيُواطِؤُا عِدَّةَ ما حَرَّمَ اللهُ فَيُحِلُّوا ما حَرَّمَ اللهُ « نسيئا » فإن « أنسأ » بمعنى أخّر ، و « النسيء » بمعنى تأخير الشهر الحرام عن وقته. ( إِنَّمَا النَّسِيءُ زِيادَةٌ فِي الْكُفْرِ ) فإن المشركين كانوا كفارا حسب عقائدهم حول الإله. واليوم الآخر فتحليل الحرام وتحريم الحلال ، زيادة في الكفر ، لأن التشريع لله وحده ، فمن شرع في قبال الله سبحانه فهو كافر ( وَمَنْ لَمْ يَحْكُمْ بِما أَنْزَلَ اللهُ فَأُولئِكَ هُمُ الْكافِرُونَ ) (1) . ومن المعلوم أن الكفر والإيمان قابلان للزيادة والنقصان ( يُضَلُّ بِهِ الَّذِينَ كَفَرُوا ) أي يضل بسبب هذا النسيء الكفار ، أما غير الكفار فإنهم لا يتبعون إلا شريعة الله سبحانه فلا ضلال لهم بالنسيء ، ومعنى « يضلّ » ـ بالبناء للمفعول ـ أن النسيء يسبب انحرافهم عن جادة الهدى ( يُحِلُّونَهُ ) أي يحلون الشهر الحرام ( عاماً ) في عام فيجعلون المحرم حلالا ( وَيُحَرِّمُونَهُ عاماً ) فيمشون على الأصل في تحريم شهر محرم ، وذلك حين يحتاجون إلى القتال في المحرم يحلّلونه ، ويجعلون صفر بدله حراما ، وحين لا يحتاجون إلى القتال يكون المحرم على حاله في التحريم ، وإنما يقدمون الحرام ويؤخرونه ( لِيُواطِؤُا ) أي ليوافقوا ، يقال : « واطأ » في الشعر ، إذا قال بيتين على قافية واحدة ، ومثله « أوطأ » ( عِدَّةَ ما حَرَّمَ اللهُ فَيُحِلُّوا ما حَرَّمَ اللهُ ) أي ليكون تعداد الحرام بقدر ( 1) المائدة : 45. زُيِّنَ لَهُمْ سُوءُ أَعْمالِهِمْ وَاللهُ لا يَهْدِي الْقَوْمَ الْكافِرِينَ (37) تعداد الحرام الذي جعله الله ، فإنهم لا يحلون الشهر الحرام ، إلا وجعلوا مكانه شهرا آخر حراما ، وهذان عصيانان : تحليل الحرام ، وتحريم الحلال ( زُيِّنَ لَهُمْ سُوءُ أَعْمالِهِمْ ) فقد زين الشيطان في نظرهم الأعمال السيئة فلازموها وافتخروا بها ( وَاللهُ لا يَهْدِي الْقَوْمَ الْكافِرِينَ ) الذين يصرّون على الكفر بعد تبيّن الحق ، فإنه سبحانه لا يلطف بهم لطفه الخاص. [38] وفي سياق حكم الجهاد مع الأعراب يأتي دور الكلام حول جهاد الروم ، فإنه لما رجع رسول الله من الطائف أمر بالجهاد لغزو الروم ، وذلك في زمان إدراك الثمار فأحبوا المقام في مساكنهم وقريبا من أموالهم ، وشق عليهم الخروج إلى القتال ، وكان من عادته صلى‌الله‌عليه‌وآله‌وسلم أن يخفي الغزوة التي يريدها غالبا ، لئلّا يعرف العدو فيتخذ أهبته منها فيكثر القتلى ، ولذا كان إذا أراد الخروج نحو غزوة في الشمال ذهب مقدارا نحو الجنوب ثم انحنى صوب قصده إلا في هذه الغزوة حيث كانت الشقة بعيدة والعدو كثير ، فإنه صلى‌الله‌عليه‌وآله‌وسلم أخبر أصحابه بذلك ليتأهبوا ويأخذوا حذرهم ، وتسمى هذه الغزوة ب « تبوك » وقد بلغ رسول الله صلى‌الله‌عليه‌وآله‌وسلم أن الروم قد جمعوا له أطراف الجزيرة بالشام وأن هرقل قد رزق أصحابه رزق سنة ، وانضمت إليهم لخم وجذم وعاملة وغسان من قبائل العرب وقدموا مقدماتهم إلى البقاء. فاستنفر المسلمين لجهادهم ، وهنا وجد المنافقون فرصتهم لإظهار نواياهم فأخذوا يخذلون المسلمين ، قائلين : « لا تنفروا في الحر » فقد كان الهواء حارا ، يا أَيُّهَا الَّذِينَ آمَنُوا ما لَكُمْ إِذا قِيلَ لَكُمُ انْفِرُوا فِي سَبِيلِ اللهِ اثَّاقَلْتُمْ إِلَى الْأَرْضِ أَرَضِيتُمْ بِالْحَياةِ الدُّنْيا مِنَ الْآخِرَةِ فَما مَتاعُ الْحَياةِ الدُّنْيا فِي الْآخِرَةِ إِلاَّ قَلِيلٌ (38) إِلاَّ تَنْفِرُوا يُعَذِّبْكُمْ عَذاباً أَلِيماً وقالوا : إن السفر بعيد ، فلا طاقة لنا به ، والعدو الروم فلا قبل لنا بهم ، إلى غير ذلك من الأعذار الواهية. ( يا أَيُّهَا الَّذِينَ آمَنُوا ما لَكُمْ ) : أيّ نفع وفائدة تعود إليكم في التخلّف والعصيان ؟ ( إِذا قِيلَ لَكُمُ ) قال لكم الرسول : ( انْفِرُوا فِي سَبِيلِ اللهِ ) اخرجوا إلى مجاهدة المشركين في « تبوك » وهي من بلاد البلقاء ( اثَّاقَلْتُمْ إِلَى الْأَرْضِ ) « اثاقل » من تثاقل ، من باب « التفاعل » أبدلت تاؤه ثاء ، على القاعدة المشهورة في تاء « التفاعل » و « التفعّل » ثم جيء بالهمزة لاستحالة الابتداء بالساكن. أي : ملتم إلى البقاء في الأرض ، وعدم الخروج ، كأن الجسم قد ثقل أزيد من وزنه العادي فكلما رفع جذبه ثقله نحو الأرض ( أَ رَضِيتُمْ بِالْحَياةِ الدُّنْيا مِنَ الْآخِرَةِ ) الاستفهام إنكاري ، و « من » بمعنى البدل ، أي : هل رضيتم أيها المسلمون وآثرتم الحياة الفانية القريبة بدل الحياة الباقية الآخرة ( فَما مَتاعُ الْحَياةِ الدُّنْيا فِي الْآخِرَةِ ) بالنسبة إليها ( إِلَّا قَلِيلٌ ) فإن الدنيا قليلة ، والآخرة كثيرة ، فلا ترجّحوا القليل على الكثير ، وإذا تركتم الجهاد فاتتكم تلك المنافع الدائمة الخالدة.` },
            { text: "وَقَالَتِ ٱلْيَهُودُ عُزَيْرٌ ٱبْنُ ٱللَّهِ وَقَالَتِ ٱلنَّصَٰرَى ٱلْمَسِيحُ ٱبْنُ ٱللَّهِ ذَٰلِكَ قَوْلُهُم بِأَفْوَٰهِهِمْ يُضَٰهِـُٔونَ قَوْلَ ٱلَّذِينَ كَفَرُوا۟ مِن قَبْلُ قَٰتَلَهُمُ ٱللَّهُ أَنَّىٰ يُؤْفَكُونَ", tafsir: `` },
            { text: "ٱتَّخَذُوٓا۟ أَحْبَارَهُمْ وَرُهْبَٰنَهُمْ أَرْبَابًا مِّن دُونِ ٱللَّهِ وَٱلْمَسِيحَ ٱبْنَ مَرْيَمَ وَمَآ أُمِرُوٓا۟ إِلَّا لِيَعْبُدُوٓا۟ إِلَٰهًا وَٰحِدًا لَّآ إِلَٰهَ إِلَّا هُوَ سُبْحَٰنَهُۥ عَمَّا يُشْرِكُونَ", tafsir: `` },
            { text: "يُرِيدُونَ أَن يُطْفِـُٔوا۟ نُورَ ٱللَّهِ بِأَفْوَٰهِهِمْ وَيَأْبَى ٱللَّهُ إِلَّآ أَن يُتِمَّ نُورَهُۥ وَلَوْ كَرِهَ ٱلْكَٰفِرُونَ", tafsir: `` },
            { text: "هُوَ ٱلَّذِىٓ أَرْسَلَ رَسُولَهُۥ بِٱلْهُدَىٰ وَدِينِ ٱلْحَقِّ لِيُظْهِرَهُۥ عَلَى ٱلدِّينِ كُلِّهِۦ وَلَوْ كَرِهَ ٱلْمُشْرِكُونَ", tafsir: `` },
            { text: "يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِنَّ كَثِيرًا مِّنَ ٱلْأَحْبَارِ وَٱلرُّهْبَانِ لَيَأْكُلُونَ أَمْوَٰلَ ٱلنَّاسِ بِٱلْبَٰطِلِ وَيَصُدُّونَ عَن سَبِيلِ ٱللَّهِ وَٱلَّذِينَ يَكْنِزُونَ ٱلذَّهَبَ وَٱلْفِضَّةَ وَلَا يُنفِقُونَهَا فِى سَبِيلِ ٱللَّهِ فَبَشِّرْهُم بِعَذَابٍ أَلِيمٍ", tafsir: `` },
            { text: "يَوْمَ يُحْمَىٰ عَلَيْهَا فِى نَارِ جَهَنَّمَ فَتُكْوَىٰ بِهَا جِبَاهُهُمْ وَجُنُوبُهُمْ وَظُهُورُهُمْ هَٰذَا مَا كَنَزْتُمْ لِأَنفُسِكُمْ فَذُوقُوا۟ مَا كُنتُمْ تَكْنِزُونَ", tafsir: `` },
            { text: "إِنَّ عِدَّةَ ٱلشُّهُورِ عِندَ ٱللَّهِ ٱثْنَا عَشَرَ شَهْرًا فِى كِتَٰبِ ٱللَّهِ يَوْمَ خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ مِنْهَآ أَرْبَعَةٌ حُرُمٌ ذَٰلِكَ ٱلدِّينُ ٱلْقَيِّمُ فَلَا تَظْلِمُوا۟ فِيهِنَّ أَنفُسَكُمْ وَقَٰتِلُوا۟ ٱلْمُشْرِكِينَ كَآفَّةً كَمَا يُقَٰتِلُونَكُمْ كَآفَّةً وَٱعْلَمُوٓا۟ أَنَّ ٱللَّهَ مَعَ ٱلْمُتَّقِينَ", tafsir: `` },
            { text: "إِنَّمَا ٱلنَّسِىٓءُ زِيَادَةٌ فِى ٱلْكُفْرِ يُضَلُّ بِهِ ٱلَّذِينَ كَفَرُوا۟ يُحِلُّونَهُۥ عَامًا وَيُحَرِّمُونَهُۥ عَامًا لِّيُوَاطِـُٔوا۟ عِدَّةَ مَا حَرَّمَ ٱللَّهُ فَيُحِلُّوا۟ مَا حَرَّمَ ٱللَّهُ زُيِّنَ لَهُمْ سُوٓءُ أَعْمَٰلِهِمْ وَٱللَّهُ لَا يَهْدِى ٱلْقَوْمَ ٱلْكَٰفِرِينَ", tafsir: `` },
            { text: "يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ مَا لَكُمْ إِذَا قِيلَ لَكُمُ ٱنفِرُوا۟ فِى سَبِيلِ ٱللَّهِ ٱثَّاقَلْتُمْ إِلَى ٱلْأَرْضِ أَرَضِيتُم بِٱلْحَيَوٰةِ ٱلدُّنْيَا مِنَ ٱلْـَٔاخِرَةِ فَمَا مَتَٰعُ ٱلْحَيَوٰةِ ٱلدُّنْيَا فِى ٱلْـَٔاخِرَةِ إِلَّا قَلِيلٌ", tafsir: `` },
            { text: "إِلَّا تَنفِرُوا۟ يُعَذِّبْكُمْ عَذَابًا أَلِيمًا وَيَسْتَبْدِلْ قَوْمًا غَيْرَكُمْ وَلَا تَضُرُّوهُ شَيْـًٔا وَٱللَّهُ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ", tafsir: `أي : إن لا تخرجوا إلى القتال الذي دعاكم إليه الرسول ( يُعَذِّبْكُمْ ) الله ( عَذاباً أَلِيماً ) مؤلما موجعا في الدنيا من قبل الكفار ، وَيَسْتَبْدِلْ قَوْماً غَيْرَكُمْ وَلا تَضُرُّوهُ شَيْئاً وَاللهُ عَلى كُلِّ شَيْءٍ قَدِيرٌ (39) إِلاَّ تَنْصُرُوهُ فَقَدْ نَصَرَهُ اللهُ إِذْ أَخْرَجَهُ الَّذِينَ كَفَرُوا ثانِيَ اثْنَيْنِ إِذْ هُما فِي وفي الآخرة بالنار ( وَيَسْتَبْدِلْ ) بكم ( قَوْماً غَيْرَكُمْ ) فيأتي بمسلمين آخرين مكانكم وبدلكم ينصرون الرسول ويطيعون أوامره ، فإن الله على كل شيء قدير ( وَلا تَضُرُّوهُ شَيْئاً ) لا تضروا الله بقعودكم عن القتال شيئا ، فإنه غني عنكم وعن العالمين ، وإنما تضرون أنفسكم ( وَاللهُ عَلى كُلِّ شَيْءٍ قَدِيرٌ ) فيقدر أن يستبدل بكم غيركم ، كما يقدر أن ينصر الرسول صلى‌الله‌عليه‌وآله‌وسلم بدونكم ، كما نصره من ذي قبل حيث لم تكونوا مسلمين أنتم ـ أيها المتخلفون ـ. [40] ثم بيّن سبحانه إمكانية نصر الرسول بدونهم ، بضرب مثل قريب ، وهو نصرته على الكفار في مكة حيث أرادوا قتله فأنجاه منهم وأعزه ، وأذلهم ( إِلَّا تَنْصُرُوهُ ) أي إن لم تنصروا الرسول في غزو الروم ( فَقَدْ نَصَرَهُ اللهُ ) من ذي قبل ، وهو قادر على نصره الآن ( إِذْ أَخْرَجَهُ الَّذِينَ كَفَرُوا ) من مكة ، ونسبة الإخراج إليهم لأنهم كانوا السبب حين أرادوا قتله ففر من أيديهم ( ثانِيَ اثْنَيْنِ ) فقد كان حين الفرار هو وأبو بكر ، إذ رآه في الطريق فأخذه كيلا يخبر الناس بخبره صلى‌الله‌عليه‌وآله‌وسلم فيلحقه الطلب ، فإن من عادة الإنسان أن يفشي الأنباء الهامة ، وذكر « ثاني اثنين » لبيان أنه صلى‌الله‌عليه‌وآله‌وسلم كان بهذه الغربة حتى أنه لم يكن معه إلا نفر آخر. فالله القادر على نصره وهو بتلك الغربة والوحدة ، قادر على أن ينصره الآن. ولبيان ذلك جيء بالقيدين الآخرين ( إِذْ هُما فِي الْغارِ إِذْ يَقُولُ لِصاحِبِهِ لا تَحْزَنْ إِنَّ اللهَ مَعَنا الْغارِ ) « الغار » هو الثقب في الجبل ( إِذْ يَقُولُ ) الرسول ( لِصاحِبِهِ ) أبي بكر : ( لا تَحْزَنْ إِنَّ اللهَ مَعَنا ) مطّلع علينا ، فالإنسان الفار اللاجئ إلى ثقب جبل لا أحد معه إلا شخص واحد يخشى ويخاف ويحزن فيزيده كآبة ، كيف نصره الله على أعدائه ، إن الله قادر على أن ينصره الآن كما نصره سابقا. وقد استدل بعض على فضيلة أبي بكر بهذه الآية ، لكن لا يخفى ما فيه ، فإنها لم تدل إلا على كونه أحد الشخصين ، وأنه صاحب ، وأنه حزن ، وأن الله معهما ، ولا دلالة في شيء من ذلك ، فإن الاثنين عدد « وثاني اثنين » حكاية العدد ، وليس فيما يقتضي الفضل يعد ، والصاحب يطلق على كل مصاحب ( فَقالَ لِصاحِبِهِ وَهُوَ يُحاوِرُهُ ) (1) ، والحزن لم يكن صحيحا وإلا لم ينهه الرسول صلى‌الله‌عليه‌وآله‌وسلم ( أَلا إِنَّ أَوْلِياءَ اللهِ لا خَوْفٌ عَلَيْهِمْ وَلا هُمْ يَحْزَنُونَ ) (2) ، والله سبحانه مع كل بر وفاجر ( ما يَكُونُ مِنْ نَجْوى ثَلاثَةٍ إِلَّا هُوَ رابِعُهُمْ ) (3) ، بل ربما قيل : إن الآية دلت على خلاف الفضيلة إذ قال سبحانه : « عليه » و « أيده » بينما قال في مكان آخر ( عَلى رَسُولِهِ وَعَلَى الْمُؤْمِنِينَ ) (4) . إن هذا البحث له موضع غير هذا الموضع ، وإنما المقصود الإشارة إلى عدم حسن أن يقحم في القرآن الحكيم ما ليس منه ثم جرّ الآيات إلى الأنظار والأفكار جرّا بدون دلالة أو برهان. فقد ورد الذم لمن فسّر القرآن برأيه. ( 1) الكهف : 35. ( 2) يونس : 63. ( 3) المجادلة : 8. ( 4) التوبة : 26. فَأَنْزَلَ اللهُ سَكِينَتَهُ عَلَيْهِ وَأَيَّدَهُ بِجُنُودٍ لَمْ تَرَوْها وَجَعَلَ كَلِمَةَ الَّذِينَ كَفَرُوا السُّفْلى ( فَأَنْزَلَ اللهُ سَكِينَتَهُ عَلَيْهِ ) أي على الرسول صلى‌الله‌عليه‌وآله‌وسلم ، أي ألقى في قلبه ما سكن به ، وعلم أنه سبحانه ينصره عليهم ( وَأَيَّدَهُ ) أي قوّى الرسول ونصره ( بِجُنُودٍ ) من الملائكة ( لَمْ تَرَوْها ) أي ما رأت الكفار إياها ، بمعنى عدم كونهم أجساما حتى يروا. ورد أنه كان رجل من خزاعة يقال له « أبو كرز » اقتفى مع المشركين أثر الرسول صلى‌الله‌عليه‌وآله‌وسلم حتى وقف بهم على الغار فقال لهم : هذه قدم محمد صلى‌الله‌عليه‌وآله‌وسلم هي والله أخت القدم التي في المقام ، وقال : هذه قدم محمد صلى‌الله‌عليه‌وآله‌وسلم هي والله أخت القدم التي في المقام ، وقال : هذه قدم أبي قحافة أو ابنه ما جاوزوا هذا المكان ، إما أن يكونوا قد صعدوا السماء أو دخلوا في الأرض. وجاء فارس من الملائكة في صورة الإنس فوقف على باب الغار وهو يقول لهم : اطلبوه في هذه الشعاب ، وكانت العنكبوت نسجت على باب الغار ، وأرسل الله زوجا من الحمام حتى باضا في أسفل الثقب فقال سراقة وكان مع الكفار : لو دخل الغار أحد لانكسر حتما البيض وتفسخ بيت العنكبوت. ودعا النبي صلى‌الله‌عليه‌وآله‌وسلم قائلا : « اللهم أعم أبصارهم » فعميت أبصارهم عن دخوله وجعلوا يضربون يمينا وشمالا حول الغار ويئسوا أخيرا فرجعوا (1) . ( وَجَعَلَ ) الله تعالى ( كَلِمَةَ الَّذِينَ كَفَرُوا ) وكيدهم للرسول وشوكتهم ( السُّفْلى ) إذ تحطمت وفشلت فكانت في الدرجة السفلى ( 1) مناقب آل أبي طالب : ج 1 127. وَكَلِمَةُ اللهِ هِيَ الْعُلْيا وَاللهُ عَزِيزٌ حَكِيمٌ (40) انْفِرُوا خِفافاً وَثِقالاً وَجاهِدُوا بِأَمْوالِكُمْ وَأَنْفُسِكُمْ فِي سَبِيلِ اللهِ ذلِكُمْ خَيْرٌ لَكُمْ إِنْ كُنْتُمْ تَعْلَمُونَ (41) ( وَكَلِمَةُ اللهِ هِيَ الْعُلْيا ) المرتفعة المنصورة ، وهذا إخبار بأن كلمته وقوله دائما يكونان كذلك. ومن الواضح في التاريخ أن كلمة الله عالية وأنصارها الأعلون ، وإن كانت الغلبة لكلمة الكافرين ، حتى إن الناس لو كانت سيوفهم مع السلطات الباطلة كانت قلوبهم مع أهل الحق ورأوا أن الحق عندهم ( وَاللهُ عَزِيزٌ ) غالب ( حَكِيمٌ ) في تدبيره.` },
            { text: "إِلَّا تَنصُرُوهُ فَقَدْ نَصَرَهُ ٱللَّهُ إِذْ أَخْرَجَهُ ٱلَّذِينَ كَفَرُوا۟ ثَانِىَ ٱثْنَيْنِ إِذْ هُمَا فِى ٱلْغَارِ إِذْ يَقُولُ لِصَٰحِبِهِۦ لَا تَحْزَنْ إِنَّ ٱللَّهَ مَعَنَا فَأَنزَلَ ٱللَّهُ سَكِينَتَهُۥ عَلَيْهِ وَأَيَّدَهُۥ بِجُنُودٍ لَّمْ تَرَوْهَا وَجَعَلَ كَلِمَةَ ٱلَّذِينَ كَفَرُوا۟ ٱلسُّفْلَىٰ وَكَلِمَةُ ٱللَّهِ هِىَ ٱلْعُلْيَا وَٱللَّهُ عَزِيزٌ حَكِيمٌ", tafsir: `` },
            { text: "ٱنفِرُوا۟ خِفَافًا وَثِقَالًا وَجَٰهِدُوا۟ بِأَمْوَٰلِكُمْ وَأَنفُسِكُمْ فِى سَبِيلِ ٱللَّهِ ذَٰلِكُمْ خَيْرٌ لَّكُمْ إِن كُنتُمْ تَعْلَمُونَ", tafsir: `من « نفر » إذا خرج مسرعا ، أي اخرجوا إلى الجهاد ( خِفافاً ) جمع « خفيف » ( وَثِقالاً ) جمع « ثقيل » ، والخفة تطلق على قليل العيال ، قليل السن والنشيط ، وقليل المشاغل ، كما أن الثقل عكس ذلك كله ، والمراد : جاهدوا واخرجوا لأجل الحرب كيفما كنتم في خفة أو ثقل ( وَجاهِدُوا بِأَمْوالِكُمْ وَأَنْفُسِكُمْ ) والمجاهدة بالمال : بذله في سبيل إعلاء كلمة الإسلام ، والمجاهدة بالنفس : الذهاب للحرب ( فِي سَبِيلِ اللهِ ) ويسمى جهادا ، لأنه من الجهد والتعب ( ذلِكُمْ ) ذلك إشارة ، و « كم » للخطاب ، أي أن الجهاد ـ أيها المسلمون ـ ( خَيْرٌ لَكُمْ ) من تركه ، فإنه فيه عزّ الدنيا وسعادة الآخرة ( إِنْ كُنْتُمْ تَعْلَمُونَ ) ليس المعنى إن لم تعلموا لم يكن خيرا لكم ، بل المعنى إن كنتم تعلمون ، لعلمتم أنه خير لكم. [42] كان المنافقون يرجفون بالمسلمين قائلين : « إن السفر بعيد » فإنها كانت مسافة بعيدة بين المدينة وبين « تبوك » فلا تذهبوا إلى الجهاد. فرد لَوْ كانَ عَرَضاً قَرِيباً وَسَفَراً قاصِداً لاتَّبَعُوكَ وَلكِنْ بَعُدَتْ عَلَيْهِمُ الشُّقَّةُ وَسَيَحْلِفُونَ بِاللهِ لَوِ اسْتَطَعْنا لَخَرَجْنا مَعَكُمْ يُهْلِكُونَ أَنْفُسَهُمْ وَاللهُ يَعْلَمُ إِنَّهُمْ لَكاذِبُونَ (42) عليهم سبحانه ( لَوْ كانَ ) ما دعوتهم إليه يا رسول الله ( عَرَضاً قَرِيباً ) أي غنيمة سهلة التناول ، فإن أموال الدنيا تسمى أعراضا باعتبار كونها زائلة فانية ( وَسَفَراً قاصِداً ) أي سفرا متوسطا في البعد والقرب ، بأن سهل عليهم الذهاب والخروج ( لَاتَّبَعُوكَ ) لأنه يسهل عليهم ذلك ( وَلكِنْ بَعُدَتْ عَلَيْهِمُ الشُّقَّةُ ) أي المسافة ، فإن الشقة بمعنى القطعة من الأرض التي يشق على إنسان السير فيها لبعدها ، ولذا يأتون بالأعذار الواهية فرارا ( وَسَيَحْلِفُونَ بِاللهِ لَوِ اسْتَطَعْنا لَخَرَجْنا مَعَكُمْ ) فإنهم كانوا يحلفون بأنهم لا يقدرون على الخروج لاشتغالهم وأن لهم أعذارا مشروعة ( يُهْلِكُونَ أَنْفُسَهُمْ ) هؤلاء المعتذرون باستحقاقهم العقاب في الآخرة ، والنكال في الدنيا ، فإن ترك الجهاد يوجب الذلة والصغار للفرد والجماعة ( وَاللهُ يَعْلَمُ إِنَّهُمْ لَكاذِبُونَ ) في ادعائهم أنهم لا يستطيعون الخروج. [43] استأذن جماعة من المنافقين الرسول صلى‌الله‌عليه‌وآله‌وسلم في تركهم الخروج إلى تبوك ، فأذن لهم الرسول صلى‌الله‌عليه‌وآله‌وسلم وقد كان هذا الإذن كسائر أوامر الرسول وكلماته بالوحي بدليل قوله سبحانه : ( وَما يَنْطِقُ عَنِ الْهَوى * إِنْ هُوَ إِلَّا وَحْيٌ يُوحى ) (1) ، لكن الاستئذان من القوم كان نفاقا فاستحقوا العقاب. ( 1) النجم : 4 و 5. عَفَا اللهُ عَنْكَ لِمَ أَذِنْتَ لَهُمْ حَتَّى يَتَبَيَّنَ لَكَ الَّذِينَ صَدَقُوا وَتَعْلَمَ الْكاذِبِينَ (43) ومن البلاغة أن يوجه الإنسان العتاب إلى أحد وهو يريد إفهام غيره ، فإذا ألحّ الشخص المتظاهر بالفقر ، فأشرت إلى ولدك بإعطائه المال ، تقول له ـ معاتبا ـ وأنت تريد إفهام الآخذ : لم أعطيته المال ؟ مع أن إعطاءه كان بأمرك ولكنك تريد توبيخ الآخذ بصورة بليغة ، وهذا كما يظهر في الكلام يظهر في العمل ، فقد تأخذ بيد الولد لتقصيره أمام الآخذ مظهرا غضبك عليه ، تريد إفهام الآخذ بسوء صنيعه في الأخذ ، كما تقدم في قصة موسى وهارون عليهما‌السلام . وهذا هو المعنى من قول الإمام الرضا عليه‌السلام في جواب أسئلة المأمون عن عصمة الأنبياء. وأنه كيف قال للرسول صلى‌الله‌عليه‌وآله‌وسلم : « عفا الله عنك .. » ، هذا مما نزل ب « إياك أعني واسمعي يا جارة » (1) . ( عَفَا اللهُ عَنْكَ ) يا رسول الله. إنه لا يريد أنه صلى‌الله‌عليه‌وآله‌وسلم فعل خلاف الأولى ، حتى يستحق العفو أو العتاب ، بل يريد إفهام المتخلفين أنهم فعلوا فعلا قبيحا حتى إن الإذن لهم في القعود يستحق العفو ( لِمَ أَذِنْتَ لَهُمْ ) في البقاء وعدم الخروج إلى الجهاد ( حَتَّى يَتَبَيَّنَ لَكَ الَّذِينَ صَدَقُوا ) في أنهم لا يستطيعون الخروج ( وَتَعْلَمَ الْكاذِبِينَ ) أي حتى تعلم وتميّز بين الصادق والكاذب ، وقد كان الرسول صلى‌الله‌عليه‌وآله‌وسلم يميّز ويعلم ، كيف وأحدنا يعلم الصادق والكاذب من أصحابه وأصدقائه ؟ لكن هذا الكلام لتنبيه المتخلفين الكاذبين ، وأنه عرف كذبهم وسوء قصدهم. ( 1) بحار الأنوار : ج 11 ص 83. لا يَسْتَأْذِنُكَ الَّذِينَ يُؤْمِنُونَ بِاللهِ وَالْيَوْمِ الْآخِرِ أَنْ يُجاهِدُوا بِأَمْوالِهِمْ وَأَنْفُسِهِمْ وَاللهُ عَلِيمٌ بِالْمُتَّقِينَ (44) إِنَّما يَسْتَأْذِنُكَ الَّذِينَ لا يُؤْمِنُونَ بِاللهِ وَالْيَوْمِ الْآخِرِ وَارْتابَتْ قُلُوبُهُمْ فَهُمْ فِي رَيْبِهِمْ يَتَرَدَّدُونَ (45) وَلَوْ أَرادُوا الْخُرُوجَ لَأَعَدُّوا لَهُ` },
            { text: "لَوْ كَانَ عَرَضًا قَرِيبًا وَسَفَرًا قَاصِدًا لَّٱتَّبَعُوكَ وَلَٰكِنۢ بَعُدَتْ عَلَيْهِمُ ٱلشُّقَّةُ وَسَيَحْلِفُونَ بِٱللَّهِ لَوِ ٱسْتَطَعْنَا لَخَرَجْنَا مَعَكُمْ يُهْلِكُونَ أَنفُسَهُمْ وَٱللَّهُ يَعْلَمُ إِنَّهُمْ لَكَٰذِبُونَ", tafsir: `` },
            { text: "عَفَا ٱللَّهُ عَنكَ لِمَ أَذِنتَ لَهُمْ حَتَّىٰ يَتَبَيَّنَ لَكَ ٱلَّذِينَ صَدَقُوا۟ وَتَعْلَمَ ٱلْكَٰذِبِينَ", tafsir: `` },
            { text: "لَا يَسْتَـْٔذِنُكَ ٱلَّذِينَ يُؤْمِنُونَ بِٱللَّهِ وَٱلْيَوْمِ ٱلْـَٔاخِرِ أَن يُجَٰهِدُوا۟ بِأَمْوَٰلِهِمْ وَأَنفُسِهِمْ وَٱللَّهُ عَلِيمٌۢ بِٱلْمُتَّقِينَ", tafsir: `إيمانا صادقا ، كيف والمؤمن يعلم أنه سواء غلب أو غلب كان له الأجر العظيم والعاقبة المحمودة عند الله سبحانه ، ولذا لا يطلب الإذن في التخلّف ( أَنْ يُجاهِدُوا بِأَمْوالِهِمْ وَأَنْفُسِهِمْ ) في أن يجاهدوا ، والمعنى لا يستأذنوا للتخلّف في أمر الجهاد ، لا أن المعنى لا يستأذنون للجهاد ( وَاللهُ عَلِيمٌ بِالْمُتَّقِينَ ) الذين يتقون عصيان الله ، ويعملون حسب أوامره.` },
            { text: "إِنَّمَا يَسْتَـْٔذِنُكَ ٱلَّذِينَ لَا يُؤْمِنُونَ بِٱللَّهِ وَٱلْيَوْمِ ٱلْـَٔاخِرِ وَٱرْتَابَتْ قُلُوبُهُمْ فَهُمْ فِى رَيْبِهِمْ يَتَرَدَّدُونَ", tafsir: `ويطلب إذنك في القعود عن الجهاد ( الَّذِينَ لا يُؤْمِنُونَ بِاللهِ وَالْيَوْمِ الْآخِرِ ) إيمانا صادقا عن عقيدة ورسوخ ( وَارْتابَتْ قُلُوبُهُمْ ) أي شكّت ، من « الريب » بمعنى التردّد ، أي شكّوا في صدق الأمر وحقيقته ( فَهُمْ فِي رَيْبِهِمْ ) وشكّهم حول المبدأ والمعاد ( يَتَرَدَّدُونَ ) فتارة ترجح عندهم العقيدة ، وأخرى يرجح عندهم الإنكار. ولهذا فإن هؤلاء لمّا لم يستيقنوا يستأذنوك للتخلّص من الصعوبة. [46] ثم بيّن سبحانه علامة نفاقهم وأنهم امتازوا عن المؤمنين بأن لم يستعدوا للجهاد فقد نووا من أول الأمر عدم الخروج ( وَلَوْ أَرادُوا الْخُرُوجَ ) إلى الجهاد ، كما أراد سائر المؤمنين ( لَأَعَدُّوا لَهُ ) للجهاد عُدَّةً وَلكِنْ كَرِهَ اللهُ انْبِعاثَهُمْ فَثَبَّطَهُمْ وَقِيلَ اقْعُدُوا مَعَ الْقاعِدِينَ (46) لَوْ خَرَجُوا فِيكُمْ ما زادُوكُمْ إِلاَّ خَبالاً وَلَأَوْضَعُوا خِلالَكُمْ ( عُدَّةً ) أهبة ، فإن العدة والأهبة والآلة نظائر ( وَلكِنْ كَرِهَ اللهُ انْبِعاثَهُمْ ) الانبعاث هو الانطلاق بسرعة في الأمر ( فَثَبَّطَهُمْ ) أي أوقفهم عن الجهاد بالتزهيد فيه فرغبوا عنه ( وَقِيلَ ) القائل هو الله سبحانه ـ بلسان الحال ـ أو إخوانهم المنافقون : ( اقْعُدُوا مَعَ الْقاعِدِينَ ) النساء والصبيان والعجزة الذين بقوا في المدينة ولم يخرجوا للجهاد. إن أمر الجهاد كان متوجها إليهم مع صفاء النية وخلوص القصد ، أما أنهم نافقوا وكانوا لو خرجوا ألقوا التشويش والاضطراب ـ كما هو شأن المنافق في كل حركة ـ بالنميمة بين المسلمين ، وكان الضرر في خروجهم أكثر ، فالأحرى أن لا يخرجوا ، فالله سبحانه كره ذهابهم للغزو لهذه الجهة فلم يوفّقهم للجهاد. وقد مرّ مكررا أنه تصحّ نسبة الفعل إليه سبحانه باعتبار أنه لم يزل العائق تكوينا ، كما يقال : « إن الملك عوّق ذهاب الجيش ولم يدعهم يذهبوا » ، فيما إذا لم يزل العائق أمامهم. [47] ثم بيّن سبحانه سبب كره الله انبعاثهم بقوله : ( لَوْ خَرَجُوا ) أي خرج هؤلاء المنافقون إلى الجهاد ( فِيكُمْ ) أي في ضمنكم أيها المسلمون ( ما زادُوكُمْ إِلَّا خَبالاً ) « الخبال » هو الفساد ، أي كان خروجهم معكم سببا للفساد والاضطراب ، فإن المنافق دائم النقد للحركات ، كثير التخذيل مما يوجب فسادا واضطرابا وتشويشا ( وَلَأَوْضَعُوا خِلالَكُمْ ) « الإيضاع » الإسراع في السير ، و « الخلال » بمعنى « البين » ، أي أسرعوا يَبْغُونَكُمُ الْفِتْنَةَ وَفِيكُمْ سَمَّاعُونَ لَهُمْ وَاللهُ عَلِيمٌ بِالظَّالِمِينَ (47) لَقَدِ ابْتَغَوُا الْفِتْنَةَ مِنْ قَبْلُ وَقَلَّبُوا لَكَ الْأُمُورَ حَتَّى جاءَ الْحَقُّ وَظَهَرَ أَمْرُ اللهِ وَهُمْ كارِهُونَ (48) في الدخول بينكم بالفساد والنميمة والإفساد ( يَبْغُونَكُمُ ) أي يطلبون لكم ( الْفِتْنَةَ ) واختلاف الكلمة والانشقاق ـ كما هو شأن المنافق ـ ( وَ ) يكونون ( فِيكُمْ ) أيها المسلمون ( سَمَّاعُونَ لَهُمْ ) يسمعون أقوال الكفار ـ المفهوم من الكلام ـ فيصبح هؤلاء المنافقون جواسيس وعيونا للكفار ، أو المراد : إن كانوا معكم كان من المؤمنين البسطاء أشخاص يسمعون لأولئك المنافقين ، فعدم مجيئهم كان أنفع لكم ( وَاللهُ عَلِيمٌ بِالظَّالِمِينَ ) الذين ظلموا أنفسهم بالنفاق وعدم الخروج ، فيجازيهم بما عملوا.` },
            { text: "وَلَوْ أَرَادُوا۟ ٱلْخُرُوجَ لَأَعَدُّوا۟ لَهُۥ عُدَّةً وَلَٰكِن كَرِهَ ٱللَّهُ ٱنۢبِعَاثَهُمْ فَثَبَّطَهُمْ وَقِيلَ ٱقْعُدُوا۟ مَعَ ٱلْقَٰعِدِينَ", tafsir: `` },
            { text: "لَوْ خَرَجُوا۟ فِيكُم مَّا زَادُوكُمْ إِلَّا خَبَالًا وَلَأَوْضَعُوا۟ خِلَٰلَكُمْ يَبْغُونَكُمُ ٱلْفِتْنَةَ وَفِيكُمْ سَمَّٰعُونَ لَهُمْ وَٱللَّهُ عَلِيمٌۢ بِٱلظَّٰلِمِينَ", tafsir: `` },
            { text: "لَقَدِ ٱبْتَغَوُا۟ ٱلْفِتْنَةَ مِن قَبْلُ وَقَلَّبُوا۟ لَكَ ٱلْأُمُورَ حَتَّىٰ جَآءَ ٱلْحَقُّ وَظَهَرَ أَمْرُ ٱللَّهِ وَهُمْ كَٰرِهُونَ", tafsir: `وطلب هؤلاء المنافقون ( الْفِتْنَةَ ) والفساد بين المسلمين ( مِنْ قَبْلُ ) في أحد وفي حنين وعند الثنية عند رجوع النبي صلى‌الله‌عليه‌وآله‌وسلم من حجة الوداع حيث أرادوا قتله ودبروا مؤامرة خبيثة لتشتيت شمل المسلمين ( وَقَلَّبُوا لَكَ الْأُمُورَ ) « التقليب » تصريف الشيء على غير وجهه ، فقد احتال المنافقون لأن يقلبوا وحدة المسلمين تشتتا ، وصفاءهم كدورة ( حَتَّى جاءَ الْحَقُ ) الظفر الذي وعد الله سبحانه ( وَظَهَرَ أَمْرُ اللهِ ) دينه والإسلام وحقيقة الرسول صلى‌الله‌عليه‌وآله‌وسلم ( وَ ) الحال أن ( هُمْ كارِهُونَ ) لمجرد الحق وظهور أمر الله ، فإن يثيروا الفتن الآن بالنفاق ، فقد كانوا سابقا كذلك ، فلا يهمّك أمرهم يا رسول الله ، ولا تعيرهم وبالا. وَمِنْهُمْ مَنْ يَقُولُ ائْذَنْ لِي وَلا تَفْتِنِّي أَلا فِي الْفِتْنَةِ سَقَطُوا وَإِنَّ جَهَنَّمَ لَمُحِيطَةٌ بِالْكافِرِينَ (49)` },
            { text: "وَمِنْهُم مَّن يَقُولُ ٱئْذَن لِّى وَلَا تَفْتِنِّىٓ أَلَا فِى ٱلْفِتْنَةِ سَقَطُوا۟ وَإِنَّ جَهَنَّمَ لَمُحِيطَةٌۢ بِٱلْكَٰفِرِينَ", tafsir: `أي من المنافقين المتخلّفين في غزوة تبوك ( مَنْ يَقُولُ ائْذَنْ لِي ) يا رسول الله في التخلّف ( وَلا تَفْتِنِّي ) لا توقعني في الفتنة ، بأن تأمرني فلا ألبّي الطلب ، أو المراد : لا تفتني ببنات الأصفر. فقد ذكر المفسرون : أن رسول الله لما استنفر الناس إلى حرب الروم في تبوك قال : انفروا لعلكم تغنمون بنات الأصفر ، فقام جد بن قيس أخو بني سلمة فقال : يا رسول الله ائذن لي ولا تفتني ببنات الأصفر ، فإني أخاف أن أفتتن بهن ، فقال : قد أذنت لك ، فنزلت الآية. ويسمّى الروم بنوا الأصفر ، لأن حبشيا غلب على ناحية الروم وكان له بنات قد أخذن بياض الروم وسواد الحبشة فكنّ صفرا لعسا ـ كما عن الفراء ـ. ثم إن الرسول صلى‌الله‌عليه‌وآله‌وسلم جزى هذا الرجل بصنيعه فقد قال لبني سلمة : من سيدكم ؟ قالوا : جد بن قيس إلا أنه بخيل جبان. فقال صلى‌الله‌عليه‌وآله‌وسلم : وأي داء أدوى من البخل ، بل سيدكم الفتى الأبيض الجعد بشر بن البراء بن المعرور (1) . ( أَلا فِي الْفِتْنَةِ سَقَطُوا ) إنهم أظهروا بتخلفهم الفرار عن الفتنة ، فقد سقطوا في الفتنة بتخلفهم عنك وعصيانهم لك ، فإن الإذن عن كره كعدمه ( وَإِنَّ جَهَنَّمَ لَمُحِيطَةٌ بِالْكافِرِينَ ) تحيط بهم فلا مخلّص لهم منها. ولعل هذا التعبير بمناسبة أنهم أظهروا الفرار من الفتنة ، لكن ( 1) بحار الأنوار : ج 21 ص 193. إِنْ تُصِبْكَ حَسَنَةٌ تَسُؤْهُمْ وَإِنْ تُصِبْكَ مُصِيبَةٌ يَقُولُوا قَدْ أَخَذْنا أَمْرَنا مِنْ قَبْلُ وَيَتَوَلَّوْا وَهُمْ فَرِحُونَ (50) قُلْ لَنْ يُصِيبَنا إِلاَّ ما كَتَبَ اللهُ لَنا هُوَ مَوْلانا وَعَلَى اللهِ فَلْيَتَوَكَّلِ الْمُؤْمِنُونَ (51) المنافق لا يفرّ من فتنة إلّا ويسقط في فتنة أخرى ، لأنه من أهل النار وهي محيطة به ، فكيف يفر منها. [50] وكيف يكون هؤلاء المنافقون مسلمين ، والحال أن صفاتهم صفات الكافرين ( إِنْ تُصِبْكَ ) يا رسول الله ( حَسَنَةٌ ) تصل إليك غنيمة أو خير ( تَسُؤْهُمْ ) أي يحزن المنافقون من أجلها ( وَإِنْ تُصِبْكَ مُصِيبَةٌ ) شدة وآفة في النفس أو المال أو غيرهما ( يَقُولُوا ) المنافقون : ( قَدْ أَخَذْنا أَمْرَنا مِنْ قَبْلُ ) أخذنا حذرنا من قبل وقوع الرسول صلى‌الله‌عليه‌وآله‌وسلم وأصحابه في هذه البلية ( وَيَتَوَلَّوْا وَهُمْ فَرِحُونَ ) رجعوا إلى بيوتهم فرحين بما أصاب المؤمنين من الشدة. وقد كان من عادة المؤمنين عكس ذلك ، فإنهم إذا رأوا الرسول في شدة اجتمعوا حوله ليواسوه بأنفسهم.` },
            { text: "إِن تُصِبْكَ حَسَنَةٌ تَسُؤْهُمْ وَإِن تُصِبْكَ مُصِيبَةٌ يَقُولُوا۟ قَدْ أَخَذْنَآ أَمْرَنَا مِن قَبْلُ وَيَتَوَلَّوا۟ وَّهُمْ فَرِحُونَ", tafsir: `` },
            { text: "قُل لَّن يُصِيبَنَآ إِلَّا مَا كَتَبَ ٱللَّهُ لَنَا هُوَ مَوْلَىٰنَا وَعَلَى ٱللَّهِ فَلْيَتَوَكَّلِ ٱلْمُؤْمِنُونَ", tafsir: `يا رسول الله لهؤلاء : ( لَنْ يُصِيبَنا إِلَّا ما كَتَبَ اللهُ لَنا ) فلم يكن ما أصابنا شر لنا ، كما زعمتم ، بل إن الله سبحانه كتب هذه البلايا لنا لأن ترفع درجاتنا في الآخرة ، وينصرنا على أعدائنا في النهاية ، ونحن مسلمون لأمر الله منقادون لإرادته ( هُوَ مَوْلانا ) أولى بنا من أنفسنا ، فما كتبه لنا كان لخيرنا وصلاحنا ( وَعَلَى اللهِ فَلْيَتَوَكَّلِ الْمُؤْمِنُونَ ) بأن يكلوا أمرهم إليه ، ويرضوا بقضائه ، فليس ذلك إلا للخير والسعادة. قُلْ هَلْ تَرَبَّصُونَ بِنا إِلاَّ إِحْدَى الْحُسْنَيَيْنِ وَنَحْنُ نَتَرَبَّصُ بِكُمْ أَنْ يُصِيبَكُمُ اللهُ بِعَذابٍ مِنْ عِنْدِهِ أَوْ بِأَيْدِينا فَتَرَبَّصُوا إِنَّا مَعَكُمْ مُتَرَبِّصُونَ (52) قُلْ أَنْفِقُوا طَوْعاً أَوْ كَرْهاً لَنْ يُتَقَبَّلَ مِنْكُمْ` },
            { text: "قُلْ هَلْ تَرَبَّصُونَ بِنَآ إِلَّآ إِحْدَى ٱلْحُسْنَيَيْنِ وَنَحْنُ نَتَرَبَّصُ بِكُمْ أَن يُصِيبَكُمُ ٱللَّهُ بِعَذَابٍ مِّنْ عِندِهِۦٓ أَوْ بِأَيْدِينَا فَتَرَبَّصُوٓا۟ إِنَّا مَعَكُم مُّتَرَبِّصُونَ", tafsir: `يا رسول الله لهؤلاء المنافقين : ( هَلْ تَرَبَّصُونَ ) « التربص » الانتظار ، أي : هل تنتظرون ( بِنا إِلَّا إِحْدَى الْحُسْنَيَيْنِ ) إما النصر والظفر وخير الدنيا ، وإما الشهادة في سبيل الله وفيها خير الآخرة ، فلا يعود تربّصكم بشر لنا أو خير لكم ( وَنَحْنُ نَتَرَبَّصُ بِكُمْ ) ننتظر أن تقعوا في أحد الشرين ( أَنْ يُصِيبَكُمُ اللهُ بِعَذابٍ مِنْ عِنْدِهِ ) بأن تهلكوا فتعذّبوا في الآخرة ( أَوْ بِأَيْدِينا ) بأن ننتصر عليكم فتصبحوا أذلاء في الدنيا خاسرين مقهورين ( فَتَرَبَّصُوا ) أي انتظروا. وهو تهديد في صورة الأمر كقوله : ( اعْمَلُوا ما شِئْتُمْ ) (1) ، ( إِنَّا مَعَكُمْ مُتَرَبِّصُونَ ) أي منتظرون ، حتى نرى لمن العاقبة الحسنة ، ولمن العاقبة السيئة. [53] قد كان بعض المنافقين عرضوا أموالهم لمساعدة المجاهدين في « تبوك » لينجوا بذلك عن الذهاب بأنفسهم ولا يقعوا موقع لوم المسلمين بأنهم نافقوا ، ولم يشتركوا في الجهاد مع المجاهدين ، لكن الله سبحانه أخبر عن نيتهم وأن إنفاقهم لا ينفع شيئا ( قُلْ ) يا رسول الله لهؤلاء المنافقين : ( أَنْفِقُوا ) أموالكم للجهاد ( طَوْعاً أَوْ كَرْهاً ) طائعين أو مكرهين ( لَنْ يُتَقَبَّلَ مِنْكُمْ ) أي إن أنفقتم طائعين أو مكرهين ( 1) فصلت : 41. إِنَّكُمْ كُنْتُمْ قَوْماً فاسِقِينَ (53) وَما مَنَعَهُمْ أَنْ تُقْبَلَ مِنْهُمْ نَفَقاتُهُمْ إِلاَّ أَنَّهُمْ كَفَرُوا بِاللهِ وَبِرَسُولِهِ وَلا يَأْتُونَ الصَّلاةَ إِلاَّ وَهُمْ كُسالى وَلا يُنْفِقُونَ إِلاَّ وَهُمْ كارِهُونَ (54) لا يتقبل الله منكم الإنفاق. فاللفظ أمر والمعنى الشرط. ثم بيّن السبب بقوله : ( إِنَّكُمْ كُنْتُمْ قَوْماً فاسِقِينَ ) خارجين عن طاعة الله سبحانه ، والفاسق لا يتقبل منه الإنفاق ، لأن قبول الأعمال مشروط بالتقوى وهو منفي عنهم ، قال سبحانه : ( إِنَّما يَتَقَبَّلُ اللهُ مِنَ الْمُتَّقِينَ ) (1) .` },
            { text: "قُلْ أَنفِقُوا۟ طَوْعًا أَوْ كَرْهًا لَّن يُتَقَبَّلَ مِنكُمْ إِنَّكُمْ كُنتُمْ قَوْمًا فَٰسِقِينَ", tafsir: `` },
            { text: "وَمَا مَنَعَهُمْ أَن تُقْبَلَ مِنْهُمْ نَفَقَٰتُهُمْ إِلَّآ أَنَّهُمْ كَفَرُوا۟ بِٱللَّهِ وَبِرَسُولِهِۦ وَلَا يَأْتُونَ ٱلصَّلَوٰةَ إِلَّا وَهُمْ كُسَالَىٰ وَلَا يُنفِقُونَ إِلَّا وَهُمْ كَٰرِهُونَ", tafsir: `: أيّ شيء منع قبول إنفاقهم والإثابة عليه ؟ إنه كفرهم ( إِلَّا أَنَّهُمْ كَفَرُوا بِاللهِ وَبِرَسُولِهِ ) فإن الكفر الباطني مانع عن قبول الأعمال ، وإن أظهر الإسلام ( وَلا يَأْتُونَ الصَّلاةَ إِلَّا وَهُمْ كُسالى ) متثاقلين ، فإن المؤمن حيث امتلأ إيمانا يقدم على الطاعات بكل شوق ورغبة ، بخلاف المنافق الذي لم يذعن قلبه لشيء ، فإنه لا يأتي الصلاة وسائر الطاعات إلّا متثاقلا كسلانا فإنه يريد بذلك إراءة الناس ( وَلا يُنْفِقُونَ إِلَّا وَهُمْ كارِهُونَ ) للإنفاق ، لأنهم لا يدفعون المال عن عقيدة وإخلاص ، وإنما يدفعون للتستر بالإسلام والتحفّظ على أنفسهم من ألسنة المؤمنين ، لئلّا يظهر ما ينوون من الكفر والنفاق. ( 1) المائدة : 28. فَلا تُعْجِبْكَ أَمْوالُهُمْ وَلا أَوْلادُهُمْ إِنَّما يُرِيدُ اللهُ لِيُعَذِّبَهُمْ بِها فِي الْحَياةِ الدُّنْيا وَتَزْهَقَ أَنْفُسُهُمْ وَهُمْ كافِرُونَ (55)` },
            { text: "فَلَا تُعْجِبْكَ أَمْوَٰلُهُمْ وَلَآ أَوْلَٰدُهُمْ إِنَّمَا يُرِيدُ ٱللَّهُ لِيُعَذِّبَهُم بِهَا فِى ٱلْحَيَوٰةِ ٱلدُّنْيَا وَتَزْهَقَ أَنفُسُهُمْ وَهُمْ كَٰفِرُونَ", tafsir: `يا رسول الله ( أَمْوالُهُمْ وَلا أَوْلادُهُمْ ) أي لا يأخذ بقلبك ما تراه من كثرة أموال هؤلاء المنافقين وأولادهم ، ولا تنظر إليهم بعين الإعجاب ، فإن الأموال والأولاد قد تكون نعمة وخيرا حينما يشكر الإنسان وجودها ويصبر ويحتسب لفقدها ، أما إذا لم تكن كذلك ، فهي بالعكس تصبح وبالا على الإنسان ( إِنَّما يُرِيدُ اللهُ لِيُعَذِّبَهُمْ بِها ) بهذه الأموال والأولاد ( فِي الْحَياةِ الدُّنْيا ) فإن النفس غير المطمئنة تكون دائمة القلق على مصير الأموال والأولاد لأنها دائمة الخوف عليهما ، أما المؤمن فإن بقيت أمواله وأولاده شكر وإن ذهبت صبر ، وعلم أن ذلك موجب للأجر والثواب ، فلا يكون خائفا قلقا. قال أحد الكافرين : إن أعجب ما رأيت من شيخ مسلم أنه كان صاحب أغنام تعدّ بالألوف وكان جميع كيانه بها وإذا به يفاجأ ذات يوم ـ وأنا عنده ـ بأن يخبره آت قائلا : إن الأغنام ذهب بها السيل ، قال : وكنت أترقب انقلابا في حال الشيخ الذي ذهب كل كيانه بذهاب أغنامه ، وإذا به يقول : « إنا لله وإنا إليه راجعون ، وماذا نصنع ؟ نتوكل على الله ، ونصبر ، فهو خير للصابرين » وكأن أمرا لم يحدث. ( وَتَزْهَقَ أَنْفُسُهُمْ ) تهلك وتذهب بالموت بصعوبة ، فهم قد عاشوا في الدنيا بصعوبة وقلق ، وها هم يموتون ، وحينما تريد أرواحهم أن تخرج ، تخرج بصعوبة ، فيموتون بكل صعوبة ( وَهُمْ كافِرُونَ ) فقد عاشوا أشقياء ، وماتوا أشقياء ويحشرون أشقياء إذ ماتوا كافرين. ثم إن جملة « تزهق » إما استئنافية ، وإما عطف على « ليعذبهم » . وإرادة الله وَيَحْلِفُونَ بِاللهِ إِنَّهُمْ لَمِنْكُمْ وَما هُمْ مِنْكُمْ وَلكِنَّهُمْ قَوْمٌ يَفْرَقُونَ (56) لَوْ يَجِدُونَ مَلْجَأً أَوْ مَغاراتٍ أَوْ مُدَّخَلاً لَوَلَّوْا إِلَيْهِ وَهُمْ يَجْمَحُونَ (57) ذلك ، إنما كانت بسبب أنهم أعرضوا عن الحق فتركهم الله سبحانه في كفرهم. وهو معنى إرادته أن يموتوا كافرين. [56] وقد كان هؤلاء المنافقين يريدون اللعب على حبلين ، فحيث أن السلطة بيد المسلمين يريدون إرضاءهم بإظهار أنهم منهم ، وحيث أن قلوبهم كانت منكرة كانوا مع الكافرين باطنا وعملا ، لكن الله سبحانه أبدى نواياهم ( وَيَحْلِفُونَ بِاللهِ إِنَّهُمْ لَمِنْكُمْ ) يقسمون بالله إنهم مثلكم في الإيمان والإخلاص ( وَما هُمْ مِنْكُمْ ) ليسوا مثلكم ( وَلكِنَّهُمْ قَوْمٌ يَفْرَقُونَ ) من « فرق » بمعنى خاف ، أي يخافون ويجتنبون القتل والقتال ، وكيف يكون من يجبن مثل غيره من المسلمين الأقوياء القلوب ؟!` },
            { text: "وَيَحْلِفُونَ بِٱللَّهِ إِنَّهُمْ لَمِنكُمْ وَمَا هُم مِّنكُمْ وَلَٰكِنَّهُمْ قَوْمٌ يَفْرَقُونَ", tafsir: `` },
            { text: "لَوْ يَجِدُونَ مَلْجَـًٔا أَوْ مَغَٰرَٰتٍ أَوْ مُدَّخَلًا لَّوَلَّوْا۟ إِلَيْهِ وَهُمْ يَجْمَحُونَ", tafsir: `أي لو وجد هؤلاء المنافقون الجبناء ( مَلْجَأً ) حصنا ، ويسمّى الحصن بذلك ، لأن الإنسان يلجأ عند الخوف إليه ( أَوْ مَغاراتٍ ) جمع « مغارة » ، من « غار يغور » إذا دخل ، ومنه « الغار » بمعنى النقب في الجبل ( أَوْ مُدَّخَلاً ) من « ادّخل » أصله أو « تدّخل » من باب الافتعال قلبت تاؤه دالا ، وجيء بهمزة الوصل لتعذر الابتداء بالساكن ، والمراد به النفق وشبهه ، أي : لو وجد هؤلاء المنافقون الجبناء محل فرار سواء كان حصنا أو غارا أو ثقبا في الأرض ( لَوَلَّوْا إِلَيْهِ ) أي فروا منكم ومن القتال إلى ذلك المخبأ ( وَهُمْ يَجْمَحُونَ ) من وَمِنْهُمْ مَنْ يَلْمِزُكَ فِي الصَّدَقاتِ فَإِنْ أُعْطُوا مِنْها رَضُوا وَإِنْ لَمْ يُعْطَوْا مِنْها إِذا هُمْ يَسْخَطُونَ (58) وَلَوْ أَنَّهُمْ رَضُوا ما آتاهُمُ اللهُ وَرَسُولُهُ « الجموح » بمعنى المضي مسرعين بحيث لا يردهم شيء.` },
            { text: "وَمِنْهُم مَّن يَلْمِزُكَ فِى ٱلصَّدَقَٰتِ فَإِنْ أُعْطُوا۟ مِنْهَا رَضُوا۟ وَإِن لَّمْ يُعْطَوْا۟ مِنْهَآ إِذَا هُمْ يَسْخَطُونَ", tafsir: `أي من المنافقين ( مَنْ يَلْمِزُكَ ) يقال : « لمز الرجل » إذا عابه ، قال سبحانه : ( وَيْلٌ لِكُلِّ هُمَزَةٍ لُمَزَةٍ ) (1) ، ( فِي الصَّدَقاتِ ) أي في تقسيم الصدقات وهي الغنائم وما أشبهها ، مما فرضه الله سبحانه لإقامة المصالح ، أي يطعنون عليك في تقسيمك ( فَإِنْ أُعْطُوا مِنْها رَضُوا ) وقالوا إن محمدا صلى‌الله‌عليه‌وآله‌وسلم عدل وأعطى الحق في موضعه ( وَإِنْ لَمْ يُعْطَوْا مِنْها إِذا هُمْ يَسْخَطُونَ ) يغضبون ويعيبون ، فليسوا معترفين بك وأن أعمالك إنما تصدر عن الوحي ، بل هم طلاب دنيا. ورد أن هذه الآية نزلت لما جاءت الصدقات وجاء الأغنياء وظنوا أن رسول الله صلى‌الله‌عليه‌وآله‌وسلم يقسمها بينهم ، فلما وضعها في الفقراء تغامزوا على رسول الله صلى‌الله‌عليه‌وآله‌وسلم ولمزوه وقالوا : نحن الذين نقوم في الحرب وننفر معه ونقوّي أمره ، ثم يدفع الصدقات إلى هؤلاء الذين لا يعينونه ولا يغنون عنه شيئا. إنهم قالوا هذا القول وطعنوا في الرسول ، لا حبا للعدالة ، بل غضبا لأنهم لم ينالوا منها.` },
            { text: "وَلَوْ أَنَّهُمْ رَضُوا۟ مَآ ءَاتَىٰهُمُ ٱللَّهُ وَرَسُولُهُۥ وَقَالُوا۟ حَسْبُنَا ٱللَّهُ سَيُؤْتِينَا ٱللَّهُ مِن فَضْلِهِۦ وَرَسُولُهُۥٓ إِنَّآ إِلَى ٱللَّهِ رَٰغِبُونَ", tafsir: `أي ما أعطاهم الرسول بحكم ( 1) الهمزة : 2. وَقالُوا حَسْبُنَا اللهُ سَيُؤْتِينَا اللهُ مِنْ فَضْلِهِ وَرَسُولُهُ إِنَّا إِلَى اللهِ راغِبُونَ (59) إِنَّمَا الصَّدَقاتُ لِلْفُقَراءِ وَالْمَساكِينِ الله سبحانه ( وَقالُوا حَسْبُنَا اللهُ ) كافينا ( سَيُؤْتِينَا اللهُ مِنْ فَضْلِهِ ) فإن لم يقسم لنا من هذه الصدقة قسم لنا من غيرها ( وَرَسُولُهُ ) ذكر الله لأنه الآمر ، وذكر الرسول لأنه المقسم والمعطي ( إِنَّا إِلَى اللهِ راغِبُونَ ) نرغب إليه ونطلب منه سبحانه أن يوسع علينا. أي « لكان خيرا لهم » هذا هو جواب « لو » فإنه حذف للدلالة على العموم والتوسعة ، فإن المذكور إنما هو لفظ واحد بخلاف المحذوف ، ولذا قالوا : إن حذف المتعلق يفيد العموم. [60] ثم بيّن سبحانه مصرف الصدقات ، وأنها يجب أن تصرف في المصارف المذكورة لا أن تعطى للأغنياء والطامعين ( إِنَّمَا الصَّدَقاتُ لِلْفُقَراءِ ) المراد بالصدقات الزكاة ـ كما أجمع المفسرون عليه ـ وهي تؤخذ بنسبة العشر ونصف العشر وربع العشر ، من أموال تسعة ، بعنوان الوجوب ، ومن غيرها بعنوان الاستحباب ـ كما فصّل في الفقه ـ والأموال التسعة هي : الإبل ، والبقر ، والغنم ، والذهب ، والفضة ، والحنطة ، والشعير ، والتمر ، والزبيب. بشرائط مخصوصة ، وتعطى لثمانية أصناف ، منهم : الفقراء الذين لا يجدون قوت سنة لأنفسهم ولعيالهم حسب شأنهم ، لا قوة ولا فعلا. ( وَالْمَساكِينِ ) وهم أسوأ حالا من الفقير ، كأن الفقر أسكنه وَالْعامِلِينَ عَلَيْها وَالْمُؤَلَّفَةِ قُلُوبُهُمْ الأرض فلم يقدر على التحرك ، وحيث أنهم في المجتمع صنفان متمايزان ، إذ هناك صنف تعسّرت أموره وإن كان ظاهره لا بأس به ، وصنف داخل في العجزة كالعميان والزمنى ومن إليهم ، ذكرهم سبحانه صنفين ، وإن كان الميزان في الصنفين واحدا ، وهو عدم تمكنهم من مؤونة سنة فعلا وقوة. ولعل وجه تقديم الفقراء : أن إعطاءهم من الزكاة أبعد في النظر ولذا جيء بهم أولا ، تداركا لهذا البعد ، كما أنك إذا أردت أن تعدّ من أتاك تذكر الأبعد في نظر السامعين ، كما أن ذكر المساكين مع أنهم داخلون في الفقراء لعلة ، وذلك لدفع احتمال أن مثل هؤلاء لا بد وأن يعيشوا على إحسان المحسنين من الذين يتصدقون بالصدقات المستحبة لدفع البلاء ، كما جرت العادة ، لا أن يكون لهم رزق في خزينة الدولة. ( وَالْعامِلِينَ عَلَيْها ) أي الذين يعملون لأجل جمع الزكوات ، وجبايتها ، ولو كانوا أغنياء فإنهم يأخذون حق العمل ، ولفظة « على » لأجل أن العامل يقتطع من أموال الناس ، فهو شبيه بالضرر ، فإنه يعمل لأجل الفقير ، على الغني. ( وَالْمُؤَلَّفَةِ قُلُوبُهُمْ ) أي الكفار الذين يراد تأليف قلوبهم بالمال ليميلوا نحو الإسلام أو نحو المسلمين ، فإن الأموال تقرّب الناس إلى الناس ، وتقرّب الناس إلى الأديان والمبادئ ، وكذلك المسلمون الذين أسلموا ولكن لم يدخل الإسلام في قلوبهم فيعطوا من الزكاة لتقوى عقيدتهم ، ويستحكم إسلامهم. وَفِي الرِّقابِ وَالْغارِمِينَ وَفِي سَبِيلِ اللهِ وَابْنِ السَّبِيلِ فَرِيضَةً مِنَ اللهِ وَاللهُ عَلِيمٌ حَكِيمٌ (60) ( وَفِي الرِّقابِ ) جمع « رقبة » والمراد بها : الإنسان ، فإن الرقبة تستعمل في الإنسان بعلاقة الجزء والكل ، كما أن « العين » تستعمل في الجاسوس بهذه العلاقة ، والمراد بهم : العبيد الذين هم تحت الشدة ، يشترون من الزكاة ويعتقون ، وكذلك العبيد الذين كاتبوا مواليهم ولم يقدروا على دفع تمام مال الكتابة. ( وَالْغارِمِينَ ) جمع غارم ، من « غرم » بمعنى استدان ، والمراد بهم : الذين اقترضوا ثم أنفقوا المال في غير معصية ، ومن غير سرف ، فإنهم يعطون من الزكاة ليؤدّوا ديونهم ، أو تدفع ديونهم منها ولو بعد موتهم. ( وَفِي سَبِيلِ اللهِ ) وهي جميع مصالح المسلمين التي من أظهرها : الجهاد لإعلاء كلمة الله. ( وَابْنِ السَّبِيلِ ) وهو المسافر المنقطع به في سفره ، يعطى من الزكاة ليرجع إلى محله ، وإن كان في بلده غنيا. ( فَرِيضَةً مِنَ اللهِ ) أي افترض الله سبحانه تقسيم الزكاة بهذه الصورة فريضة ( وَاللهُ عَلِيمٌ ) بحاجة خلقه ( حَكِيمٌ ) فيما فرض عليهم ، وعلى من فرض. والكلام حول الزكاة طويل ، راجع « عبادات الإسلام » (1) حتى تعرف بعض أحكامها. [61] كان الكلام حول المنافقين وعلامات النفاق وبعض ما صدر منهم مما ( 1) للمؤلف. وَمِنْهُمُ الَّذِينَ يُؤْذُونَ النَّبِيَّ وَيَقُولُونَ هُوَ أُذُنٌ قُلْ أُذُنُ خَيْرٍ لَكُمْ يُؤْمِنُ بِاللهِ وَيُؤْمِنُ لِلْمُؤْمِنِينَ يدل على انحرافهم ونفاقهم ، فمنهم من يلمز النبي في الصدقات ، ومنهم من يؤذي النبي ، ومنهم من يخشى أن تنزل عليه صلى‌الله‌عليه‌وآله‌وسلم ( وَمِنْهُمُ الَّذِينَ يُؤْذُونَ النَّبِيَ ) إيذاء بالقول ، فقد كان عبد الله بن نفيل منافقا ، وكان يقعد إلى رسول الله صلى‌الله‌عليه‌وآله‌وسلم فيسمع كلامه ثم ينقله إلى المنافقين وينمّ عليه. فنزل جبرائيل عليه‌السلام وأخبر رسول الله صلى‌الله‌عليه‌وآله‌وسلم بخبر المنافق ، فدعاه رسول الله صلى‌الله‌عليه‌وآله‌وسلم فأخبره بذلك فحلف أنه لم يفعل فقبل منه الرسول صلى‌الله‌عليه‌وآله‌وسلم ـ حسب الظاهر ـ ونهاه أن يقعد مع أصحابه من بعد ، فرجع إلى أصحابه وقال : إن محمدا « أذن » أخبره الله أني أنمّ عليه وأنقل أخباره ، فقبل ، وأخبرته : أني لم أفعل ، فقبل ، فأنزل الله هذه الآية : ( وَيَقُولُونَ هُوَ أُذُنٌ ) أي يستمع إلى ما يقال له ويقبل ، ولا فطنة له بأن يميّز بين الصحيح من الكلام والسقيم. ( قُلْ ) يا رسول الله لهؤلاء المنافقين : إني ( أُذُنُ خَيْرٍ لَكُمْ ) فإنه صلى‌الله‌عليه‌وآله‌وسلم أذن كما قالوا ، ولكن ليس كما قصدوا ، فإن « الأذن » قد يكون في سماع كلام الشر في أحد ثم يرتّب الأثر عليه ، وقد يكون خيرا ، يسمع الكلام ولا يكذّبه ، ولكنه لا يرتّب ما على المجرم من العقاب ، كيف يمكن أن يعاب عليه فعله هذا ؟! لكن المنافق هو الذي يرى الإحسان ـ حتى بالنسبة إلى المنافق ـ إساءة. ( يُؤْمِنُ بِاللهِ ) إيمانا من القلب ، ويعلم أن الله سبحانه صادق ( وَيُؤْمِنُ لِلْمُؤْمِنِينَ ) أي لنفع المؤمنين ، وفرق بين « الإيمان به » إذ معناه تصديقه ، و « الإيمان له » ، أي يرتب الأثر الذي هو نافع للمؤمن ، سواء وَرَحْمَةٌ لِلَّذِينَ آمَنُوا مِنْكُمْ وَالَّذِينَ يُؤْذُونَ رَسُولَ اللهِ لَهُمْ عَذابٌ أَلِيمٌ (61) يَحْلِفُونَ بِاللهِ لَكُمْ لِيُرْضُوكُمْ وَاللهُ وَرَسُولُهُ أَحَقُّ أَنْ يُرْضُوهُ اعتقد بذلك أم لم يعتقد. فقد اعتقد الرسول صلى‌الله‌عليه‌وآله‌وسلم صحة كلام جبرئيل المنزل من قبله سبحانه ، كما رتّب أثر الصحة لنفع ذلك المؤمن ـ المنافق ـ حيث لم يعاقبه. ولا يخفى أن « الإيمان » له إطلاقان : إطلاق على كل مؤمن مقابل الكافر ، وهو من أظهر الإسلام ، وإن لم يدخل في قلبه ، كما قال سبحانه : ( يا أَيُّهَا الَّذِينَ آمَنُوا آمِنُوا ) (1) ، وإطلاق على المعتقد في مقابل المنافق ، كما قال سبحانه : ( قالَتِ الْأَعْرابُ آمَنَّا قُلْ لَمْ تُؤْمِنُوا وَلكِنْ قُولُوا أَسْلَمْنا ) (2) ، والمراد هنا : الإطلاق الأول. ( وَ ) هو صلى‌الله‌عليه‌وآله‌وسلم ( رَحْمَةٌ لِلَّذِينَ آمَنُوا مِنْكُمْ ) ولو إيمانا ظاهريا ، حيث أنه هداهم للأصلح بحالهم في الدنيا ، أما المؤمن الحقيقي فإنه سعد بالرسول صلى‌الله‌عليه‌وآله‌وسلم دنيا وآخرة ( وَالَّذِينَ يُؤْذُونَ رَسُولَ اللهِ ) بالقول أو العمل ، لا يظنون أنهم فاتوه حيث لم يعاقبهم وقبل عذرهم ، فلم يرتّب على أذيتهم شيء ، بل ( لَهُمْ عَذابٌ أَلِيمٌ ) مؤلم موجع في الدنيا والآخرة ، أما في الدنيا فلأن إيذاء الرسول له أثر وضعي يوجب الخسران والخزي ، وأما في الآخرة فله عذاب أليم في النار.` },
            { text: "إِنَّمَا ٱلصَّدَقَٰتُ لِلْفُقَرَآءِ وَٱلْمَسَٰكِينِ وَٱلْعَٰمِلِينَ عَلَيْهَا وَٱلْمُؤَلَّفَةِ قُلُوبُهُمْ وَفِى ٱلرِّقَابِ وَٱلْغَٰرِمِينَ وَفِى سَبِيلِ ٱللَّهِ وَٱبْنِ ٱلسَّبِيلِ فَرِيضَةً مِّنَ ٱللَّهِ وَٱللَّهُ عَلِيمٌ حَكِيمٌ", tafsir: `` },
            { text: "وَمِنْهُمُ ٱلَّذِينَ يُؤْذُونَ ٱلنَّبِىَّ وَيَقُولُونَ هُوَ أُذُنٌ قُلْ أُذُنُ خَيْرٍ لَّكُمْ يُؤْمِنُ بِٱللَّهِ وَيُؤْمِنُ لِلْمُؤْمِنِينَ وَرَحْمَةٌ لِّلَّذِينَ ءَامَنُوا۟ مِنكُمْ وَٱلَّذِينَ يُؤْذُونَ رَسُولَ ٱللَّهِ لَهُمْ عَذَابٌ أَلِيمٌ", tafsir: `` },
            { text: "يَحْلِفُونَ بِٱللَّهِ لَكُمْ لِيُرْضُوكُمْ وَٱللَّهُ وَرَسُولُهُۥٓ أَحَقُّ أَن يُرْضُوهُ إِن كَانُوا۟ مُؤْمِنِينَ", tafsir: `أي يحلف هؤلاء المنافقون ( لَكُمْ لِيُرْضُوكُمْ ) حيث أنكم تقبلون عذرهم إذا أقسموا بالله بأنهم لم يقولوا ما قالوا ، ولم يفعلوا ما فعلوا ( وَاللهُ وَرَسُولُهُ أَحَقُّ أَنْ يُرْضُوهُ ) أي يرضوا كل واحد ( 1) النساء : 137. ( 2) الحجرات : 15. إِنْ كانُوا مُؤْمِنِينَ (62) أَ لَمْ يَعْلَمُوا أَنَّهُ مَنْ يُحادِدِ اللهَ وَرَسُولَهُ فَأَنَّ لَهُ نارَ جَهَنَّمَ خالِداً فِيها ذلِكَ الْخِزْيُ الْعَظِيمُ (63) يَحْذَرُ الْمُنافِقُونَ أَنْ تُنَزَّلَ عَلَيْهِمْ سُورَةٌ تُنَبِّئُهُمْ بِما فِي قُلُوبِهِمْ منهما ، بالإيمان الصحيح وعدم الإيذاء واقعا ـ مما يريدون ستره بالحلف ـ أما الترضية الظاهرية للرسول ، فإنها لا تنفعهم في الباطن والواقع ( إِنْ كانُوا مُؤْمِنِينَ ) واقعا ، والمعنى : إن كانوا مؤمنين واقعا لعلموا أن مرضاة الله والرسول أولى من الترضية الظاهرية.` },
            { text: "أَلَمْ يَعْلَمُوٓا۟ أَنَّهُۥ مَن يُحَادِدِ ٱللَّهَ وَرَسُولَهُۥ فَأَنَّ لَهُۥ نَارَ جَهَنَّمَ خَٰلِدًا فِيهَا ذَٰلِكَ ٱلْخِزْىُ ٱلْعَظِيمُ", tafsir: `أليس يعرف هؤلاء المنافقون ( أَنَّهُ مَنْ يُحادِدِ اللهَ وَرَسُولَهُ ) « المحادّة » مجاوزة الحد بالمشاقة والمخالفة ( فَأَنَّ لَهُ نارَ جَهَنَّمَ خالِداً فِيها ) فإن علموا ذلك فكيف يحادّون الله والرسول بالنفاق وإيذاء الرسول ( ذلِكَ ) الخلود في النار ( الْخِزْيُ ) أي الهوان ( الْعَظِيمُ ) الذي لا خزي فوقه.` },
            { text: "يَحْذَرُ ٱلْمُنَٰفِقُونَ أَن تُنَزَّلَ عَلَيْهِمْ سُورَةٌ تُنَبِّئُهُم بِمَا فِى قُلُوبِهِمْ قُلِ ٱسْتَهْزِءُوٓا۟ إِنَّ ٱللَّهَ مُخْرِجٌ مَّا تَحْذَرُونَ", tafsir: `أي يخافون ويخشون ( أَنْ تُنَزَّلَ عَلَيْهِمْ سُورَةٌ ) من القرآن ( تُنَبِّئُهُمْ بِما فِي قُلُوبِهِمْ ) أي تخبرهم بنفاقهم ، فتكون فضيحة لهم ، وقوله « تنبئهم » لإفادة أنهم كانوا يخفون نفاقهم ، فكأنهم لا يعلمون. وإنما السورة المنزلة تخبرهم حسب تظاهرهم بالنفاق. ورد أنه لما خرج رسول الله صلى‌الله‌عليه‌وآله‌وسلم إلى « تبوك » قال قوم من المنافقين فيما بينهم : أ يرى محمدا أن حرب الروم مثل حرب غيرهم ، لا يرجع منهم أحد أبدا. فقال بعضهم : ما أحرى أن يخبر الله محمدا بما كنّا فيه ، وبما في قلوبنا ، وينزل بهذا قرآنا يقرأه الناس ـ قالوا هذا قُلِ اسْتَهْزِؤُا إِنَّ اللهَ مُخْرِجٌ ما تَحْذَرُونَ (64) وَلَئِنْ سَأَلْتَهُمْ لَيَقُولُنَّ إِنَّما كُنَّا نَخُوضُ وَنَلْعَبُ قُلْ أَ بِاللهِ وَآياتِهِ وَرَسُولِهِ كُنْتُمْ تَسْتَهْزِؤُنَ (65) لا تَعْتَذِرُوا قَدْ كَفَرْتُمْ بَعْدَ إِيمانِكُمْ على حد الاستهزاء ـ فقال رسول الله صلى‌الله‌عليه‌وآله‌وسلم لعمار بن ياسر : الحق القوم فإنهم قد انحرفوا ، فلحقهم عمار فقال لهم : ما قلتم ؟ قالوا : ما قلنا شيئا إنما نقول ذلك على حد اللعب والمزاح. فنزلت هذه الآية. ( قُلِ ) يا رسول الله لهؤلاء المنافقين : ( اسْتَهْزِؤُا ) أمر في معنى الوعيد ( إِنَّ اللهَ مُخْرِجٌ ما تَحْذَرُونَ ) أي مظهر ما تحذرون ظهوره من نفاقكم وقولكم الاستهزائي.` },
            { text: "وَلَئِن سَأَلْتَهُمْ لَيَقُولُنَّ إِنَّمَا كُنَّا نَخُوضُ وَنَلْعَبُ قُلْ أَبِٱللَّهِ وَءَايَٰتِهِۦ وَرَسُولِهِۦ كُنتُمْ تَسْتَهْزِءُونَ", tafsir: `يا رسول الله ! عن طعنهم في الدين واستهزائهم بك وبحركاتك ، وقلت لهم : لم فعلتم ذلك ؟ ( لَيَقُولُنَّ إِنَّما كُنَّا نَخُوضُ وَنَلْعَبُ ) « الخوض » هو دخول القدم في المائع ، من ماء أو طين ، ثم كثر استعماله في الدخول فيها ، يعني : على وجه اللهو دون الجد ، أي كان كلامنا مجرد لعب ولهو دون إرادة الحقيقة والجد ( قُلْ ) يا رسول الله لهم : ( أَ بِاللهِ وَآياتِهِ وَرَسُولِهِ كُنْتُمْ تَسْتَهْزِؤُنَ ) استفهام إنكاري ، أي كيف تستهزئون بالله وحججه ورسوله ؟ [66] قل يا رسول الله لهؤلاء المنافقين : ( لا تَعْتَذِرُوا ) بهذه الأعذار الواهية الكاذبة ( قَدْ كَفَرْتُمْ بَعْدَ إِيمانِكُمْ ) الظاهري ، فإنهم بإظهارهم الإيمان دخلوا في زمرة المؤمنين ، فاستهزاؤهم هذا كان كفرا ونقضا لذلك الإيمان ، وقد اعتذر بعضهم اعتذارا صادقا فرجع عن نفاقه ودخل إِنْ نَعْفُ عَنْ طائِفَةٍ مِنْكُمْ نُعَذِّبْ طائِفَةً بِأَنَّهُمْ كانُوا مُجْرِمِينَ (66) الْمُنافِقُونَ وَالْمُنافِقاتُ بَعْضُهُمْ مِنْ بَعْضٍ يَأْمُرُونَ بِالْمُنْكَرِ وَيَنْهَوْنَ عَنِ الْمَعْرُوفِ وَيَقْبِضُونَ أَيْدِيَهُمْ نَسُوا اللهَ فَنَسِيَهُمْ إِنَّ الْمُنافِقِينَ هُمُ الْفاسِقُونَ (67) الإيمان قلبه ، فقبل الرسول عذره وعفا الله عنه. وفي بعض التفاسير : إنه كان مخشي بن حميّر ، ويسمى عبد الرحمن ، وسأل الله بعد توبته أن يقتل شهيدا لا يعلم أحد مكانه ، فقتل يوم اليمامة ولم يوجد له أثر ، ولذا قال سبحانه : ( إِنْ نَعْفُ عَنْ طائِفَةٍ مِنْكُمْ ) وهو التائب حقيقة ( نُعَذِّبْ طائِفَةً ) بسبب أنهم بقوا على نفاقهم و ( كانُوا مُجْرِمِينَ ) لم ينفكوا عن الجريمة. [67] ثم بيّن سبحانه حقيقة المنافقين وصفاتهم بقوله تعالى : ( الْمُنافِقُونَ وَالْمُنافِقاتُ بَعْضُهُمْ مِنْ بَعْضٍ ) أي أنهم من طبيعة واحدة وطينة واحدة ( يَأْمُرُونَ بِالْمُنْكَرِ ) يأمر بعضهم بعضا بإتيان المنكر ، من الكفر والمعاصي ( وَيَنْهَوْنَ عَنِ الْمَعْرُوفِ ) فإذا أراد أحدهم أن يعمل بطاعة نهاه غيره ( وَيَقْبِضُونَ أَيْدِيَهُمْ ) يمسكونها عن الإنفاق ، بخلاف المؤمن الذي يبسط يده بالمال ، أو المراد : قبض أيديهم عن كل خير ( نَسُوا اللهَ ) عملوا عمل الناسي وإن كانوا ذاكرين له ، فكما أن الناسي يترك المنسي ، كذلك هؤلاء يتركون أوامر الله سبحانه ( فَنَسِيَهُمْ ) الله سبحانه أي تركهم وشأنهم لا يهديهم طريقا ولا يفعل بهم صلاحا. وليس المراد « النسيان » حقيقة ، لأن الله سبحانه لا ينسى ( إِنَّ الْمُنافِقِينَ هُمُ الْفاسِقُونَ ) الذين خرجوا عن طاعة الله سبحانه ، وإن أظهروا وَعَدَ اللهُ الْمُنافِقِينَ وَالْمُنافِقاتِ وَالْكُفَّارَ نارَ جَهَنَّمَ خالِدِينَ فِيها هِيَ حَسْبُهُمْ وَلَعَنَهُمُ اللهُ وَلَهُمْ عَذابٌ مُقِيمٌ (68) كَالَّذِينَ مِنْ قَبْلِكُمْ كانُوا أَشَدَّ مِنْكُمْ قُوَّةً وَأَكْثَرَ أَمْوالاً وَأَوْلاداً الإيمان ، و « الفسق » عبارة عن الخروج عن الطاعة. وهذه الآية تعطي ميزان النفاق إلى يومنا ، وما أكثر أمثال هؤلاء في زماننا هذا.` },
            { text: "لَا تَعْتَذِرُوا۟ قَدْ كَفَرْتُم بَعْدَ إِيمَٰنِكُمْ إِن نَّعْفُ عَن طَآئِفَةٍ مِّنكُمْ نُعَذِّبْ طَآئِفَةًۢ بِأَنَّهُمْ كَانُوا۟ مُجْرِمِينَ", tafsir: `` },
            { text: "ٱلْمُنَٰفِقُونَ وَٱلْمُنَٰفِقَٰتُ بَعْضُهُم مِّنۢ بَعْضٍ يَأْمُرُونَ بِٱلْمُنكَرِ وَيَنْهَوْنَ عَنِ ٱلْمَعْرُوفِ وَيَقْبِضُونَ أَيْدِيَهُمْ نَسُوا۟ ٱللَّهَ فَنَسِيَهُمْ إِنَّ ٱلْمُنَٰفِقِينَ هُمُ ٱلْفَٰسِقُونَ", tafsir: `` },
            { text: "وَعَدَ ٱللَّهُ ٱلْمُنَٰفِقِينَ وَٱلْمُنَٰفِقَٰتِ وَٱلْكُفَّارَ نَارَ جَهَنَّمَ خَٰلِدِينَ فِيهَا هِىَ حَسْبُهُمْ وَلَعَنَهُمُ ٱللَّهُ وَلَهُمْ عَذَابٌ مُّقِيمٌ", tafsir: `وحيث كان الكلام حول المنافقين مفصلا ، أما الكفار فذكرهم استطراد ( نارَ جَهَنَّمَ ) يعذبهم بها جزاء لما اقترفوا من الآثام ( خالِدِينَ فِيها ) دائمين لا يخرجون منها ( هِيَ حَسْبُهُمْ ) أي أن النار تكفيهم جزاء لذنوبهم وكفرهم ونفاقهم ( وَلَعَنَهُمُ اللهُ ) طردهم عن نعيمه ورضوانه ، فإن اللعن بمعنى الطرد ( وَلَهُمْ عَذابٌ مُقِيمٌ ) يقيم عليهم فلا يجدون خلاصا منه. ولعل المراد بذلك : العذاب العام في الدنيا والآخرة ، فإن النفاق خلة يكون صاحبها دائم التعب والنصب لأنه بين المؤمن ، المهين له ، الحذر منه ، وبين الكافر الذي لا يقبله لأنه لم يتمسك بالكفر كما تمسك الكافر الصريح بكفره. [69] إن هؤلاء المنافقين حالهم كحال الذين ( مِنْ قَبْلِكُمْ ) من الكفار والمنافقين الذين كانوا يظهرون الإيمان بالأنبياء ويبطنون الكفر ، أو يحادّون الأنبياء ويكفرون بما أنزل إليهم ( كانُوا أَشَدَّ مِنْكُمْ قُوَّةً ) فإن بعض الأمم كانت قواهم المادية والجسمية أكثر من أمة الرسول صلى‌الله‌عليه‌وآله‌وسلم ـ كما يشهد بذلك التاريخ ـ ( وَأَكْثَرَ أَمْوالاً وَأَوْلاداً ) لخصوبة النسل فيهم فَاسْتَمْتَعُوا بِخَلاقِهِمْ فَاسْتَمْتَعْتُمْ بِخَلاقِكُمْ كَمَا اسْتَمْتَعَ الَّذِينَ مِنْ قَبْلِكُمْ بِخَلاقِهِمْ وَخُضْتُمْ كَالَّذِي خاضُوا أُولئِكَ حَبِطَتْ أَعْمالُهُمْ فِي الدُّنْيا وَالْآخِرَةِ وَأُولئِكَ هُمُ الْخاسِرُونَ (69) وازدهار التجارة والعمران عندهم ( فَاسْتَمْتَعُوا بِخَلاقِهِمْ ) « الخلاق » النصيب ، أي صرفوا نصيبهم من المال والقوة والأولاد في الاستمتاع والملذات عوض أن يصرفوها في شكر المنعم وما أمر به ( فَاسْتَمْتَعْتُمْ ) أنتم ـ يا أمة محمد صلى‌الله‌عليه‌وآله‌وسلم ـ أي المنافقون منهم ( بِخَلاقِكُمْ ) أي بنصيبكم ( كَمَا اسْتَمْتَعَ الَّذِينَ مِنْ قَبْلِكُمْ بِخَلاقِهِمْ ) دون أن تعتبروا بمصيرهم فتصرفوا نعم الله سبحانه فيما أمر ( وَخُضْتُمْ ) في الكفر والاستهزاء وملاذ الدنيا ( كَالَّذِي خاضُوا ) أي كخوض أولئك الأولين ( أُولئِكَ ) الذين صنعوا هذه الصنائع السيئة ( حَبِطَتْ أَعْمالُهُمْ ) الحسنة ، لأن الحسنة لا تقبل مع الكفر والنفاق والعصيان ، قال سبحانه : ( إِنَّما يَتَقَبَّلُ اللهُ مِنَ الْمُتَّقِينَ ) (1) . ومعنى الحبط ذهاب الأجر ( فِي الدُّنْيا ) إذ لم ينتفعوا بها ، فإن الانحراف عن مناهج الله سبحانه يوجب المشاكل التي لا تكافأ بها الأعمال ، فمثلا الثروة توجب رفاه الإنسان ، أما إذا كانت مقترنة بالانحراف فإنها توجب الضنك والضيق عوض الرفاه ( وَالْآخِرَةِ ) فلا ثواب لأعمالهم الخيرة ( وَأُولئِكَ هُمُ الْخاسِرُونَ ) الذين خسروا أنفسهم وكل شيء عندهم. ( 1) المائدة : 28. أَ لَمْ يَأْتِهِمْ نَبَأُ الَّذِينَ مِنْ قَبْلِهِمْ قَوْمِ نُوحٍ وَعادٍ وَثَمُودَ وَقَوْمِ إِبْراهِيمَ وَأَصْحابِ مَدْيَنَ وَالْمُؤْتَفِكاتِ أَتَتْهُمْ رُسُلُهُمْ بِالْبَيِّناتِ فَما كانَ اللهُ لِيَظْلِمَهُمْ وَلكِنْ كانُوا أَنْفُسَهُمْ يَظْلِمُونَ (70) وَالْمُؤْمِنُونَ وَالْمُؤْمِناتُ بَعْضُهُمْ أَوْلِياءُ بَعْضٍ` },
            { text: "كَٱلَّذِينَ مِن قَبْلِكُمْ كَانُوٓا۟ أَشَدَّ مِنكُمْ قُوَّةً وَأَكْثَرَ أَمْوَٰلًا وَأَوْلَٰدًا فَٱسْتَمْتَعُوا۟ بِخَلَٰقِهِمْ فَٱسْتَمْتَعْتُم بِخَلَٰقِكُمْ كَمَا ٱسْتَمْتَعَ ٱلَّذِينَ مِن قَبْلِكُم بِخَلَٰقِهِمْ وَخُضْتُمْ كَٱلَّذِى خَاضُوٓا۟ أُو۟لَٰٓئِكَ حَبِطَتْ أَعْمَٰلُهُمْ فِى ٱلدُّنْيَا وَٱلْـَٔاخِرَةِ وَأُو۟لَٰٓئِكَ هُمُ ٱلْخَٰسِرُونَ", tafsir: `` },
            { text: "أَلَمْ يَأْتِهِمْ نَبَأُ ٱلَّذِينَ مِن قَبْلِهِمْ قَوْمِ نُوحٍ وَعَادٍ وَثَمُودَ وَقَوْمِ إِبْرَٰهِيمَ وَأَصْحَٰبِ مَدْيَنَ وَٱلْمُؤْتَفِكَٰتِ أَتَتْهُمْ رُسُلُهُم بِٱلْبَيِّنَٰتِ فَمَا كَانَ ٱللَّهُ لِيَظْلِمَهُمْ وَلَٰكِن كَانُوٓا۟ أَنفُسَهُمْ يَظْلِمُونَ", tafsir: `استفهام إنكاري ، أي ألم يأت إلى هؤلاء المنافقين ( نَبَأُ ) أي خبر ( الَّذِينَ مِنْ قَبْلِهِمْ ) من الأمم ( قَوْمِ نُوحٍ ) عليه‌السلام حيث أهلكهم الله بالغرق ( وَعادٍ ) قوم هود عليه‌السلام أهلكهم الله بالريح ( وَثَمُودَ ) قوم صالح عليه‌السلام أهلكهم بالرجفة ( وَقَوْمِ إِبْراهِيمَ ) عليه‌السلام نمرود وأتباعه ، حيث سلب الله ملكهم ونعمتهم ( وَأَصْحابِ مَدْيَنَ ) قوم شعيب عليه‌السلام أهلكهم بعذاب يوم الظلة ( وَالْمُؤْتَفِكاتِ ) من « ائتفك » بمعنى انقلب ، أي البلاد التي انقلبت وهي بلاد قوم لوط عليه‌السلام حيث أهلكوا ، وذلك أن الله سبحانه أمر جبرائيل فقلب تلك المدن بأن جعل عاليها سافلها ( أَتَتْهُمْ رُسُلُهُمْ بِالْبَيِّناتِ ) أي بالحجج الظاهرة والأدلة البينة ، لكنهم عصوا وأبوا وتمردوا على الله ورسله فأهلكهم الله بذنوبهم وما ( كانَ اللهُ لِيَظْلِمَهُمْ ) فتعذيبهم بأنواع العذاب لم يكن ظلما منه سبحانه لهم ( وَلكِنْ كانُوا أَنْفُسَهُمْ يَظْلِمُونَ ) فقد عوقبوا بسبب تمرّدهم وعصيانهم ، وهؤلاء الكفار والمنافقون حالهم حال أولئك ، إن تمردوا وعصوا أخذوا بذنوبهم ، فليحذروا أن يصيبهم ما أصاب من قبلهم. [71] ولما بيّن سبحانه صفات المنافقين وما فعل بهم كما فعل بأسلافهم ، بيّن صفات المؤمنين والعاقبة الحسنة التي تنتظرهم ( وَالْمُؤْمِنُونَ وَالْمُؤْمِناتُ بَعْضُهُمْ أَوْلِياءُ بَعْضٍ ) فإن كل واحد منهم ينصر صاحبه يَأْمُرُونَ بِالْمَعْرُوفِ وَيَنْهَوْنَ عَنِ الْمُنْكَرِ وَيُقِيمُونَ الصَّلاةَ وَيُؤْتُونَ الزَّكاةَ وَيُطِيعُونَ اللهَ وَرَسُولَهُ أُولئِكَ سَيَرْحَمُهُمُ اللهُ إِنَّ اللهَ عَزِيزٌ حَكِيمٌ (71) وَعَدَ اللهُ الْمُؤْمِنِينَ وَالْمُؤْمِناتِ جَنَّاتٍ تَجْرِي مِنْ تَحْتِهَا الْأَنْهارُ خالِدِينَ فِيها وَمَساكِنَ ويؤيده ويعينه ، لأنهم من عنصر واحد وأصل واحد وتجمعهم عقيدة واحدة ( يَأْمُرُونَ بِالْمَعْرُوفِ ) أي الأمور الحسنة التي يعرفها الناس من واجب أو مندوب شرعا وعقلا ( وَيَنْهَوْنَ عَنِ الْمُنْكَرِ ) الذي ينكره الناس من حرام أو مكروه شرعا وعقلا ( وَيُقِيمُونَ الصَّلاةَ ) يداومون على فعلها ويحثّون الناس عليها ( وَيُؤْتُونَ الزَّكاةَ ) أي الحق المفروض ، أو مطلق الصدقة ، فإن الزكاة تطلق عليهما ( وَيُطِيعُونَ اللهَ وَرَسُولَهُ ) فيما يأمرهم وينهاهم ( أُولئِكَ ) المؤمنون الذين هذه صفاتهم ( سَيَرْحَمُهُمُ اللهُ ) إما المراد : رحمتهم في الجنة ، ولذا دخلت « السين » ، وإما المراد : في الدنيا ، ودخول « السين » لإفادة كون الرحمة إنما تأتي بعد مدة من استمرارهم في العمل ونجاحهم في الامتحان ، فلا يتوقع المؤمن أن تشمله الرحمة فورا بمجرد وقوعه في مشكلة ، وإنما تؤخر عنه للامتحان والاختبار ( إِنَّ اللهَ عَزِيزٌ ) غالب على أمره متمكن من إنفاذ إرادته ( حَكِيمٌ ) في تدبيره وفعله ، فيفعل الأشياء حسب المصلحة.` },
            { text: "وَٱلْمُؤْمِنُونَ وَٱلْمُؤْمِنَٰتُ بَعْضُهُمْ أَوْلِيَآءُ بَعْضٍ يَأْمُرُونَ بِٱلْمَعْرُوفِ وَيَنْهَوْنَ عَنِ ٱلْمُنكَرِ وَيُقِيمُونَ ٱلصَّلَوٰةَ وَيُؤْتُونَ ٱلزَّكَوٰةَ وَيُطِيعُونَ ٱللَّهَ وَرَسُولَهُۥٓ أُو۟لَٰٓئِكَ سَيَرْحَمُهُمُ ٱللَّهُ إِنَّ ٱللَّهَ عَزِيزٌ حَكِيمٌ", tafsir: `` },
            { text: "وَعَدَ ٱللَّهُ ٱلْمُؤْمِنِينَ وَٱلْمُؤْمِنَٰتِ جَنَّٰتٍ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ خَٰلِدِينَ فِيهَا وَمَسَٰكِنَ طَيِّبَةً فِى جَنَّٰتِ عَدْنٍ وَرِضْوَٰنٌ مِّنَ ٱللَّهِ أَكْبَرُ ذَٰلِكَ هُوَ ٱلْفَوْزُ ٱلْعَظِيمُ", tafsir: `بالإضافة إلى الخير في هذه الحياة ( جَنَّاتٍ تَجْرِي مِنْ تَحْتِهَا الْأَنْهارُ ) من تحت قصورها وأشجارها ( خالِدِينَ فِيها ) دائمين لا يزولون عنها ( وَ ) وعدهم ( مَساكِنَ طَيِّبَةً فِي جَنَّاتِ عَدْنٍ وَرِضْوانٌ مِنَ اللهِ أَكْبَرُ ذلِكَ هُوَ الْفَوْزُ الْعَظِيمُ (72) يا أَيُّهَا النَّبِيُّ جاهِدِ الْكُفَّارَ وَالْمُنافِقِينَ طَيِّبَةً ) مهيأة فيها الأثاث والرياش ، طيبة الهواء والمرافق بحيث يطيب فيها العيش ( فِي جَنَّاتِ عَدْنٍ ) العدن ، والإقامة والخلود ، نظائر ، أي أنهم في جنات الخلود. و ورد في بعض الأحاديث : « إنها أعلى الجنان مما لم يخطر على قلب بشر » (1) ( وَرِضْوانٌ مِنَ اللهِ أَكْبَرُ ) أي أن رضاه سبحانه على هؤلاء المؤمنين أكبر من كل ذلك ، فإن الإنسان إذا علم برضى الكبير منه ارتاح ضميره ، فكيف به لو علم برضاه سبحانه عنه. ومن المعلوم أن ارتياح الضمير أكبر من ارتياح الجسد. ( ذلِكَ ) النعيم الجسدي والروحي للمؤمنين والمؤمنات ( هُوَ الْفَوْزُ ) والنجاح ( الْعَظِيمُ ) الذي لا نجاح فوقه ولا فوز أكبر منه وأعظم. [73] وحيث ذكر سبحانه أحوال الكفار والمنافقين وبيّن صفاتهم الذميمة ، أوجب الجهاد لتخليص البشرية منهم ( يا أَيُّهَا النَّبِيُ ) صلى‌الله‌عليه‌وآله‌وسلم ( جاهِدِ الْكُفَّارَ ) بالمقاتلة والمحاربة وبيان عقائدهم السخيفة ، فإن هذا الجهاد نوع من أنواع الحرب الباردة ـ في الاصطلاح الحديث ـ ( وَالْمُنافِقِينَ ) وجهاد المنافقين بالوعظ والإنذار لهم ، وإجراء الحدود عليهم ، وتخويف الناس من النفاق. وقد كان النبي صلى‌الله‌عليه‌وآله‌وسلم يجاهدهم مرة بإظهار نفاقهم ، وتارة بضرب الحصار عليهم ، كما قال سبحانه : ( 1) المستدرك : ج 6 ص 62. وَاغْلُظْ عَلَيْهِمْ وَمَأْواهُمْ جَهَنَّمُ وَبِئْسَ الْمَصِيرُ (73) يَحْلِفُونَ بِاللهِ ما قالُوا وَلَقَدْ قالُوا كَلِمَةَ الْكُفْرِ ( وَعَلَى الثَّلاثَةِ الَّذِينَ خُلِّفُوا ) (1) ، وأخرى بنهي المؤمنين عن أن يتصفوا بخلة النفاق. ومن المحتمل أن يراد بالمنافق هنا : الكافر المنافق ، فإن بعض الكفار ينافق بإظهار الودّ للمسلم وتأليفه وهو ألد الأعداء له ، في مقابل الكافر الصريح الذي يظهر عداءه وشحناءه. ( وَاغْلُظْ عَلَيْهِمْ ) حتى يرتدعوا ، فإن الغلظة في الكلام والسلوك مع شخص خليق بأن يردعه عن عمله ، كما قال سبحانه : ( أَشِدَّاءُ عَلَى الْكُفَّارِ ) (2) ، ( وَمَأْواهُمْ ) أي محلهم ومصيرهم ، من « أوى » إذا اتخذ مكانا ( جَهَنَّمُ وَبِئْسَ الْمَصِيرُ ) أي بئس المرجع والمأوى لهم. [74] ومن المنافقين من يتأمرون على الرسول صلى‌الله‌عليه‌وآله‌وسلم ويقولون عنه أشياء ، إذا استنطقهم الرسول حلفوا بالله كذبا أنه لم يصدر منهم شيء ، فقد كان جماعة منهم خرجوا مع الرسول صلى‌الله‌عليه‌وآله‌وسلم إلى « تبوك » وكانوا كارهين لذلك ، فإذا خلا بعضهم إلى بعض سبوا الرسول صلى‌الله‌عليه‌وآله‌وسلم وانتقصوه ، فأبلغ ذلك « حذيفة » إلى الرسول صلى‌الله‌عليه‌وآله‌وسلم فطلبهم وقال : ما هذا الذي بلغني عنكم. فأخذوا يحلفون بالله ما قالوا شيئا ، فأنزل الله سبحانه هذه الآية تفضحهم ( يَحْلِفُونَ بِاللهِ ما قالُوا ) أي أقسم هؤلاء المنافقون بالله بأنهم لم يقولوا شيئا ضد الرسول صلى‌الله‌عليه‌وآله‌وسلم ( وَلَقَدْ قالُوا كَلِمَةَ الْكُفْرِ ) فإنهم ( 1) التوبة : 118. ( 2) الفتح : 30. وَكَفَرُوا بَعْدَ إِسْلامِهِمْ وَهَمُّوا بِما لَمْ يَنالُوا وَما نَقَمُوا إِلاَّ أَنْ أَغْناهُمُ اللهُ وَرَسُولُهُ مِنْ فَضْلِهِ بسبّ النبي صلى‌الله‌عليه‌وآله‌وسلم والطعن في الإسلام صاروا كفارا ( وَكَفَرُوا بَعْدَ إِسْلامِهِمْ ) الظاهري ، فإن المنافق إذا أظهر الإسلام صار مسلما ، فإذا صدرت منه كلمة الكفر صار كافرا. لا يقال : إنهم إن كفروا وجب عليهم حدّ المرتد. لأنا نقول : إنهم كانوا مرتدين عن ملّة ، ولا يحدّ مثلهم ، وإنما يستتابوا ، وإنكارهم كان بمنزلة التوبة ، وإن كان توبة صورية لا حقيقية. ( وَهَمُّوا بِما لَمْ يَنالُوا ) فقد أرادوا إخفاء نور الإسلام ، وذلك يتحقق بكل ما يهتم به المنافق من إرادة قتل النبي ، وإيجاد الفساد بين المسلمين ، وإخراج الرسول صلى‌الله‌عليه‌وآله‌وسلم من المدينة ، لكنهم لم ينالوا ذلك ولم يقدروا على ما هموا به ، بل انعكس الأمر فقد زاد الإسلام علوّا ، والرسول ارتفاعا ، والمسلمون سموّا. وقد ورد في بعض الأحاديث : تأويل الآية بالذين خالفوا الرسول في قصة « غدير خم » وأرادوا إخماد نور الوصي ، وقالوا في الرسول كلاما بذيئا (1) . ( وَما نَقَمُوا ) النقمة الإنكار والغضب ، أي أن هؤلاء لم ينكروا على المسلمين ( إِلَّا أَنْ أَغْناهُمُ اللهُ وَرَسُولُهُ مِنْ فَضْلِهِ ) فإن الله سبحانه أغنى المسلمين وأنعم عليهم ، بفضل إرشادات الرسول ، فلم يكن ( 1) بحار الأنوار : ج 37 ص 115. فَإِنْ يَتُوبُوا يَكُ خَيْراً لَهُمْ وَإِنْ يَتَوَلَّوْا يُعَذِّبْهُمُ اللهُ عَذاباً أَلِيماً فِي الدُّنْيا وَالْآخِرَةِ وَما لَهُمْ فِي الْأَرْضِ مِنْ وَلِيٍّ وَلا نَصِيرٍ (74) وَمِنْهُمْ مَنْ عاهَدَ اللهَ لَئِنْ آتانا للمسلمين ذنب يستحقون به النقمة من المنافقين ، ولكن المنافقين كرهوا ذلك حسدا ، أو المراد : أن الله أغنى هؤلاء المنافقين ، فكان من اللازم أن يحبوا الله ورسوله حيث أعطاهم الغنائم لكنهم جعلوا مكان الشكر كفرانا ، كما يقال : « لم يكرهني فلان إلا لأني أحسنت إليه » . ( فَإِنْ يَتُوبُوا ) عن نفاقهم ويرجعوا إلى الحق ( يَكُ خَيْراً لَهُمْ ) في دنياهم وفي آخرتهم حيث يكونون كسائر المسلمين لا يجتنب أحد منهم ولا يكرههم المسلمون ، ويقال في مثل هذه المواضع « خير » مقابل ما يظن أنه خير ، وإن لم يكن إلا شرا واقعا ( وَإِنْ يَتَوَلَّوْا ) أي يستمروا على إعراضهم عن الحق وسلوكهم سبيل النفاق ( يُعَذِّبْهُمُ اللهُ عَذاباً أَلِيماً ) مؤلما موجعا ( فِي الدُّنْيا ) باجتناب المسلمين لهم ، وتضييق العيش عليهم ، كما قال سبحانه : ( وَمَنْ أَعْرَضَ عَنْ ذِكْرِي فَإِنَّ لَهُ مَعِيشَةً ضَنْكاً ) (1) ، ( وَ ) في ( الْآخِرَةِ ) بالنكال والنار ( وَما لَهُمْ ) ليس لهم ( فِي الْأَرْضِ مِنْ وَلِيٍ ) يلي أمورهم ويحبهم ( وَلا نَصِيرٍ ) ينصرهم ، فليس كما ظنوا أن المنافقين ينصرونهم إذا وقعوا في المشاكل ، فإن المنافق حيث اختمر على طبيعة النفاق ، لا ينصر حتى أخاه وأقرب الناس إليه.` },
            { text: "يَٰٓأَيُّهَا ٱلنَّبِىُّ جَٰهِدِ ٱلْكُفَّارَ وَٱلْمُنَٰفِقِينَ وَٱغْلُظْ عَلَيْهِمْ وَمَأْوَىٰهُمْ جَهَنَّمُ وَبِئْسَ ٱلْمَصِيرُ", tafsir: `` },
            { text: "يَحْلِفُونَ بِٱللَّهِ مَا قَالُوا۟ وَلَقَدْ قَالُوا۟ كَلِمَةَ ٱلْكُفْرِ وَكَفَرُوا۟ بَعْدَ إِسْلَٰمِهِمْ وَهَمُّوا۟ بِمَا لَمْ يَنَالُوا۟ وَمَا نَقَمُوٓا۟ إِلَّآ أَنْ أَغْنَىٰهُمُ ٱللَّهُ وَرَسُولُهُۥ مِن فَضْلِهِۦ فَإِن يَتُوبُوا۟ يَكُ خَيْرًا لَّهُمْ وَإِن يَتَوَلَّوْا۟ يُعَذِّبْهُمُ ٱللَّهُ عَذَابًا أَلِيمًا فِى ٱلدُّنْيَا وَٱلْـَٔاخِرَةِ وَمَا لَهُمْ فِى ٱلْأَرْضِ مِن وَلِىٍّ وَلَا نَصِيرٍ", tafsir: `` },
            { text: "وَمِنْهُم مَّنْ عَٰهَدَ ٱللَّهَ لَئِنْ ءَاتَىٰنَا مِن فَضْلِهِۦ لَنَصَّدَّقَنَّ وَلَنَكُونَنَّ مِنَ ٱلصَّٰلِحِينَ", tafsir: `من المنافقين ( مَنْ عاهَدَ اللهَ ) أي عهد مع الله ( لَئِنْ آتانا ( 1) طه : 125. مِنْ فَضْلِهِ لَنَصَّدَّقَنَّ وَلَنَكُونَنَّ مِنَ الصَّالِحِينَ (75) فَلَمَّا آتاهُمْ مِنْ فَضْلِهِ بَخِلُوا بِهِ وَتَوَلَّوْا وَهُمْ مُعْرِضُونَ (76) فَأَعْقَبَهُمْ نِفاقاً فِي قُلُوبِهِمْ مِنْ فَضْلِهِ ) أعطانا الله من كرمه وجوده ( لَنَصَّدَّقَنَ ) نتصدق على الفقراء ( وَلَنَكُونَنَّ مِنَ الصَّالِحِينَ ) فيما أعطانا الله فننفق المال في وجهه ، ولا نكون مفسدين مسرفين. روي عن الإمام الباقر عليه‌السلام أنه قال : هو ثعلبة بن حاطب بن عمرو بن عوف كان محتاجا فعاهد الله ، فلما آتاه بخل به. وفي التفاسير : أنه قال للرسول صلى‌الله‌عليه‌وآله‌وسلم : يا رسول الله ! ادع الله أن يرزقني مالا. فقال : يا ثعلبة « قليل تؤدي شكره خير من كثير لا تطيقه » فقال : و الذي بعثك بالحق لئن رزقني الله مالا لأعطين كل ذي حق حقه. فدعا له الرسول صلى‌الله‌عليه‌وآله‌وسلم فاتخذ غنما ، فنمت كما ينمو الدود حتى ضاقت بها المدينة ، فنزل واديا وانقطع عن الجماعة والجمعة ، وبعث رسول الله المصدق ليأخذ الصدقة ، فأبى وبخل وقال : ما هذه إلا أخت الجزية. فقال صلى‌الله‌عليه‌وآله‌وسلم : « يا ويح ثعلبة يا ويح ثعلبة » (1) .` },
            { text: "فَلَمَّآ ءَاتَىٰهُم مِّن فَضْلِهِۦ بَخِلُوا۟ بِهِۦ وَتَوَلَّوا۟ وَّهُم مُّعْرِضُونَ", tafsir: `أي أعطاهم الله ( مِنْ فَضْلِهِ ) وجوده ما طلبوه ( بَخِلُوا بِهِ ) ولم يدفعوا حقه ولم يفوا بما عاهدوا عليه ( وَتَوَلَّوْا ) أي أعرضوا عن إعطاء حقه كما أمر الله ( وَهُمْ مُعْرِضُونَ ) عن دين الله وأحكامه وأوامر الرسول وأعمال الخير.` },
            { text: "فَأَعْقَبَهُمْ نِفَاقًا فِى قُلُوبِهِمْ إِلَىٰ يَوْمِ يَلْقَوْنَهُۥ بِمَآ أَخْلَفُوا۟ ٱللَّهَ مَا وَعَدُوهُ وَبِمَا كَانُوا۟ يَكْذِبُونَ", tafsir: `فأورثهم بخلهم ونقضهم لعهد الله ( نِفاقاً فِي قُلُوبِهِمْ ) ( 1) مستدرك الوسائل : ج 13 ص 256. إِلى يَوْمِ يَلْقَوْنَهُ بِما أَخْلَفُوا اللهَ ما وَعَدُوهُ وَبِما كانُوا يَكْذِبُونَ (77) أَ لَمْ يَعْلَمُوا أَنَّ اللهَ يَعْلَمُ سِرَّهُمْ وَنَجْواهُمْ وَأَنَّ اللهَ عَلاَّمُ الْغُيُوبِ (78) فإن الإنسان إذا أعرض عن أمر كبير لا بد وأن يختلق لنفسه تبريرات وأعذارا ، ليبرّر موقفه ، وذلك هو النفاق ( إِلى يَوْمِ يَلْقَوْنَهُ ) أي يلقون جزاء بخلهم ، فالضمير عائد إلى البخل ، وأريد به جزاءه ، أو المراد نفس البخل ، بناء على تجسيم الأعمال ، أو الضمير عائد إلى الله سبحانه المعلوم من السياق ، و « ملاقاة الله » إنما هي في القيامة بملاقاة حسابه ، فإنه سبحانه منزّه عن المكان والرؤية. وذلك بسبب ما ( أَخْلَفُوا اللهَ ما وَعَدُوهُ ) بسبب خلفهم للعهد الذي عاهدوا ، من أن الله إذا أعطاهم من فضله تصدّقوا وكانوا شاكرين ( وَبِما كانُوا يَكْذِبُونَ ) أي وبسبب كذبهم على الرسول صلى‌الله‌عليه‌وآله‌وسلم أو المراد بالكذب عليه : أن الصدقة أخت الجزية ـ كما تقدم ـ.` },
            { text: "أَلَمْ يَعْلَمُوٓا۟ أَنَّ ٱللَّهَ يَعْلَمُ سِرَّهُمْ وَنَجْوَىٰهُمْ وَأَنَّ ٱللَّهَ عَلَّٰمُ ٱلْغُيُوبِ", tafsir: `استفهام إنكاري ، أي أليس يعرف هؤلاء المنافقون ( أَنَّ اللهَ يَعْلَمُ سِرَّهُمْ ) المخفي في نفوسهم ( وَنَجْواهُمْ ) التي يتناجون بها مع أمثالهم من المنافقين ؟ فإن المنافق لا بد وأن يتناجى مع أمثاله لجعل حلول ومبرّرات لموقفهم النفاقي ، كما تدور الأسرار في نفوسهم فيقلبون أوجه الرأي للخلاص من مأزقهم ( وَأَنَّ اللهَ عَلَّامُ الْغُيُوبِ ) يعلم ما غاب عن الحواس ، من الأمور المختفية في النفوس ، والنجوى ، وغيرهما ، فإذا علموا ذلك ، فلما ذا لا يخشون منه سبحانه ولا يفعلون حسب مرضاته ؟ الَّذِينَ يَلْمِزُونَ الْمُطَّوِّعِينَ مِنَ الْمُؤْمِنِينَ فِي الصَّدَقاتِ وَالَّذِينَ لا يَجِدُونَ إِلاَّ جُهْدَهُمْ فَيَسْخَرُونَ مِنْهُمْ سَخِرَ اللهُ مِنْهُمْ وَلَهُمْ عَذابٌ أَلِيمٌ (79) [79] وكان من المنافقين من يرصدون للمسلمين ليعيبونهم ، فقد جاء رجل من المؤمنين بصاع من تمر للصدقة ، فقال المنافقون : إن الله غني عن صاعه ، وإنما جاء بذلك حتى يذكر في المتصدقين. وجاء رجل آخر بصرّة من دراهم ، فقالوا : إنه جاء بذلك للرياء ، فعابوا المكثر بالرياء ، والمقل بالإقلال ، فنزل قوله تعالى : المنافقون ( الَّذِينَ يَلْمِزُونَ ) « اللّمز » هو الطعن ، أي يطعنون ( الْمُطَّوِّعِينَ ) أي معطي الصدقة تطوعا من « اطّوع » ، أصله « تطوع » ، أدغمت التاء في الطاء ، وجيء بهمزة الوصل ، لتعذر الابتداء بالساكن ( مِنَ الْمُؤْمِنِينَ ) ولعلّ ذكر هذا للدلالة على أن إيمان المتطوع كان اللازم أن يحجز القائلين من الطعن بهم ، لكنهم منافقون لا يبالون بالإيمان والمؤمنين ( فِي الصَّدَقاتِ ) كما طعنوا فيمن أعطى الدراهم ( وَ ) يلمزون ( الَّذِينَ لا يَجِدُونَ إِلَّا جُهْدَهُمْ ) أي إلّا طاقتهم في الإنفاق والتصدق ، كما عابوا من أعطى الصاع ( فَيَسْخَرُونَ مِنْهُمْ ) ويستهزئون بهم ( سَخِرَ اللهُ مِنْهُمْ ) أي يجازيهم جزاء سخريتهم. وقد تقدم تفصيل الكلام في سورة البقرة ، في قوله سبحانه : ( اللهُ يَسْتَهْزِئُ بِهِمْ ) (1) ، ( وَلَهُمْ عَذابٌ أَلِيمٌ ) مؤلم موجع.` },
            { text: "ٱلَّذِينَ يَلْمِزُونَ ٱلْمُطَّوِّعِينَ مِنَ ٱلْمُؤْمِنِينَ فِى ٱلصَّدَقَٰتِ وَٱلَّذِينَ لَا يَجِدُونَ إِلَّا جُهْدَهُمْ فَيَسْخَرُونَ مِنْهُمْ سَخِرَ ٱللَّهُ مِنْهُمْ وَلَهُمْ عَذَابٌ أَلِيمٌ", tafsir: `` },
            { text: "ٱسْتَغْفِرْ لَهُمْ أَوْ لَا تَسْتَغْفِرْ لَهُمْ إِن تَسْتَغْفِرْ لَهُمْ سَبْعِينَ مَرَّةً فَلَن يَغْفِرَ ٱللَّهُ لَهُمْ ذَٰلِكَ بِأَنَّهُمْ كَفَرُوا۟ بِٱللَّهِ وَرَسُولِهِۦ وَٱللَّهُ لَا يَهْدِى ٱلْقَوْمَ ٱلْفَٰسِقِينَ", tafsir: `في حق المنافقين قالوا : يا ( 1) البقرة : 16. اسْتَغْفِرْ لَهُمْ أَوْ لا تَسْتَغْفِرْ لَهُمْ إِنْ تَسْتَغْفِرْ لَهُمْ سَبْعِينَ مَرَّةً فَلَنْ يَغْفِرَ اللهُ لَهُمْ رسول الله استغفر لنا فوعدهم النبي صلى‌الله‌عليه‌وآله‌وسلم بالاستغفار ، فنزلت الآية : ( اسْتَغْفِرْ لَهُمْ ) يا رسول الله ( أَوْ لا تَسْتَغْفِرْ لَهُمْ ) الصيغة الأولى للأمر ، والمراد بها المبالغة في الإياس ، أي سواء استغفرت لهم أم لم تستغفر فإنهم لا يستحقون الغفران ، ولذا لا يغفر الله لهم ( إِنْ تَسْتَغْفِرْ لَهُمْ سَبْعِينَ مَرَّةً ) صيغة مبالغة يراد بها الكثرة ، كما يقال : « لو قلت لي ألف مرة ما قبلت » لا يريد الألف ، بل المراد أنه لا يقبل وإن قال فوق الألف ( فَلَنْ يَغْفِرَ اللهُ لَهُمْ ) لأنهم جبلوا على النفاق والجبل عليه لا يفيده الاستغفار ، وهذا ليس إهانة للرسول ـ كما زعم ـ بل أفرغ التوبيخ لأولئك في هذا القالب ، كما تقدم في قوله : ( وَأَخَذَ بِرَأْسِ أَخِيهِ يَجُرُّهُ إِلَيْهِ ) (1) . وإن قيل : كيف جاز للرسول أن يعدهم بما لم يفعل ؟ قلنا : إن ثبتت الرواية ، لم يكن به بأس لأن الاستغفار إنما كان لأجل أن يغفر الله ، فإذا أخبر سبحانه بأنه لا يغفر لم يبق للاستغفار مجالا ، كما لو وعد إنسان بإطعام زيد ثم مات زيد. ثم إنه كان مراد الرسول صلى‌الله‌عليه‌وآله‌وسلم الاستغفار بالشرط فلم يكن إخبارا مطلقا حتى يقال أنه يلزم جهله بالمستقبل ، وأنه تكلم من عند نفسه ، وهذا ينافي قوله تعالى : ( ما يَنْطِقُ عَنِ الْهَوى * إِنْ هُوَ إِلَّا وَحْيٌ يُوحى ) (2) . ( 1) الأعراف : 151. ( 2) النجم : 4 و 5. ذلِكَ بِأَنَّهُمْ كَفَرُوا بِاللهِ وَرَسُولِهِ وَاللهُ لا يَهْدِي الْقَوْمَ الْفاسِقِينَ (80) فَرِحَ الْمُخَلَّفُونَ بِمَقْعَدِهِمْ خِلافَ رَسُولِ اللهِ وَكَرِهُوا أَنْ يُجاهِدُوا بِأَمْوالِهِمْ وَأَنْفُسِهِمْ فِي سَبِيلِ اللهِ وَقالُوا لا تَنْفِرُوا فِي الْحَرِّ قُلْ نارُ جَهَنَّمَ أَشَدُّ حَرًّا ( ذلِكَ ) الذي تقدم من عدم قبول توبتهم وعدم فائدة الاستغفار بالنسبة إليهم بسبب أنهم أي المنافقين ( كَفَرُوا بِاللهِ وَرَسُولِهِ ) كفرا باطنا ، وإن أظهروا الإسلام ( وَاللهُ لا يَهْدِي الْقَوْمَ الْفاسِقِينَ ) فإنه سبحانه لا يلطف بهم اللطف الخفي بعد أن خرجوا عن طاعته وخالفوا أوامره عن علم وعمل.` },
            { text: "فَرِحَ ٱلْمُخَلَّفُونَ بِمَقْعَدِهِمْ خِلَٰفَ رَسُولِ ٱللَّهِ وَكَرِهُوٓا۟ أَن يُجَٰهِدُوا۟ بِأَمْوَٰلِهِمْ وَأَنفُسِهِمْ فِى سَبِيلِ ٱللَّهِ وَقَالُوا۟ لَا تَنفِرُوا۟ فِى ٱلْحَرِّ قُلْ نَارُ جَهَنَّمَ أَشَدُّ حَرًّا لَّوْ كَانُوا۟ يَفْقَهُونَ", tafsir: `« المخلّف » بصيغة المفعول من باب « التفعيل » هو المتروك خلف من مضى ، وسمّي مخلفا لأنه تخلّف بنفسه ، أو خلّفه شخص آخر وأبقاه ، كالمؤخّر ، ( بِمَقْعَدِهِمْ ) هو « مصدر ميمي » بمعنى « القعود » أي أن من تخلفوا عن الجهاد في تبوك ، فرحوا بقعودهم ( خِلافَ رَسُولِ اللهِ ) أي بعده ، أو بمعنى : بقاؤهم خلافا للرسول صلى‌الله‌عليه‌وآله‌وسلم ، فقد فرحوا بأنهم نجوا من تلك السفرة المتعبة الخطرة ( وَكَرِهُوا أَنْ يُجاهِدُوا بِأَمْوالِهِمْ وَأَنْفُسِهِمْ ) ترجيحا للراحة على التعب ( فِي سَبِيلِ اللهِ ) ولإعلاء كلمته ( وَقالُوا ) قال أولئك المخلّفون للمسلمين ولنظرائهم من المنافقين : ( لا تَنْفِرُوا ) أي لا تذهبوا للجهاد ( فِي الْحَرِّ ) فإن وقت خروجهم كان مصادفا للحر الشديد ( قُلْ ) يا رسول الله لهؤلاء : ( نارُ جَهَنَّمَ ) التي تجب للمتخلّف ( أَشَدُّ حَرًّا ) من هذه الحرارة التي يلاقيها المجاهدون ، فهي أولى بالاحتراز من هذه لَوْ كانُوا يَفْقَهُونَ (81) فَلْيَضْحَكُوا قَلِيلاً وَلْيَبْكُوا كَثِيراً جَزاءً بِما كانُوا يَكْسِبُونَ (82) فَإِنْ رَجَعَكَ اللهُ إِلى طائِفَةٍ مِنْهُمْ فَاسْتَأْذَنُوكَ لِلْخُرُوجِ فَقُلْ لَنْ تَخْرُجُوا مَعِيَ أَبَداً وَلَنْ تُقاتِلُوا مَعِيَ عَدُوًّا إِنَّكُمْ رَضِيتُمْ بِالْقُعُودِ أَوَّلَ مَرَّةٍ فَاقْعُدُوا مَعَ الْخالِفِينَ (83) ( لَوْ كانُوا يَفْقَهُونَ ) أي يفهمون ، والمعنى : أنهم لو فقهوا لعلموا أن نار جهنم أولى بالاحتراز والتجنّب. [82] إن الفرح الذي فرحه المخلفون بسبب بقائهم يوجب لهم العذاب الدائم ، فاللازم أن يضحكوا قليلا لأنه لم يبق لهم مجال للضحك ، فقد استحقوا بذلك العقاب ، والمهدّد لا يضحك ( فَلْيَضْحَكُوا قَلِيلاً ) إنه ليس أمرا بالضحك وإنما بيان لوجوب التقليل من ضحكهم ( وَلْيَبْكُوا كَثِيراً ) حيث عملوا ما يستحقون به البكاء حيث اشتروا النار بفرارهم من الزحف ( جَزاءً بِما كانُوا يَكْسِبُونَ ) من النفاق والتخلّف عن الرسول صلى‌الله‌عليه‌وآله‌وسلم .` },
            { text: "فَلْيَضْحَكُوا۟ قَلِيلًا وَلْيَبْكُوا۟ كَثِيرًا جَزَآءًۢ بِمَا كَانُوا۟ يَكْسِبُونَ", tafsir: `` },
            { text: "فَإِن رَّجَعَكَ ٱللَّهُ إِلَىٰ طَآئِفَةٍ مِّنْهُمْ فَٱسْتَـْٔذَنُوكَ لِلْخُرُوجِ فَقُل لَّن تَخْرُجُوا۟ مَعِىَ أَبَدًا وَلَن تُقَٰتِلُوا۟ مَعِىَ عَدُوًّا إِنَّكُمْ رَضِيتُم بِٱلْقُعُودِ أَوَّلَ مَرَّةٍ فَٱقْعُدُوا۟ مَعَ ٱلْخَٰلِفِينَ", tafsir: `يا رسول الله من هذه الغزوة ـ غزوة تبوك ـ ( إِلى طائِفَةٍ مِنْهُمْ ) لا خصوصية للرجوع إلى الطائفة ، وإنما المقصود ترتيب الأثر على تلك الطائفة من المنافقين الذين تخلفوا عن تبوك ( فَاسْتَأْذَنُوكَ ) أي طلبوا منك الإذن ( لِلْخُرُوجِ ) معك إلى غزوة أخرى ( فَقُلْ ) لهم : ( لَنْ تَخْرُجُوا مَعِيَ أَبَداً ) إلى الغزوة ( وَلَنْ تُقاتِلُوا مَعِيَ عَدُوًّا ) فإنا قطعنا عنكم ولا صلة بيننا وبينكم ( إِنَّكُمْ رَضِيتُمْ بِالْقُعُودِ ) عن الجهاد ( أَوَّلَ مَرَّةٍ ) في غزوة تبوك ( فَاقْعُدُوا مَعَ الْخالِفِينَ ) الذين وَلا تُصَلِّ عَلى أَحَدٍ مِنْهُمْ ماتَ أَبَداً وَلا تَقُمْ عَلى قَبْرِهِ إِنَّهُمْ كَفَرُوا بِاللهِ وَرَسُولِهِ وَماتُوا وَهُمْ فاسِقُونَ (84) يخالفوننا ، وكونوا معهم دائما ، إن الذي يترك الإنسان في ساعة العسرة لا يصلح أن يكون معه ، فطبعه طبع انهزامي مخلد إلى الدعة ، ولو خرج لم يزد إلا خبالا وخذلانا ، فلذا كان اللازم أن يجتنب عنه إطلاقا ، بالإضافة إلى أن الإسلام في غنى عنه ، وهو لا يستحق شرف الجهاد فليبق في بيته ويكن مع الخالفين. [84] ثم نهى سبحانه نبيه عن الصلاة على مثل هؤلاء المنافقين ليحذر غيرهم من النفاق ، ولأنهم لا يستحقون الرحمة والغفران ( وَلا تُصَلِّ عَلى أَحَدٍ مِنْهُمْ ماتَ ) أي إذا مات أحد هؤلاء المنافقين فلا تصلّ على ميتهم ( أَبَداً ) أي إلى الأبد ، فإنه تجوز الصلاة على من لم يصلّ عليه إلى آخر العمر ـ على قول ـ لكن المنافق لا يستحق ذلك ( وَلا تَقُمْ عَلى قَبْرِهِ ) أي لا تقف على قبره للدعاء كما هو عادة الناس أن يقفون على قبر المسلم يدعون له ويستغفرون من أجله. وذلك بسبب ( إِنَّهُمْ كَفَرُوا بِاللهِ وَرَسُولِهِ ) وإسلامهم الظاهري إنما حقن دماءهم وحفظ أموالهم وأعراضهم ، لكنه لم يدخلهم في زمرة المؤمنين الذين لهم الكرامة ( وَماتُوا وَهُمْ فاسِقُونَ ) خارجون عن طاعة الله سبحانه. ثم إن المراد ب « الصلاة » طلب الرحمة له ، كما أن المراد ب « الوقوف على قبره » ذلك ، فلا ينافي ذلك ما فعله النبي صلى‌الله‌عليه‌وآله‌وسلم بعبد الله ابن أبيّ المنافق الذي مات فصلّى الرسول عليه ، ولعنه عقيب الرابعة. ثم إنه قد اختلفت الأقوال حول هذا المنافق مما لا يهمنا التعرّض له. وَلا تُعْجِبْكَ أَمْوالُهُمْ وَأَوْلادُهُمْ إِنَّما يُرِيدُ اللهُ أَنْ يُعَذِّبَهُمْ بِها فِي الدُّنْيا وَتَزْهَقَ أَنْفُسُهُمْ وَهُمْ كافِرُونَ (85) وَإِذا أُنْزِلَتْ سُورَةٌ أَنْ آمِنُوا بِاللهِ وَجاهِدُوا مَعَ رَسُولِهِ اسْتَأْذَنَكَ أُولُوا الطَّوْلِ مِنْهُمْ وَقالُوا ذَرْنا` },
            { text: "وَلَا تُصَلِّ عَلَىٰٓ أَحَدٍ مِّنْهُم مَّاتَ أَبَدًا وَلَا تَقُمْ عَلَىٰ قَبْرِهِۦٓ إِنَّهُمْ كَفَرُوا۟ بِٱللَّهِ وَرَسُولِهِۦ وَمَاتُوا۟ وَهُمْ فَٰسِقُونَ", tafsir: `` },
            { text: "وَلَا تُعْجِبْكَ أَمْوَٰلُهُمْ وَأَوْلَٰدُهُمْ إِنَّمَا يُرِيدُ ٱللَّهُ أَن يُعَذِّبَهُم بِهَا فِى ٱلدُّنْيَا وَتَزْهَقَ أَنفُسُهُمْ وَهُمْ كَٰفِرُونَ", tafsir: `يا رسول الله ، أي لا تنظر نظرة إعجاب ـ المستلزمة للتكريم ـ ( أَمْوالُهُمْ ) أي أموال المنافقين ( وَأَوْلادُهُمْ ) الكثيرة ، كيف قد منحوا ذلك ، وأنها تدل على تكريم الله لهم ، بل بالعكس ( إِنَّما يُرِيدُ اللهُ أَنْ يُعَذِّبَهُمْ بِها ) بهذه الأموال والأولاد ( فِي الدُّنْيا وَتَزْهَقَ أَنْفُسُهُمْ ) « زهق النفس » عبارة عن هلاكها ( وَهُمْ كافِرُونَ ) فهم بين عذاب الدنيا للمال والأولاد من التبعة والهموم ، وبين عذاب الآخرة حيث أنهم يموتون مع الكفر. وقد مر تفسير الآية فراجع. ولعل المقصود من تكرار الآية : النهي عن هذا النوع من التكريم اللاشعوري للكفار والمنافقين ، فإن نظر الإعجاب هو نظر التكريم ، فيختلف المقصود هنا من المقصود هناك.` },
            { text: "وَإِذَآ أُنزِلَتْ سُورَةٌ أَنْ ءَامِنُوا۟ بِٱللَّهِ وَجَٰهِدُوا۟ مَعَ رَسُولِهِ ٱسْتَـْٔذَنَكَ أُو۟لُوا۟ ٱلطَّوْلِ مِنْهُمْ وَقَالُوا۟ ذَرْنَا نَكُن مَّعَ ٱلْقَٰعِدِينَ", tafsir: `من القرآن الكريم تتضمن ( أَنْ آمِنُوا بِاللهِ ) إما بالنسبة إلى غير المؤمنين ، وإما بالنسبة إلى المنافقين ، أي آمنوا إيمانا صحيحا ، وإما بالنسبة إلى المؤمنين بقصد إبقائهم على الإيمان واستقامتهم فيه نحو ( اهْدِنَا الصِّراطَ الْمُسْتَقِيمَ )( وَجاهِدُوا مَعَ رَسُولِهِ ) لإعلاء كلمة الإسلام ، فآمنوا ، وادعوا غيركم إلى الإيمان والجهاد ( اسْتَأْذَنَكَ ) أي طلب منك الإذن في عدم الجهاد ( أُولُوا الطَّوْلِ ) أي أصحاب المال والقدرة والغنى ( مِنْهُمْ ) من المنافقين ( وَقالُوا ذَرْنا ) نَكُنْ مَعَ الْقاعِدِينَ (86) رَضُوا بِأَنْ يَكُونُوا مَعَ الْخَوالِفِ وَطُبِعَ عَلى قُلُوبِهِمْ فَهُمْ لا يَفْقَهُونَ (87) لكِنِ الرَّسُولُ وَالَّذِينَ آمَنُوا مَعَهُ جاهَدُوا بِأَمْوالِهِمْ وَأَنْفُسِهِمْ وَأُولئِكَ لَهُمُ الْخَيْراتُ وَأُولئِكَ هُمُ الْمُفْلِحُونَ (88) أَعَدَّ اللهُ لَهُمْ جَنَّاتٍ تَجْرِي مِنْ تَحْتِهَا الْأَنْهارُ أي دعنا ( نَكُنْ مَعَ الْقاعِدِينَ ) الذين ليس عليهم جهاد ، من النساء والصبيان والعاجزين.` },
            { text: "رَضُوا۟ بِأَن يَكُونُوا۟ مَعَ ٱلْخَوَالِفِ وَطُبِعَ عَلَىٰ قُلُوبِهِمْ فَهُمْ لَا يَفْقَهُونَ", tafsir: `أي رضي هؤلاء المنافقين ( بِأَنْ يَكُونُوا مَعَ الْخَوالِفِ ) جمع « خالفة » ، وهي المرأة سميت به لأنها تتخلف عن الجهاد ، أو هو أعم من « الخالف » فإن « فارس » يجمع على « فوارس » ، والمراد : كل من تخلف عن الجهاد من النساء والصبيان والعاجزين ( وَطُبِعَ عَلى قُلُوبِهِمْ ) فإنهم بسبب نفاقهم طبع عدم الإيمان على قلوبهم ( فَهُمْ لا يَفْقَهُونَ ) قبح عملهم وتركهم للجهاد ، كشأن كل إنسان انغمر في الشهوات والمفاسد ، فإنه لا يعرف قبح عمله بل يراه حسنا.` },
            { text: "لَٰكِنِ ٱلرَّسُولُ وَٱلَّذِينَ ءَامَنُوا۟ مَعَهُۥ جَٰهَدُوا۟ بِأَمْوَٰلِهِمْ وَأَنفُسِهِمْ وَأُو۟لَٰٓئِكَ لَهُمُ ٱلْخَيْرَٰتُ وَأُو۟لَٰٓئِكَ هُمُ ٱلْمُفْلِحُونَ", tafsir: `إيمانا صادقا ( جاهَدُوا بِأَمْوالِهِمْ ) بإنفاقها في سبيل الله. وسمي جهادا لأن بذل المال يحتاج إلى جهد النفس وتعبها ( وَأَنْفُسِهِمْ ) يقاتلون الكفار ويجالدون المردة الفجار ( وَأُولئِكَ لَهُمُ الْخَيْراتُ ) المنافع والأشياء الخيرة من خيرات الدنيا والآخرة ، فإنهم يحرزون حسن السمعة والمال في الدنيا ، والنعيم في الجنة ( وَأُولئِكَ هُمُ الْمُفْلِحُونَ ) الفائزون الناجحون.` },
            { text: "أَعَدَّ ٱللَّهُ لَهُمْ جَنَّٰتٍ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ خَٰلِدِينَ فِيهَا ذَٰلِكَ ٱلْفَوْزُ ٱلْعَظِيمُ", tafsir: `أي من تحت أشجارها خالِدِينَ فِيها ذلِكَ الْفَوْزُ الْعَظِيمُ (89) وَجاءَ الْمُعَذِّرُونَ مِنَ الْأَعْرابِ لِيُؤْذَنَ لَهُمْ وَقَعَدَ الَّذِينَ كَذَبُوا اللهَ وَرَسُولَهُ سَيُصِيبُ الَّذِينَ كَفَرُوا مِنْهُمْ عَذابٌ أَلِيمٌ (90) وقصورها ، فهم مشرفون على الأنهر الجارية ، وفي ذلك لذة ومتعة ( خالِدِينَ فِيها ) أبدا لا خروج لهم منها ، ولا زوال لنعيمها عنهم ( ذلِكَ ) الإحراز للخيرات وللجنات ( الْفَوْزُ الْعَظِيمُ ) الذي لا شيء أعظم منه. [90] أمام الحركات ينقسم الناس إلى ثلاثة أصناف : قسم يأتي وينضم إلى الحركة ، وقسم لا يأتي ولا يعتذر ، وقسم يأتي ويعتذر. وهكذا حدث في غزوة تبوك ، فالمؤمنون الصادقون انضموا إلى الرسول صلى‌الله‌عليه‌وآله‌وسلم ، والمنافقون بعضهم جاء ليعتذر بلا مبرّر ، وبعضهم لم يجئ إطلاقا حتى للاعتذار ( وَجاءَ الْمُعَذِّرُونَ ) من « اعتذر » باب « التفعيل » بمعنى : أبدى العذر بدون أن يكون ذا عذر في الحقيقة ( مِنَ الْأَعْرابِ ) إما المراد بهم : أهل البدو ، وإما المراد : أهل الحضر ، لكنهم شبّهوا بالأعراب في عدم استحقاقهم التكريم ، كما قال سبحانه : ( الْأَعْرابُ أَشَدُّ كُفْراً وَنِفاقاً ) (1) . جاء هؤلاء ( لِيُؤْذَنَ لَهُمْ ) أي يأذن لهم الرسول صلى‌الله‌عليه‌وآله‌وسلم في التخلّف عن الجهاد ( وَقَعَدَ ) المنافقون ( الَّذِينَ كَذَبُوا اللهَ وَرَسُولَهُ ) في باطنهم ، وإن أظهروا التصديق في الظاهر ـ كما هو شأن المنافق ـ فإن هؤلاء لم يأتوا إلى النبي صلى‌الله‌عليه‌وآله‌وسلم للاعتذار بل قعدوا في مكانهم وكأن أمرا لم يحدث ( سَيُصِيبُ الَّذِينَ كَفَرُوا مِنْهُمْ ) من هؤلاء ( عَذابٌ أَلِيمٌ ) مؤلم موجع ، وإنما خصص جماعة منهم لأنهم لم يكفروا كلهم ، فالمعذورون من ( 1) التوبة : 97. لَيْسَ عَلَى الضُّعَفاءِ وَلا عَلَى الْمَرْضى وَلا عَلَى الَّذِينَ لا يَجِدُونَ ما يُنْفِقُونَ حَرَجٌ إِذا نَصَحُوا لِلَّهِ وَرَسُولِهِ ما عَلَى الْمُحْسِنِينَ مِنْ سَبِيلٍ وَاللهُ غَفُورٌ رَحِيمٌ (91) وَلا عَلَى الَّذِينَ إِذا ما أَتَوْكَ الأعراب غالبا لا ينطوون على الكفر ، وإنما يتخلّفون تكاسلا. [91] ثم بيّن سبحانه أهل الأعذار الذين يسقط عنهم الجهاد بقوله : ( لَيْسَ عَلَى الضُّعَفاءِ ) جمع « ضعيف » كالشيخ الكبير ، والضعيف البنية ، والعاجز لعمى أو زمانه أو ما أشبه ـ مما لا يسمّى مرضا ـ ( وَلا عَلَى الْمَرْضى ) جمع « مريض » وهم أصحاب الأسقام والعلل المانعة عن الجهاد ( وَلا عَلَى الَّذِينَ لا يَجِدُونَ ما يُنْفِقُونَ ) ليست معهم نفقة الخروج وأسباب السفر ( حَرَجٌ ) ضيق ، فلا جناح عليهم في التخلّف عن الجهاد ( إِذا نَصَحُوا لِلَّهِ وَرَسُولِهِ ) بأن أخلصوا العمل من الفسق ، وكانوا ناصحين في قرارة نفوسهم. وليس المعنى : وجود الحرج لغير الناصح ـ من جهة عدم الجهاد ـ بل المراد : أن عدم الحرج المطلق إنما يترتب على العاجز الناصح ، أما العاجز المنافق فعليه حرج من جهة نفاقه. ( ما عَلَى الْمُحْسِنِينَ مِنْ سَبِيلٍ ) لا سبيل على تعذيبهم ولا جناح عليهم ، فإنهم محسنون في أعمالهم. ولا يخفى أن الآية لا تدل على أن مريد الإحسان لا جناح عليه وإن أساء ، فإن الظاهر منها أن المحسن حقيقة لا جناح عليه ( وَاللهُ غَفُورٌ ) لذنوبهم ( رَحِيمٌ ) بهم ، فلا يحمّلهم فوق طاقتهم. لِتَحْمِلَهُمْ قُلْتَ لا أَجِدُ ما أَحْمِلُكُمْ عَلَيْهِ تَوَلَّوْا وَأَعْيُنُهُمْ تَفِيضُ مِنَ الدَّمْعِ حَزَناً أَلاَّ يَجِدُوا ما يُنْفِقُونَ (92) إِنَّمَا السَّبِيلُ عَلَى الَّذِينَ يَسْتَأْذِنُونَكَ وَهُمْ أَغْنِياءُ رَضُوا بِأَنْ يَكُونُوا مَعَ الْخَوالِفِ وَطَبَعَ اللهُ عَلى قُلُوبِهِمْ فَهُمْ لا يَعْلَمُونَ (93)` },
            { text: "وَجَآءَ ٱلْمُعَذِّرُونَ مِنَ ٱلْأَعْرَابِ لِيُؤْذَنَ لَهُمْ وَقَعَدَ ٱلَّذِينَ كَذَبُوا۟ ٱللَّهَ وَرَسُولَهُۥ سَيُصِيبُ ٱلَّذِينَ كَفَرُوا۟ مِنْهُمْ عَذَابٌ أَلِيمٌ", tafsir: `` },
            { text: "لَّيْسَ عَلَى ٱلضُّعَفَآءِ وَلَا عَلَى ٱلْمَرْضَىٰ وَلَا عَلَى ٱلَّذِينَ لَا يَجِدُونَ مَا يُنفِقُونَ حَرَجٌ إِذَا نَصَحُوا۟ لِلَّهِ وَرَسُولِهِۦ مَا عَلَى ٱلْمُحْسِنِينَ مِن سَبِيلٍ وَٱللَّهُ غَفُورٌ رَّحِيمٌ", tafsir: `` },
            { text: "وَلَا عَلَى ٱلَّذِينَ إِذَا مَآ أَتَوْكَ لِتَحْمِلَهُمْ قُلْتَ لَآ أَجِدُ مَآ أَحْمِلُكُمْ عَلَيْهِ تَوَلَّوا۟ وَّأَعْيُنُهُمْ تَفِيضُ مِنَ ٱلدَّمْعِ حَزَنًا أَلَّا يَجِدُوا۟ مَا يُنفِقُونَ", tafsir: `سبيل وجناح ( عَلَى الَّذِينَ إِذا ما أَتَوْكَ ) « ما » زائدة تأتي لتزيين الكلام ، أي إذا جاءوك يا رسول الله ( لِتَحْمِلَهُمْ ) أي يسألونك مركبا يركبون عليه ليجاهدوا ( قُلْتَ ) يا رسول الله : ( لا أَجِدُ ما أَحْمِلُكُمْ عَلَيْهِ ) فليس عندي مركب تركبونه ( تَوَلَّوْا ) أي رجعوا ( وَأَعْيُنُهُمْ تَفِيضُ مِنَ الدَّمْعِ حَزَناً ) أعينهم تسيل بالدموع من حزنهم ( أَلَّا يَجِدُوا ما يُنْفِقُونَ ) ينفقونه لأجل تهيئة وسائل الجهاد. ورد أن سبعة من الأنصار جاءوا إلى الرسول يطلبون منه المركب ليرافقوه في غزوة ، فاعتذر منهم الرسول صلى‌الله‌عليه‌وآله‌وسلم بأنه لا يجد ما يحملهم ، فرجعوا باكين (1) . وفيهم نزلت الآية.` },
            { text: "إِنَّمَا ٱلسَّبِيلُ عَلَى ٱلَّذِينَ يَسْتَـْٔذِنُونَكَ وَهُمْ أَغْنِيَآءُ رَضُوا۟ بِأَن يَكُونُوا۟ مَعَ ٱلْخَوَالِفِ وَطَبَعَ ٱللَّهُ عَلَىٰ قُلُوبِهِمْ فَهُمْ لَا يَعْلَمُونَ", tafsir: `أي السبيل لعقابهم ولومهم ( عَلَى الَّذِينَ يَسْتَأْذِنُونَكَ ) يطلبون إذنك للتخلّف عن الجهاد والبقاء في المدينة ( وَهُمْ أَغْنِياءُ ) قادرون على الجهاد ونفقاته ( رَضُوا ) أي رضي هؤلاء المستأذنون ( بِأَنْ يَكُونُوا مَعَ الْخَوالِفِ ) من النساء والصبيان والعاجزين ( وَطَبَعَ اللهُ عَلى قُلُوبِهِمْ ) بسبب نفاقهم ( فَهُمْ لا يَعْلَمُونَ ) بأن تخلّفهم عن الجهاد يسبب ( 1) راجع مجمع البيان : ج 5 ص 104. تقريب القران الى الأذهان من آية 94 من سورة التوبة إلى آية 6 من سورة هود بسم الله الرّحمن الرّحيم الحمد لله رب العالمين والصلاة والسلام على أشرف الأنبياء والمرسلين محمد المصطفى وعترته الطاهرين [94] لنذكر طرفا يسيرا من هذه الغزوة « تبوك » من كراس « رسول الإسلام في المدينة » من السلسلة التي وضعناها في قادة الإسلام (1) : لما خرج الرسول صلى‌الله‌عليه‌وآله‌وسلم من المدينة استعرض الجيش فكانوا ثلاثين ألفا ، فغمر الجيش الفرح لكثرة عددهم ، لكنهم عانوا في هذه السفرة أشد أنواع الجوع والعطش ، فالمضرة كبيرة ، والحر شديد ، والقلوب متعلقة بالمدينة ، إذ نضجت الثمار ، وحان قطفها ، والمركوب قليل ، حتى أن العشرة منهم كانوا يتناوبون في ركوب جمل واحد ، والطعام قليل جدا ، ففي بعض الأحيان كان نفران منهم يتقاسمان تمرة واحدة شق لهذا وشق لذاك ، وأصابهم أشد العطش فكانوا ينحرون إبلهم العزيزة ، لينقبوا كروشها ، ويشربوا ماءها ، أو يعتصروا فرثها ليشربوا عصيره ثم يجعل ما بقي على كبده ، حتى أن بعضهم رأى الموت بعينيه ، فطلبوا من النبي الاستسقاء ، فدعا صلى‌الله‌عليه‌وآله‌وسلم رافعا يديه إلى السماء. قال الراوي : فلم يرجعوا حتى هطلت السماء بمطر غزير. هذا بالإضافة إلى الإشاعات التي ملكت القلوب ـ وإن سارت بأجسامها مع الرسول صلى‌الله‌عليه‌وآله‌وسلم ـ أنه لا بد وأن تقضي جيوش الروم الهائلة المنظمة على الجيش الإسلامي ، فلا يبقى منه أحد .. وسار الرسول حتى وصل « تبوك » وقد كان « هرقل » وزع رواتب سنة كاملة على جيشه ، كما وزع أموالا طائلة على القبائل التي استخدمها لقتال المسلمين ، وهم لخم وجذم وعاملة وغسان وغيرها .. . وقد أتت الروم أنباء هائلة عن جيش المسلمين ، مما رأوا أن ( 1) للمؤلف. من الصالح عدم دخولهم في قتال لا يعرف مصيره ، وقد كان الروم شاهدوا في حرب « مؤتة » قتال المسلمين ، فإذا لم يتمكن جيشهم ، وعدده « مائتا ألف » من جيش « مؤتة » الذي كان بقيادة جعفر عليه‌السلام وعدده « ثلاثة آلاف » فكيف يقاوم جيشهم جيش الإسلام كله وهم لا يعلمون عدده من الكثرة بقيادة الرسول صلى‌الله‌عليه‌وآله‌وسلم . ولذا قرروا انسحاب الجيش ، فانسحبوا قبل الاصطدام بجيش المسلمين. وصل الرسول صلى‌الله‌عليه‌وآله‌وسلم إلى « تبوك » فلم يلق جيشا ، فاستشار أصحابه في غزو بني الأصفر ـ أي الروم ـ والرجوع إلى المدينة ؟ فأشاروا على الرسول بالرجوع ، فبقي الرسول صلى‌الله‌عليه‌وآله‌وسلم هناك عشرين يوما ، وعقد الاتفاقيات مع الزعماء والقبائل ، فأرسل إلى أصحاب أيلة : « يوحنا بن روبة » بالإذعان للمسلمين أو الغزو ؟ لكن « يوحنا » كان رجلا حكيما ، فاختار الإذعان ، وتم الاتفاق بإعطائه الجزية للدولة الإسلامية ، وعدم التعرض للدعوة الإسلامية .. . وعقد الصلح بين المسلمين وبين أهل « جرباء » وهي قرية في منطقة « عمان » بالبلقاء ، من أراضي الشام ، على مثل المصالحة مع صاحب أيلة .. . وعقد الصلح بين المسلمين وبين أهل « أذرح » قرية أخرى قريبة من الجرباء بمثل مصالحة الجرباء .. وتم الصلح بين المسلمين وبين « الأكيدر » ملك « دومة الجندل » على بذل الجزية وعدم التعرض للمسلمين. وانتظر الرسول جيوش الروم لكنها لم تزحف ، فأخذ الجيش الإسلامي طريقه إلى المدينة بعد ما أمن الحدود الشمالية ، وصارت له منعة وقوة ، وفتحت مجالات الإسلام في القلوب والمدن والقرى ، وإذا بالمدينة تشاهد غبار جيش الإسلام المنتصر على الإمبراطورية يَعْتَذِرُونَ إِلَيْكُمْ إِذا رَجَعْتُمْ إِلَيْهِمْ قُلْ لا تَعْتَذِرُوا لَنْ نُؤْمِنَ لَكُمْ قَدْ نَبَّأَنَا اللهُ مِنْ أَخْبارِكُمْ يبدو في الأفق البعيد ، ويقترب رويدا رويدا ، وإذا بالرسول صلى‌الله‌عليه‌وآله‌وسلم يزحف بهذه الجيوش المنتصرة في هيبة الرسالة السماوية ، ويلتقي الإمام بالرسول تلاقي الأخ بأخيه في فرح وسرور ، فقد كان الرسول صلى‌الله‌عليه‌وآله‌وسلم قد خلّف عليا في المدينة لئلّا يفسد المتخلفون الجو ، كما كانوا قد تآمروا ، وهناك قال له : « أنت مني بمنزلة هارون من موسى إلا أنه لا نبي بعدي » (1) ، ويجيء المتخلفون عن الجيش ، ليعتذروا عما تقدم منهم من تفريط ، ويطهروا آثامهم السالفة بالتوبة والندم ( يَعْتَذِرُونَ ) أي يعتذر المتخلفون من المنافقين الذين كان عددهم ثمانين ، وقد تخلفوا في المدينة خوفا ونفاقا ، وإرادة للتآمر على الرسول ، وقلب أوضاع المدينة ( إِلَيْكُمْ إِذا رَجَعْتُمْ إِلَيْهِمْ ) من غزوة « تبوك » بأعذار كاذبة باطلة لا حقيقة لها ولا واقع ، كما هو شأن المنافق في كل زمان ( قُلْ ) يا رسول الله لهم : ( لا تَعْتَذِرُوا ) فإن اعتذاركم لا يفيدكم ، فإنا ( لَنْ نُؤْمِنَ لَكُمْ ) أي لن نصدقكم في ما تقولون ( قَدْ نَبَّأَنَا اللهُ ) أخبرنا الله عز اسمه ( مِنْ أَخْبارِكُمْ ) وأعلمنا حقيقة أمركم ، وأنكم لم تخرجوا نفاقا وجبنا لا لعذر مشروع. وفي بعض التفاسير أن النبي صلى‌الله‌عليه‌وآله‌وسلم نهى المسلمين أن يكلموهم أو يجالسوهم ليذوقوا وبال أمرهم ، ولئلّا يتجرأ أحد على خرق أوامر ( 1) بحار الأنوار : ج 31 ص 366. وَسَيَرَى اللهُ عَمَلَكُمْ وَرَسُولُهُ ثُمَّ تُرَدُّونَ إِلى عالِمِ الْغَيْبِ وَالشَّهادَةِ فَيُنَبِّئُكُمْ بِما كُنْتُمْ تَعْمَلُونَ (94) سَيَحْلِفُونَ بِاللهِ لَكُمْ إِذَا انْقَلَبْتُمْ إِلَيْهِمْ لِتُعْرِضُوا عَنْهُمْ فَأَعْرِضُوا عَنْهُمْ الله والرسول (1) . ( وَسَيَرَى اللهُ عَمَلَكُمْ وَرَسُولُهُ ) أي سينظران في المستقبل إلى أعمالكم الدالة على نفاقكم وعدم صحة أعذاركم ، فإن عمل الإنسان في المستقبل دليل على عمله في الماضي ، فعمله بعضه من بعض ( ثُمَّ تُرَدُّونَ ) أي ترجعون ( إِلى عالِمِ الْغَيْبِ وَالشَّهادَةِ ) في الآخرة ، والمراد بذلك : التهديد ، وفي الآخرة سيحاسبكم الله على أعمالكم التي صدرت منكم ، كما يقول الحاكم للمجرم : « سترد إليّ » يريد تهديده بالعقاب ( فَيُنَبِّئُكُمْ ) أي يخبركم الله سبحانه ( بِما كُنْتُمْ تَعْمَلُونَ ) فيجازيكم عليها. [95] وجاء رئيس المنافقين « عبد الله بن أبي » حالفا للنبي صلى‌الله‌عليه‌وآله‌وسلم أن لا يتخلّف بعد هذه الغزوة ، وطلب من النبي صلى‌الله‌عليه‌وآله‌وسلم أن يرضى عنه ( سَيَحْلِفُونَ ) سيقسمون ( بِاللهِ لَكُمْ ) أيها المؤمنون ( إِذَا انْقَلَبْتُمْ إِلَيْهِمْ ) إذا رجعتم إليهم ووصلتم إلى المدينة ( لِتُعْرِضُوا عَنْهُمْ ) لتصفحوا عن جرمهم ، ولا توبّخوهم على ما صدر منهم ( فَأَعْرِضُوا عَنْهُمْ ) إعراض ردّ وإنكار ، لا إعراض صفح. ومن البلاغة التشابه في اللفظ والاختلاف في المعنى. ( 1) راجع مجمع البيان : ج 5 ص 106. إِنَّهُمْ رِجْسٌ وَمَأْواهُمْ جَهَنَّمُ جَزاءً بِما كانُوا يَكْسِبُونَ (95) يَحْلِفُونَ لَكُمْ لِتَرْضَوْا عَنْهُمْ فَإِنْ تَرْضَوْا عَنْهُمْ فَإِنَّ اللهَ لا يَرْضى عَنِ الْقَوْمِ الْفاسِقِينَ (96) الْأَعْرابُ ( إِنَّهُمْ رِجْسٌ ) أي نجس ، والمراد نجاسة باطنهم ، فهم كالشيء المنتن النجس الذي يلزم الاجتناب عنه ، وإلا أصاب الإنسان قذره ونتنه ( وَمَأْواهُمْ ) مصيرهم ( جَهَنَّمُ ) فهي مستقرّهم ( جَزاءً بِما كانُوا يَكْسِبُونَ ) من النفاق والآثام.` },
            { text: "يَعْتَذِرُونَ إِلَيْكُمْ إِذَا رَجَعْتُمْ إِلَيْهِمْ قُل لَّا تَعْتَذِرُوا۟ لَن نُّؤْمِنَ لَكُمْ قَدْ نَبَّأَنَا ٱللَّهُ مِنْ أَخْبَارِكُمْ وَسَيَرَى ٱللَّهُ عَمَلَكُمْ وَرَسُولُهُۥ ثُمَّ تُرَدُّونَ إِلَىٰ عَٰلِمِ ٱلْغَيْبِ وَٱلشَّهَٰدَةِ فَيُنَبِّئُكُم بِمَا كُنتُمْ تَعْمَلُونَ", tafsir: `` },
            { text: "سَيَحْلِفُونَ بِٱللَّهِ لَكُمْ إِذَا ٱنقَلَبْتُمْ إِلَيْهِمْ لِتُعْرِضُوا۟ عَنْهُمْ فَأَعْرِضُوا۟ عَنْهُمْ إِنَّهُمْ رِجْسٌ وَمَأْوَىٰهُمْ جَهَنَّمُ جَزَآءًۢ بِمَا كَانُوا۟ يَكْسِبُونَ", tafsir: `` },
            { text: "يَحْلِفُونَ لَكُمْ لِتَرْضَوْا۟ عَنْهُمْ فَإِن تَرْضَوْا۟ عَنْهُمْ فَإِنَّ ٱللَّهَ لَا يَرْضَىٰ عَنِ ٱلْقَوْمِ ٱلْفَٰسِقِينَ", tafsir: `يحلف هؤلاء المنافقون لكم أيها المسلمون ، يريدون بذلك تقوية أعذارهم وتصديقكم لهم ( لِتَرْضَوْا عَنْهُمْ ) طلبا لمرضاتكم حتى يؤمّنوا سعادتهم الدنيوية بينكم ( فَإِنْ تَرْضَوْا عَنْهُمْ ) مجاملة ، أو لعدم علمكم بواقعهم النفاقي ( فَإِنَّ اللهَ لا يَرْضى عَنِ الْقَوْمِ الْفاسِقِينَ ) الذين فسقوا وخرجوا عن طاعة الله سبحانه ، ثم لم يرجعوا عن نفاقهم ، قد علقت الآثام بقلوبهم فهي رجس نجس ، والمراد : أن الواجب عدم إظهار المؤمنين الرضا عنهم ، بعد ما علموا أن الله غير راض عنهم. [97] وبعد ما ينتهي الكلام حول الكفار والمؤمنين والمنافقين من أهل المدينة ونحوها ، يأتي دور ذكر الكفار والمؤمنين والمنافقين من أهل البوادي ، فإن لأهل البوادي لونا خاصا يميّزهم عن أهل المدن « فالأعراب أشد كفرا » لكفارهم ، ( مَنْ يَتَّخِذُ ما يُنْفِقُ مَغْرَماً ) لمنافقيهم ( مَنْ يُؤْمِنُ بِاللهِ ) لمؤمنيهم. ( الْأَعْرابُ ) يقال : رجل أعرابي ، إذا كان ساكنا في البادية سواء أَشَدُّ كُفْراً وَنِفاقاً وَأَجْدَرُ أَلاَّ يَعْلَمُوا حُدُودَ ما أَنْزَلَ اللهُ عَلى رَسُولِهِ وَاللهُ عَلِيمٌ حَكِيمٌ (97) وَمِنَ الْأَعْرابِ مَنْ يَتَّخِذُ ما يُنْفِقُ مَغْرَماً وَيَتَرَبَّصُ بِكُمُ الدَّوائِرَ كان عربيا أو أعجميا ، ويقال : رجل عربي إذا كان من العرب سواء سكن البادية أو المدينة ( أَشَدُّ كُفْراً وَنِفاقاً ) لأنهم حيث كانوا من أهل البادية سرت فيهم جفوة الصحراء وقساوة الجهل ، فكفرهم ونفاقهم أشد من كفر كفّار أهل المدن ونفاق منافقي أهل الحضر ، لبعدهم عن الحضارة والعلم والآداب ( وَأَجْدَرُ أَلَّا يَعْلَمُوا حُدُودَ ما أَنْزَلَ اللهُ عَلى رَسُولِهِ ) أي أنهم أحرى وأولى بعدم العلم بالفرائض والسنن وسائر الحدود التي أنزلها الله سبحانه على رسوله ، وإنما قال : « حدود » لأن حدود الأحكام أدق من نفس الأحكام ، ولذا كثيرا ما يعرف الناس الأحكام ، لكنهم لا يعلمون حدودها ، أي خصوصياتها وميّزاتها ، حتى لا يدخل فيها شيء ليس منها ، ولا يخرج منها شيء هو منها ( وَاللهُ عَلِيمٌ ) بهم وبأحوالهم ( حَكِيمٌ ) فيما يأمر وينهى بالنسبة إليهم. وفي الآية دلالة على ذم بقاء الإنسان أعرابيا ـ ساكنا للبادية ـ.` },
            { text: "ٱلْأَعْرَابُ أَشَدُّ كُفْرًا وَنِفَاقًا وَأَجْدَرُ أَلَّا يَعْلَمُوا۟ حُدُودَ مَآ أَنزَلَ ٱللَّهُ عَلَىٰ رَسُولِهِۦ وَٱللَّهُ عَلِيمٌ حَكِيمٌ", tafsir: `` },
            { text: "وَمِنَ ٱلْأَعْرَابِ مَن يَتَّخِذُ مَا يُنفِقُ مَغْرَمًا وَيَتَرَبَّصُ بِكُمُ ٱلدَّوَآئِرَ عَلَيْهِمْ دَآئِرَةُ ٱلسَّوْءِ وَٱللَّهُ سَمِيعٌ عَلِيمٌ", tafsir: `منافقون وهم ( مَنْ يَتَّخِذُ ما يُنْفِقُ ) في سبيل الله ( مَغْرَماً ) « المغرم » هو الغرم ، وهو نزول نائبة بالمال ، فهم يظنون أن ما أنفقوه في سبيل الله من جهاد أو غيره غرامة لحقت بأموالهم ، حيث لا يرجون خيره وثوابه ، ولا يصدّقون بما قال الله والرسول في سبيل بذل الأموال وأجرها ( وَيَتَرَبَّصُ بِكُمُ الدَّوائِرَ ) أي ينتظر بكم صروف الزمان وحوادث الأيام ، فقد كان هؤلاء المنافقون ينتظرون الانكسار والذلة والفقر وما أشبه للمؤمنين. وسميت الحوادث السيئة بالدوائر ، عَلَيْهِمْ دائِرَةُ السَّوْءِ وَاللهُ سَمِيعٌ عَلِيمٌ (98) وَمِنَ الْأَعْرابِ مَنْ يُؤْمِنُ بِاللهِ وَالْيَوْمِ الْآخِرِ وَيَتَّخِذُ ما يُنْفِقُ قُرُباتٍ عِنْدَ اللهِ وَصَلَواتِ الرَّسُولِ أَلا إِنَّها قُرْبَةٌ لَهُمْ سَيُدْخِلُهُمُ اللهُ فِي رَحْمَتِهِ إِنَّ اللهَ غَفُورٌ رَحِيمٌ (99) لأن الفلك يدور ، فإذا دار جاء بالمكروه ، ولذا يقال لمن يراد تحذيره : « لا تغفل من دوران الفلك » . ( عَلَيْهِمْ دائِرَةُ السَّوْءِ ) هذا دعاء على أولئك الأعراب المنافقين بأن تدور الدائرة الآتية بالعاقبة السيئة عليهم ، لا على المؤمنين ( وَاللهُ سَمِيعٌ ) لأقوالهم النفاقية ( عَلِيمٌ ) بضمائرهم ونواياهم ، فيجازيهم عليها.` },
            { text: "وَمِنَ ٱلْأَعْرَابِ مَن يُؤْمِنُ بِٱللَّهِ وَٱلْيَوْمِ ٱلْـَٔاخِرِ وَيَتَّخِذُ مَا يُنفِقُ قُرُبَٰتٍ عِندَ ٱللَّهِ وَصَلَوَٰتِ ٱلرَّسُولِ أَلَآ إِنَّهَا قُرْبَةٌ لَّهُمْ سَيُدْخِلُهُمُ ٱللَّهُ فِى رَحْمَتِهِۦٓ إِنَّ ٱللَّهَ غَفُورٌ رَّحِيمٌ", tafsir: `قسم طيّب وهو ( مَنْ يُؤْمِنُ بِاللهِ وَالْيَوْمِ الْآخِرِ ) فيعتقد بما جاء الرسول صلى‌الله‌عليه‌وآله‌وسلم من أحوال المعاد ( وَيَتَّخِذُ ما يُنْفِقُ قُرُباتٍ ) فيعلم أن إنفاقه يقرّبه من الله سبحانه ، فإن « قربات » جمع قربة ، وهي الأعمال الخيرة التي تورث قرب العبد من الله سبحانه قربا تشريفيا ( عِنْدَ اللهِ ) فهي تبقى عنده سبحانه لا تضيع ولا تذهب عبثا ، كما كان يظن بعض المنافقين الذين يتخذون إنفاقهم مغرما. ( وَصَلَواتِ الرَّسُولِ ) أي يبتغي بما ينفق دعوات الرسول صلى‌الله‌عليه‌وآله‌وسلم بأن يدعو له بالخير ، فإن « الصلاة » بمعنى العطف والرحمة والدعاء ، فهو عطف على « قربات » ( أَلا إِنَّها ) أي نفقاتهم ( قُرْبَةٌ لَهُمْ ) موجبة لقربهم إلى ساحة رضا الله سبحانه ، فلهم ما ابتغوا ، ويبشّرون بحسن العاقبة ( سَيُدْخِلُهُمُ اللهُ فِي رَحْمَتِهِ ) فتغمرهم الرحمة في الجنة ( إِنَّ اللهَ غَفُورٌ ) لذنوبهم ( رَحِيمٌ ) بهم وَالسَّابِقُونَ الْأَوَّلُونَ مِنَ الْمُهاجِرِينَ وَالْأَنْصارِ وَالَّذِينَ اتَّبَعُوهُمْ بِإِحْسانٍ رَضِيَ اللهُ عَنْهُمْ وَرَضُوا عَنْهُ وَأَعَدَّ لَهُمْ جَنَّاتٍ تَجْرِي تَحْتَهَا الْأَنْهارُ خالِدِينَ فِيها أَبَداً ذلِكَ الْفَوْزُ الْعَظِيمُ (100) وَمِمَّنْ حَوْلَكُمْ مِنَ الْأَعْرابِ مُنافِقُونَ يتفضّل عليهم بالرحمة والرضوان. [100] وبعد ذكر أقسام من أهل البلاد وأهل البادية ، يبيّن سبحانه أحوال الأمة بصورة عامة ، وأن فيهم المؤمن والمنافق والكافر ، وأن لكلّ درجات ومراتب ( وَالسَّابِقُونَ ) إلى الإيمان والطاعة ( الْأَوَّلُونَ ) بالنسبة إلى غيرهم ، وإن كان فيهم الأول فالأول ( مِنَ الْمُهاجِرِينَ ) المسلمين الذين هاجروا من مكة إلى الحبشة أو إلى المدينة ( وَالْأَنْصارِ ) للإسلام وهم أهل المدينة الذين سبقوا إلى الإيمان والنصرة ( وَالَّذِينَ اتَّبَعُوهُمْ بِإِحْسانٍ ) أي بالإيمان والطاعة ، فإن الاتّباع يلزم أن يكون لشيء ( رَضِيَ اللهُ عَنْهُمْ ) ومعنى رضاه أنه أكرمهم وأوجب لهم الخير والجنة ( وَرَضُوا عَنْهُ ) فهم فائزون بشرف الرضا ، ومن دخل قلبه الرضا عن الرب ارتاح واطمأن ( وَأَعَدَّ ) الله ( لَهُمْ جَنَّاتٍ تَجْرِي تَحْتَهَا الْأَنْهارُ ) أي من تحت أشجارها وقصورها ( خالِدِينَ فِيها أَبَداً ) لا زوال لهم عنها ، ولا تغيّر لها عنهم ( ذلِكَ ) الرضوان والجنة ( الْفَوْزُ الْعَظِيمُ ) والفلاح الذي يصغر دونه كل شيء ، وإنما فضّل الله السابقين لما تحمّلوه من المشاق والأتعاب في نصرة الدين والجهاد في سبيله.` },
            { text: "وَٱلسَّٰبِقُونَ ٱلْأَوَّلُونَ مِنَ ٱلْمُهَٰجِرِينَ وَٱلْأَنصَارِ وَٱلَّذِينَ ٱتَّبَعُوهُم بِإِحْسَٰنٍ رَّضِىَ ٱللَّهُ عَنْهُمْ وَرَضُوا۟ عَنْهُ وَأَعَدَّ لَهُمْ جَنَّٰتٍ تَجْرِى تَحْتَهَا ٱلْأَنْهَٰرُ خَٰلِدِينَ فِيهَآ أَبَدًا ذَٰلِكَ ٱلْفَوْزُ ٱلْعَظِيمُ", tafsir: `` },
            { text: "وَمِمَّنْ حَوْلَكُم مِّنَ ٱلْأَعْرَابِ مُنَٰفِقُونَ وَمِنْ أَهْلِ ٱلْمَدِينَةِ مَرَدُوا۟ عَلَى ٱلنِّفَاقِ لَا تَعْلَمُهُمْ نَحْنُ نَعْلَمُهُمْ سَنُعَذِّبُهُم مَّرَّتَيْنِ ثُمَّ يُرَدُّونَ إِلَىٰ عَذَابٍ عَظِيمٍ", tafsir: `أي في أطراف بلدكم ( مِنَ الْأَعْرابِ ) الساكنين في البادية ، أي بعضهم ( مُنافِقُونَ ) يظهرون الإيمان ويبطنون الكفر وَمِنْ أَهْلِ الْمَدِينَةِ مَرَدُوا عَلَى النِّفاقِ لا تَعْلَمُهُمْ نَحْنُ نَعْلَمُهُمْ سَنُعَذِّبُهُمْ مَرَّتَيْنِ ثُمَّ يُرَدُّونَ إِلى عَذابٍ عَظِيمٍ (101) وَآخَرُونَ اعْتَرَفُوا بِذُنُوبِهِمْ ( وَمِنْ أَهْلِ الْمَدِينَةِ ) أيضا منافقون ( مَرَدُوا ) أي تمرّنوا حتى صاروا ماهرين ( عَلَى النِّفاقِ ) وذكرهم بهذه الصفة للإشعار بخطرهم ، فإن المنافق الماهر أكثر خطرا من غيره من المنافقين ( لا تَعْلَمُهُمْ ) أي لا تدرك حقيقة نفاقهم ولا تعرف أشخاصهم ، وهو تقرير لمهارتهم فيه ، بحيث يخفون عليك حتى أنك لا تعلم ذلك. وهذا لا غضاضة فيه ، فإن النبي صلى‌الله‌عليه‌وآله‌وسلم كان يعلم الغيب إذا شاء الله. ومن المعلوم أن الله إذا لم يشأ تعليمه بشيء لم يعلمه. ومن المحتمل أن يكون لفظة « لا تعلمهم » استعملت بقصد التهويل من نفاقهم ، فإن مثل هذا اللفظ يستعمل بقصد شيء آخر غير معناه ، فيقال : « أنت لا تعرف زيدا كيف يحسن » يراد بذلك أنه كثير الإحسان. ( نَحْنُ نَعْلَمُهُمْ ) ونعرف حقائقهم ( سَنُعَذِّبُهُمْ مَرَّتَيْنِ ) لعلّ المراد : مرّة في الدنيا بالتضييق عليهم وعدم هدوء بالهم ، كما قال تعالى : ( وَمَنْ أَعْرَضَ عَنْ ذِكْرِي فَإِنَّ لَهُ مَعِيشَةً ضَنْكاً ) (1) ، ومرّة في القبر ( ثُمَّ يُرَدُّونَ إِلى عَذابٍ عَظِيمٍ ) هو عذاب النار في الآخرة.` },
            { text: "وَءَاخَرُونَ ٱعْتَرَفُوا۟ بِذُنُوبِهِمْ خَلَطُوا۟ عَمَلًا صَٰلِحًا وَءَاخَرَ سَيِّئًا عَسَى ٱللَّهُ أَن يَتُوبَ عَلَيْهِمْ إِنَّ ٱللَّهَ غَفُورٌ رَّحِيمٌ", tafsir: `من أهل المدينة ومن الأعراب حولها ( اعْتَرَفُوا بِذُنُوبِهِمْ ) فقد جاء بعض المتخلّفين معتذرين إلى الرسول صلى‌الله‌عليه‌وآله‌وسلم عما صدر منهم من التخلّف ، وكانوا سبعة ندموا على قعودهم وتخلّفهم عن ( 1) طه : 125. خَلَطُوا عَمَلاً صالِحاً وَآخَرَ سَيِّئاً عَسَى اللهُ أَنْ يَتُوبَ عَلَيْهِمْ إِنَّ اللهَ غَفُورٌ رَحِيمٌ (102) خُذْ مِنْ أَمْوالِهِمْ صَدَقَةً تُطَهِّرُهُمْ الجهاد في غزوة تبوك لما بلغهم ما نزل في المتخلفين ، فأيقنوا على أنفسهم بالعذاب فأوثقوا أنفسهم على سواري المسجد ، فقدم رسول الله فدخل المسجد وصلّى ركعتين ـ وكانت هذه عادته إذا قدم من السفر ـ فلما رآهم موثقين سأل عنهم ، فذكر له أنهم أقسموا أن لا يحلّوا أنفسهم حتى يحلّهم رسول الله صلى‌الله‌عليه‌وآله‌وسلم ، فقال صلى‌الله‌عليه‌وآله‌وسلم : وأنا أقسم أني لا أحلهم حتى أؤمر فيهم. فنزلت الآية ، فأطلقهم الرسول صلى‌الله‌عليه‌وآله‌وسلم ، فقالوا بعد ما فكّهم : هذه أموالنا ، وإنما تخلفنا عنك بسببها ، فخذها وتصدق بها وطهّرنا ، فقال صلى‌الله‌عليه‌وآله‌وسلم : « ما أمرت أن آخذ من أموالكم شيئا » ، فنزلت ( ( خُذْ مِنْ أَمْوالِهِمْ صَدَقَةً تُطَهِّرُهُمْ وَتُزَكِّيهِمْ بِها .. ) (1) . ( خَلَطُوا عَمَلاً صالِحاً وَ ) عملا ( آخَرَ سَيِّئاً ) فإنهم كانوا يقيمون الصلاة ويأتمرون بأوامر الرسول لكنهم تركوا الجهاد في تبوك ( عَسَى اللهُ أَنْ يَتُوبَ عَلَيْهِمْ ) وإنما قال : « عسى » ليكونوا بين الخوف والرجاء ( إِنَّ اللهَ غَفُورٌ ) للذنوب ( رَحِيمٌ ) بالناس يتفضّل عليهم بالرحمة.` },
            { text: "خُذْ مِنْ أَمْوَٰلِهِمْ صَدَقَةً تُطَهِّرُهُمْ وَتُزَكِّيهِم بِهَا وَصَلِّ عَلَيْهِمْ إِنَّ صَلَوٰتَكَ سَكَنٌ لَّهُمْ وَٱللَّهُ سَمِيعٌ عَلِيمٌ", tafsir: `يا رسول الله ( مِنْ أَمْوالِهِمْ ) أي أموال هؤلاء الذين خلطوا عملا صالحا وآخر سيئا ( صَدَقَةً ) هي بعض أموالهم ، ولذا جاء ب « من » . والظاهر من السياق أنها غير الصدقة المفروضة التي هي من الزكاة. وقد قال المفسرون : إن الرسول صلى‌الله‌عليه‌وآله‌وسلم أخذ ثلث أموال التائبين وترك لهم الثلثين (2) ( تُطَهِّرُهُمْ ) تلك الصدقة عن دنس الذنوب ( 1) التوبة : 103. ( 2) راجع بحار الأنوار : ج 21 ص 201. وَتُزَكِّيهِمْ بِها وَصَلِّ عَلَيْهِمْ إِنَّ صَلاتَكَ سَكَنٌ لَهُمْ وَاللهُ سَمِيعٌ عَلِيمٌ (103) والخطايا ، أو المراد تطهرهم أنت بتلك الصدقة ، وتطهير الإنسان بالصدقة إنما هو تطهير معنوي ، فإن للذنوب نجاسة ، والصدقة توجب تنظيف الإنسان من تلك النجاسة ، لأنها موجبة للغفران وحتّ الآثام ( وَتُزَكِّيهِمْ بِها ) « التزكية » هي التنمية أي توجب لهم النمو ، وذلك أعم من النمو الخلقي والخلقي وسائر أقسام النمو ، وسميت الزكاة زكاة ، لأنها توجب نمو صاحبها ، أو المال المزكّى ، و « تزكيهم » خطاب ، بخلاف « تطهّرهم » المحتمل للأمرين. ( وَصَلِ ) يا رسول الله ( عَلَيْهِمْ ) على معطي الصدقة ، والمراد ب « الصلاة عليهم » الدعاء لهم ، فإن الصلاة عبارة عن الدعاء ، فإن صاحب الصدقة إذا دعا له الرسول صلى‌الله‌عليه‌وآله‌وسلم كان جبرا لما يحسّ به من ألم فقد المال ( إِنَّ صَلاتَكَ ) عليهم ( سَكَنٌ لَهُمْ ) أي موجبة لسكون خاطرهم وهدوء بالهم وارتياح نفوسهم. روي أن النبي صلى‌الله‌عليه‌وآله‌وسلم إذا أتاه آت بالصدقة قال : « اللهم صلّ عليه » (1) . والظاهر تحقق الصلاة بكل لفظ أفاد الدعاء ، نحو : « بارك الله لك أو آجرك الله » أو ما أشبه ، كما أن الظاهر من السياق والتعليل أن الحكم عام لا يخص الرسول صلى‌الله‌عليه‌وآله‌وسلم ، وذلك لأن لنا برسول الله أسوة حسنة ، فما دل على الخصوصية استثني ، وما لم يدل بقي على عموم الأسوة ( وَاللهُ سَمِيعٌ ) لأقوالك وأقوالهم ( عَلِيمٌ ) بصدقاتهم وما نووه ( 1) راجع مجمع البيان : ج 5 ص 118. أَ لَمْ يَعْلَمُوا أَنَّ اللهَ هُوَ يَقْبَلُ التَّوْبَةَ عَنْ عِبادِهِ وَيَأْخُذُ الصَّدَقاتِ وَأَنَّ اللهَ هُوَ التَّوَّابُ من النيات الصالحة.` },
            { text: "أَلَمْ يَعْلَمُوٓا۟ أَنَّ ٱللَّهَ هُوَ يَقْبَلُ ٱلتَّوْبَةَ عَنْ عِبَادِهِۦ وَيَأْخُذُ ٱلصَّدَقَٰتِ وَأَنَّ ٱللَّهَ هُوَ ٱلتَّوَّابُ ٱلرَّحِيمُ", tafsir: `أي : ألم يعلم هؤلاء المتصدقين ، أو الناس جميعا ؟! وهذا تحريض للناس على التوبة والتصدق ، لا لأولئك التائبين الذين أرادوا أن يتصدقوا. فلا يقال : أنه لا مجال لمثل هذا الاستفهام إلا للمنكر ، فلا يحسن أن يقول الإنسان لمريد الحج : « ألا تعلم أن للحج ثوابا عظيما » ، بل إنما يحسن قول ذلك لمن يريد الحج. وإنما جاء الاستفهام في سياق قصة التائبين لإعطاء الصدقة للمناسبة ( أَنَّ اللهَ هُوَ يَقْبَلُ التَّوْبَةَ عَنْ عِبادِهِ ) فلا صغار في التوبة حتى يأنف الإنسان من الإنابة ، إن طرف القبول هو الله العظيم الشأن ، وهذا أمر طبيعي ، فإن الإنسان لا يكره الاعتراف لدى العظيم ، وإنما يكرهه لدى الحقير ( وَيَأْخُذُ الصَّدَقاتِ ) أي يقبلها ، فليس الآخذ هو الفقير حتى لا يهتم الإنسان بشأنه ، وإنما هو سبحانه ، وذلك يوجب الإعطاء بكثرة واحترام ، لا بقلة وإهانة ، كما هو الطبع البشري في إرادة إعطاء الشيء لمن دونه. و في الخبر : أن النبي صلى‌الله‌عليه‌وآله‌وسلم قال : « إن الصدقة تقع في يد الله قبل أن تصل إلى يد السائل » (1) ، وهذا على وجه تشبيه المعقول بالمحسوس ، مبالغة في الأمر. ( وَأَنَّ اللهَ هُوَ التَّوَّابُ ) كثير قبول التوبة ، إما باعتبار الأفراد ، وإما ( 1) فقه القرآن : ج 1 ص 222 .. الرَّحِيمُ (104) وَقُلِ اعْمَلُوا فَسَيَرَى اللهُ عَمَلَكُمْ وَرَسُولُهُ وَالْمُؤْمِنُونَ باعتبار كل فرد حيث أن الإنسان لو عصى ألف مرة وفي كل مرة تاب قبلت توبته ، إذا كانت توبة نصوحا ( الرَّحِيمُ ) الذي يرحم العباد ويتفضّل عليهم. [105] وبمناسبة أن الله يقبل التوبة ويأخذ الصدقة ، مما يدل على أنه سبحانه مطّلع على الأعمال ، يأتي السياق لبيان أن كل الأعمال كذلك ، وليس ذاك خاصا بالتوبة والصدقة ، وإن الاطّلاع ليس خاصا بالله سبحانه بل الرسول والمؤمنون أيضا مشاركون له سبحانه في الاطّلاع على أعمال الناس ، وإن كان هناك فرق بين الاطّلاعين ، فالله سبحانه يعلم كل شيء من كل أحد ، والرسول والمؤمنون مطّلعون بقدر ما يريد الله سبحانه. ( وَقُلِ ) يا رسول الله للناس عامة : ( اعْمَلُوا ) ما شئتم من خير وشر ، إن كان المراد صبّ الكلام على أن عملكم سوف يرى ، لأنه حينئذ تجرد الصيغة عن معنى الأمر ، أو المراد : اعملوا الأعمال الحسنة ( فَسَيَرَى اللهُ عَمَلَكُمْ ) يعلمها سبحانه ، ولعلّ دخول « السين » لأن الرؤية إنما تكون بعد وجود العمل ( وَرَسُولُهُ وَالْمُؤْمِنُونَ ) وذلك واضح لا يحتاج إلى التأويل ، أ رأيت أن الناس يعلمون الخير من الشر كما يعرفون مقادير الأشخاص في أعمالهم ، منتهى الأمر أن الله سبحانه يعلم الخفايا بالتفصيل ، والمؤمنون يعلمون بالإجمال. وربما يقال : إن دخول « السين » لتوحيد السياق بين الله والرسول والمؤمنين ، حيث أنهم لا يرون العمل إلا بعد زمان من وقوعه ، كما وَسَتُرَدُّونَ إِلى عالِمِ الْغَيْبِ وَالشَّهادَةِ فَيُنَبِّئُكُمْ بِما كُنْتُمْ تَعْمَلُونَ (105) وَآخَرُونَ مُرْجَوْنَ لِأَمْرِ اللهِ إِمَّا يُعَذِّبُهُمْ وَإِمَّا يَتُوبُ عَلَيْهِمْ وَاللهُ عَلِيمٌ ربما يقال : إن الإتيان بهذه الآية عقب الآية السابقة لإفادة أن التوبة المجردة لا تنفع وإنما اللازم تصديقها بالعمل. وما ورد في بعض الأخبار : أن المراد بالمؤمنين الأئمة عليهم‌السلام (1) فهو من باب المصداق الظاهر ، وإلا فالعموم على حاله ، كسائر الآيات العامة التي لها مصاديق ظاهرة. ( وَسَتُرَدُّونَ ) أي ترجعون بعد موتكم ( إِلى عالِمِ الْغَيْبِ ) ما غاب عن الحواس ( وَالشَّهادَةِ ) ما يشهده الإنسان أي يحضره ، وهو كل ما يدرك بالحواس الظاهرة ، أي سترجعون إلى عالم السر والعلانية ( فَيُنَبِّئُكُمْ ) أي يخبركم للجزاء ( بِما كُنْتُمْ تَعْمَلُونَ ) من خير أو شر. [106] كان المتخلفون عن غزوة تبوك بين منافق معتذر ، ومنافق غير معتذر ، ومخطئ معترف ( وَ ) هناك ( آخَرُونَ ) من المتخلفين ( مُرْجَوْنَ لِأَمْرِ اللهِ ) أي مؤخّرون موقوفون ، من « أرجأ » بمعنى « أخّر » فلم يكن هذا القسم منافقا ، ولا مخطئا ، بل إنما تخلّف توانيا عن الاستعداد حتى فاته المسير ، ولم يكن قبل نزول الآية قد بتّ في أمرهم بشيء بل كان موكولا إليه سبحانه ، إما يعذبهم بتوانيهم ، وإما يتوب عليهم بسبب أنهم لم ينافقوا ولم تدنس قلوبهم ( إِمَّا يُعَذِّبُهُمْ ) لعصيانهم وتخلفهم ( وَإِمَّا يَتُوبُ عَلَيْهِمْ ) لنقاء قلوبهم ( وَاللهُ عَلِيمٌ ) ( 1) بحار الأنوار : ج 23 ص 347. حَكِيمٌ (106) بنياتهم وسبب توانيهم عن غزوة تبوك ( حَكِيمٌ ) فيما يفعله بهم من العذاب والتوبة. لكن الله سبحانه تاب عليهم أخيرا ، وهؤلاء هم الذين ذكروا في قوله تعالى في آخر السورة ( وَعَلَى الثَّلاثَةِ الَّذِينَ خُلِّفُوا ) (1) وكان من قصتهم ما ذكره المفسرون حيث قالوا : قد كان تخلف عن رسول الله قوم منافقون وقوم مؤمنون مستبصرون لم يعثر عليهم في نفاق وهم كعب بن مالك ومرارة بن الربيع وهلال بن أمية ، فلما تاب الله عليهم قال كعب : ما كنت قط أقوى مني في ذلك الوقت الذي خرج رسول الله صلى‌الله‌عليه‌وآله‌وسلم إلى تبوك وما اجتمعت لي راحلتان إلا في ذلك اليوم فكنت أقول : أخرج غدا ، أخرج بعد غد ، فإني قوي ، وتوانيت وبقيت بعد خروج النبي صلى‌الله‌عليه‌وآله‌وسلم أياما أدخل السوق ولا أقضي حاجة ، فلقيت هلال ومرارة وقد كانا تخلّفا أيضا فتوافقنا أن نبكر إلى السوق ولم نقض حاجة ، فما زلنا نقول : نخرج غدا وبعد غد حتى بلغنا إقبال رسول الله صلى‌الله‌عليه‌وآله‌وسلم فندمنا ، فلما وافى رسول الله صلى‌الله‌عليه‌وآله‌وسلم استقبلناه نهنّئه بالسلامة فسلمنا عليه ، فلم يرد علينا السلام وأعرض عنا ، وسلمنا على إخواننا فلم يردوا علينا السلام. فبلغ ذلك أهلونا فقطعوا كلامنا ، وكنا نحضر المسجد فلا يسلم علينا أحد ولا يكلمنا ، فجاءت نساؤنا إلى رسول الله صلى‌الله‌عليه‌وآله‌وسلم فقلن : قد بلغنا سخطك على أزواجنا أ فنعتزلهم ؟ فقال رسول الله صلى‌الله‌عليه‌وآله‌وسلم : لا تعتزلنهم ولكن لا يقربوكن ، فلما رأى كعب وصاحباه ما حل بهم ( 1) المستدرك : ج 7 ص 12. قالوا : ما يقعدنا بالمدينة ولا يكلمنا رسول الله صلى‌الله‌عليه‌وآله‌وسلم ولا إخواننا ولا أهلنا فهلموا نخرج إلى هذا الجبل فلا نزال فيه حتى يتوب الله علينا أو نموت. فخرجوا إلى « ذناب » جبل بالمدينة فكانوا يصومون وكان أهلوهم يأتونهم بالطعام فيضعونه ناحية ثم يولون عنهم فلا يكلمونهم ، فبقوا على هذه الحالة أياما كثيرة يبكون بالليل والنهار ، ويدعون الله أن يغفر لهم ، فلما طال عليهم الأمر قال كعب : يا قوم قد سخط الله علينا ورسوله وسخط علينا إخواننا وسخط علينا أهلونا ، فلا يكلم أحد منهم صاحبه حتى يموت أو يتوب الله عليه. فبقوا على هذا ثلاثة أيام كلّ منهم في ناحية من الجبل لا يرى أحد منهم صاحبه ولا يكلمه ، فلما كان في الليلة الثالثة ورسول الله في بيت أم سلمة نزلت توبتهم على رسول الله ، وهو قوله سبحانه : ( وَعَلَى الثَّلاثَةِ الَّذِينَ .. ) فأرسل النبي صلى‌الله‌عليه‌وآله‌وسلم من يبشرهم ، وجاءوا مسلّمين على الرسول صلى‌الله‌عليه‌وآله‌وسلم ، وقد بان السرور في وجهه الشريف صلى‌الله‌عليه‌وآله‌وسلم ، وتصدق كعب بثلث ماله شكرا لله تعالى (1) . وفي بعض الأحاديث : انطباق الآية على مثل « الوحشي » قاتل حمزة عليه‌السلام حيث أسلم بعد الجريمة ، فإنه مرجأ لأمر الله إما يعذبه وإما يتوب عليه (2) . [107] ثم ذكر سبحانه قصة جماعة أخرى من المنافقين الذين ارتبطت ( 1) بحار الأنوار : ج 21 ص 202. ( 2) راجع الكافي : ج 2 ص 381. قصتهم بقصة تبوك وهم الذين أرادوا أن يتستروا بمسجد « ضرار » لحبك المؤامرات ضد الرسول صلى‌الله‌عليه‌وآله‌وسلم والمسلمين ، وأرادوا انقلاب الأمر في المدينة لكن الله وقى المسلمين شرهم وأعلم الرسول صلى‌الله‌عليه‌وآله‌وسلم بما نووه من المكر. فقد روى بعض أهل السير : أنه كان بالمدينة قبل مقدم رسول الله صلى‌الله‌عليه‌وآله‌وسلم إليها رجل من الخزرج يقال له أبو عامر الراهب وكان قد تنصّر وله عبادة في الجاهلية وله شرف كبير في قبيلته الخزرج ، فلما قدم رسول الله صلى‌الله‌عليه‌وآله‌وسلم مهاجرا إلى المدينة واجتمع عليه المسلمون وصارت للإسلام كلمة عالية وأظهرهم الله يوم بدر ، شرق أبو عامر بريقه وبارز بالعداوة وظاهر بها وخرج فارا إلى كفار مكة من مشركي قريش يمالؤهم على حرب رسول الله صلى‌الله‌عليه‌وآله‌وسلم فاجتمعوا بمن وافقهم من أحياء العرب وقدموا عام أحد. وكان من أمر المسلمين ما كان ، وقد امتحنهم الله عزوجل وكانت العاقبة للمتقين ، وكان هذا الفاسق قد حفر حفائر فيما بين الصفين ، فوقع في إحداهن رسول الله صلى‌الله‌عليه‌وآله‌وسلم ، وأصيب ذلك اليوم ، فجرح وجهه ، وكسرت رباعيته اليمنى السفلى وشج رأسه صلى‌الله‌عليه‌وآله‌وسلم . وتقدم أبو عامر في أول المبارزة إلى قومه من الأنصار فخاطبهم وحثهم إلى نصرته وموافقته ، فلما عرفوا كلامه قالوا : لا أنعم الله بك عينا يا فاسق يا عدو الله ، ونالوا منه وسبّوه ، فرجع وهو يقول : والله لقد أصاب قومي شر. ولما فرغ الناس من أحد ورأى أمر الرسول صلى‌الله‌عليه‌وآله‌وسلم في ارتفاع وظهور ذهب إلى « هرقل » ملك الروم يستنصره على النبي صلى‌الله‌عليه‌وآله‌وسلم فوعده ومنّاه وأقام عنده ، وكتب إلى جماعة من قومه من وَالَّذِينَ اتَّخَذُوا مَسْجِداً ضِراراً الأنصار من أهل النفاق والريب يعدهم ويمنيهم أنه سيقدم بجيش يقاتل به رسول الله ويغلبه ويردّه عمّا هو فيه ، وأمرهم أن يتخذوا له معقلا يقدم عليه من عنده لأداء كتبه ويكون مرصدا لهم إذا قدم عليهم بعد ذلك. فشرعوا في بناء مسجد مجاور لمسجد « قبا » فبنوه وأحكموه وفرغوا منه قبل خروج رسول الله صلى‌الله‌عليه‌وآله‌وسلم إلى تبوك وجاءوا فسألوا الرسول صلى‌الله‌عليه‌وآله‌وسلم أن يأتي إليهم فيصلي في مسجدهم ليحتجوا بصلاته فيه على تقريره وإثباته ، وذكروا أنهم إنما بنوه للضعفاء منهم وأهل العلة في الليلة الشاتية ، فعصمه الله من الصلاة فيه ، فقال صلى‌الله‌عليه‌وآله‌وسلم : أنا على سفر ولكن إذا رجعنا إن شاء الله. فلما قفل صلى‌الله‌عليه‌وآله‌وسلم راجعا إلى المدينة من تبوك ، ولم يبق بينه وبينها إلا يوم أو بعض يوم نزل عليه الوحي بخبر مسجد « ضرار » وما أبطن بانوه من الكفر والتفريق بين جماعة المؤمنين في مسجدهم ـ مسجد قبا ـ فأرسل الرسول صلى‌الله‌عليه‌وآله‌وسلم من هدم المسجد وأحرقه ، وأمر أن يتخذ مكانه كناسة يلقى فيها الجيف والقمامة ، وردّ الله كيده ، فأصاب أبا عامر قبل رجوعه إلى المدينة بالقولنج والبرص والفالج واللّقوة ، وبقي أربعين يوما في عذاب الدنيا ، ثم هلك إلى عذاب السعير (1) . وفي هذه القصة نزلت هذه الآيات : ( وَ ) منهم ( الَّذِينَ اتَّخَذُوا ) أي بنوا ( مَسْجِداً ) وهو اسم لبقعة يتّخذ للصلاة ، وإن كان أصله بمعنى موضع السجود ( ضِراراً ) أي مضارّة ، فإنه مصدر من باب « المفاعلة » ، يقال : « ضارّ ضرارا وضيرارا » ، ( 1) تفسير الإمام العسكري : ص 487. وَكُفْراً وَتَفْرِيقاً بَيْنَ الْمُؤْمِنِينَ وَإِرْصاداً لِمَنْ حارَبَ اللهَ وَرَسُولَهُ مِنْ قَبْلُ وَلَيَحْلِفُنَّ إِنْ أَرَدْنا إِلاَّ الْحُسْنى وَاللهُ يَشْهَدُ إِنَّهُمْ لَكاذِبُونَ (107) لا تَقُمْ فِيهِ أَبَداً لَمَسْجِدٌ أُسِّسَ عَلَى التَّقْوى فإنهم بنوه لأجل الإضرار بالمسلمين ( وَكُفْراً ) لأجل الكفر ( وَتَفْرِيقاً بَيْنَ الْمُؤْمِنِينَ ) أي لاختلاف الكلمة وإبطال الألفة ، وجعل المسلمين طائفتين ، الموالي للرسول ، والمخالف له ( وَإِرْصاداً ) لأجل الإعداد للفتنة ، وأن يجعلوه محل رصد وإشراف ( لِمَنْ حارَبَ اللهَ وَرَسُولَهُ مِنْ قَبْلُ ) وهو أبو عامر الراهب. وهذا أبو حنظلة غسيل الملائكة الذي هو من أخيار المؤمنين ، وقد تقدم أن أبا عامر كان حربا للرسول من قبل غزوة تبوك. وقد سماه الرسول صلى‌الله‌عليه‌وآله‌وسلم ب « الفاسق » . ( وَلَيَحْلِفُنَ ) أي يحلف هؤلاء الذين اتخذوا المسجد وكانوا اثني عشر ( إِنْ أَرَدْنا ) أي ما أردنا ببنائنا للمسجد ( إِلَّا الْحُسْنى ) أي الفعلة الحسنة ، من إقامة الصلاة ، ودرك الجماعة في الليلة الشاتية والممطرة للضعفاء ونحوهم ( وَاللهُ يَشْهَدُ إِنَّهُمْ لَكاذِبُونَ ) فإنهم لم يريدوا ببنائه الحسنى ، بل السوءة والتآمر على الرسول صلى‌الله‌عليه‌وآله‌وسلم وكفى بالله شهيدا على ذلك ، بالإضافة إلى ما عرف بعد ذلك من الأدلة والشواهد.` },
            { text: "وَقُلِ ٱعْمَلُوا۟ فَسَيَرَى ٱللَّهُ عَمَلَكُمْ وَرَسُولُهُۥ وَٱلْمُؤْمِنُونَ وَسَتُرَدُّونَ إِلَىٰ عَٰلِمِ ٱلْغَيْبِ وَٱلشَّهَٰدَةِ فَيُنَبِّئُكُم بِمَا كُنتُمْ تَعْمَلُونَ", tafsir: `` },
            { text: "وَءَاخَرُونَ مُرْجَوْنَ لِأَمْرِ ٱللَّهِ إِمَّا يُعَذِّبُهُمْ وَإِمَّا يَتُوبُ عَلَيْهِمْ وَٱللَّهُ عَلِيمٌ حَكِيمٌ", tafsir: `` },
            { text: "وَٱلَّذِينَ ٱتَّخَذُوا۟ مَسْجِدًا ضِرَارًا وَكُفْرًا وَتَفْرِيقًۢا بَيْنَ ٱلْمُؤْمِنِينَ وَإِرْصَادًا لِّمَنْ حَارَبَ ٱللَّهَ وَرَسُولَهُۥ مِن قَبْلُ وَلَيَحْلِفُنَّ إِنْ أَرَدْنَآ إِلَّا ٱلْحُسْنَىٰ وَٱللَّهُ يَشْهَدُ إِنَّهُمْ لَكَٰذِبُونَ", tafsir: `` },
            { text: "لَا تَقُمْ فِيهِ أَبَدًا لَّمَسْجِدٌ أُسِّسَ عَلَى ٱلتَّقْوَىٰ مِنْ أَوَّلِ يَوْمٍ أَحَقُّ أَن تَقُومَ فِيهِ فِيهِ رِجَالٌ يُحِبُّونَ أَن يَتَطَهَّرُوا۟ وَٱللَّهُ يُحِبُّ ٱلْمُطَّهِّرِينَ", tafsir: `يا رسول الله ( فِيهِ ) في ذلك المسجد ( أَبَداً ) يقال : «فلان يقوم الليل » أي يصلّي ، والمعنى : لا تصلّ في ذلك المسجد ، ولم يكن هذا خلفا من الرسول لوعده بالصلاة فيه ، لأنه صلى‌الله‌عليه‌وآله‌وسلم قال : « إن شاء الله » فلم يشأ الله ونهاه عن ذلك ( لَمَسْجِدٌ أُسِّسَ عَلَى التَّقْوى ) مِنْ أَوَّلِ يَوْمٍ أَحَقُّ أَنْ تَقُومَ فِيهِ فِيهِ رِجالٌ يُحِبُّونَ أَنْ يَتَطَهَّرُوا وَاللهُ يُحِبُّ الْمُطَّهِّرِينَ (108) أي بني أصله على تقوى الله ، وطاعته ( مِنْ أَوَّلِ يَوْمٍ ) منذ أول يوم وضع أساسه ، وهو مسجد « قبا » فإن الرسول صلى‌الله‌عليه‌وآله‌وسلم لما هاجر إلى المدينة أقام هناك أياما وبنى فيه هذا المسجد وصلى فيه ، ثم انتقل إلى المدينة ، وبنى فيه مسجده الذي دفن في حجرة مجاورة له ( أَحَقُّ أَنْ تَقُومَ فِيهِ ) للصلاة ، من مسجد « ضرار » . ولا يراد بهذا أن يصلي النبي صلى‌الله‌عليه‌وآله‌وسلم دائما في مسجد « قبا » بل إنه إذا أراد الصلاة هناك ـ خارج المدينة ـ فمسجد « قبا » أولى بالصلاة فيه من مسجد « ضرار » ( فِيهِ ) في هذا المسجد. والمراد بالظرف ذلك المكان ، أي أن القبيلة الموجودة هناك وهم بنو عمرو بن عوف ( رِجالٌ يُحِبُّونَ أَنْ يَتَطَهَّرُوا ) من لوث المعاصي والذنوب ، وليسوا مثل بني غنم أصحاب مسجد ضرار الذين بنوه ، فهم رجال يحبون النجاسة ولوث المعاصي ( وَاللهُ يُحِبُّ الْمُطَّهِّرِينَ ) أي المتطهرين. وهناك معنى آخر للتطهير فقد روي عن النبي صلى‌الله‌عليه‌وآله‌وسلم أنه قال لأهل قبا : « ماذا تفعلون في طهركم فإن الله قد أحسن عليكم الثناء » . قالوا نغسل أثر الغائط. فقال النبي صلى‌الله‌عليه‌وآله‌وسلم : « أنزل فيكم هذه الآية » (1) . أقول : لأنه كان المتعارف عندهم في ذلك الوقت الاستنجاء بالخرق والأحجار. [109] ثم بيّن سبحانه الفرق بين البناءين ، وبين الفريقين ، وأن أحد البناءين ( 1) بحار الأنوار : ج 21 ص 254. أَ فَمَنْ أَسَّسَ بُنْيانَهُ عَلى تَقْوى مِنَ اللهِ وَرِضْوانٍ خَيْرٌ أَمْ مَنْ أَسَّسَ بُنْيانَهُ عَلى شَفا جُرُفٍ هارٍ فَانْهارَ بِهِ فِي نارِ جَهَنَّمَ وَاللهُ لا يَهْدِي الْقَوْمَ الظَّالِمِينَ (109) راسخ ثابت والآخر هاو منهار ، وأن أحد الفريقين صلد الإيمان قوي العقيدة ، والآخر شاكّ ذو ريبة وتزلزل ( أَ فَمَنْ أَسَّسَ بُنْيانَهُ ) أي بنيان أمره ودينه ومنهجه ( عَلى تَقْوى مِنَ اللهِ ) فهو يتحرّى التقوى في كل أعماله ( وَرِضْوانٍ ) أي رضى الله سبحانه ، فلا يعمل شيئا إلا إذا علم أن فيه رضاه سبحانه ( خَيْرٌ أَمْ مَنْ أَسَّسَ بُنْيانَهُ عَلى شَفا جُرُفٍ هارٍ ) « شفا جرف » نهاية الشيء في المساحة ، و « جرف الوادي » نهايته التي تنجرف بالماء ، و « هار الجرف يهور » ، إذا أشرف على السقوط والهدم ، و « أنهار » بمعنى سقط. فقد شبه سبحانه بنيان المنافق بالبناء الذي بني على شفا جرف جهنم وكان الجرف هائر ( فَانْهارَ ) الجرف ( بِهِ ) أي بالبناء ، أو أنهار البناء بصاحبه ( فِي نارِ جَهَنَّمَ ) فذهبت أتعابه أدراج الرياح. والمعنى : أنه لا يستوي عمل المتقي وعمل المنافق فإن عمل المتقي ثابت راسخ وعمل المنافق هاو منهار ( وَاللهُ لا يَهْدِي الْقَوْمَ الظَّالِمِينَ ) فإن الإنسان الذي صار الظلم عالقا بقلبه ، ينغلق فؤاده ، فلا تدخله أشعة الهداية. والمراد بعدم الهداية : أنه يتركهم وشأنهم ولا يلطف بهم الألطاف الخاصة. [110] ذاك كان مثل بنيانهم ـ من بناء المسجد ـ ثم انتقل سبحانه إلى البناء العام في حياتهم ومناهجهم في الدنيا ، وانتقل إلى تصويره ببناء حسّي يبنى على جرف هار ، فكما أن ذلك البناء ينحرف ويسقط ، كذلك أعمالهم تسقط بهم في جهنم. وهنا مثل آخر لعقيدتهم الكائنة في لا يَزالُ بُنْيانُهُمُ الَّذِي بَنَوْا رِيبَةً فِي قُلُوبِهِمْ إِلاَّ أَنْ تَقَطَّعَ قُلُوبُهُمْ وَاللهُ عَلِيمٌ حَكِيمٌ (110) إِنَّ اللهَ اشْتَرى مِنَ الْمُؤْمِنِينَ أَنْفُسَهُمْ وَأَمْوالَهُمْ بِأَنَّ لَهُمُ الْجَنَّةَ يُقاتِلُونَ فِي سَبِيلِ اللهِ فَيَقْتُلُونَ وَيُقْتَلُونَ قلوبهم والمختلجة في صدورهم ( لا يَزالُ بُنْيانُهُمُ الَّذِي بَنَوْا ) أي ما بنوا عليه حياتهم من النفاق ( رِيبَةً فِي قُلُوبِهِمْ ) سببا للتزلزل والشك في قلوبهم ، فإن الإنسان كيفما بنى حياته وقرّر منهجه ، يكون معتقده وضميره ، فهم مقسّمو القلوب بين المؤمنين والكافرين ( لا إِلى هؤُلاءِ وَلا إِلى هؤُلاءِ )( إِلَّا أَنْ تَقَطَّعَ قُلُوبُهُمْ ) تصير قطعة قطعة ، فتزول الريبة بزوال موضعها ، وإلا فما دام هؤلاء على ذلك البناء والمنهج ، فالريبة لازمة لقلوبهم لا تنفك عنها أبدا ( وَاللهُ عَلِيمٌ ) بنياتهم ( حَكِيمٌ ) فيما يفعله بهم. [111] ثم يحرّض الله المؤمنين على الجهاد مبيّنا الثواب العظيم لمن جاهد قائلا : ( إِنَّ اللهَ اشْتَرى مِنَ الْمُؤْمِنِينَ أَنْفُسَهُمْ وَأَمْوالَهُمْ ) فأنفسهم لله سبحانه ، وأموالهم له تعالى ، لا يحق لهم أن يخلّوا بالنفس أو المال بعد هذه المبايعة التي عقدوها مع الله بقبول الإيمان ، وقد كان في مقابل هذا المبيع ( بِأَنَّ لَهُمُ الْجَنَّةَ ) فالجنة بدل بذل النفس والمال في سبيل الله تعالى. ولا يخفى أن بيع النفس إنما هو لصرفها في مراضيه لسانا وقدما وقلما وسائر ما يتعلق بالبدن ، فليس الأمر خاصا بالجهاد ، ومن أهمّ الأغراض في هذه المعاملة ما بيّنه بقوله : ( يُقاتِلُونَ فِي سَبِيلِ اللهِ ) ولأجل إعلاء كلمته ( فَيَقْتُلُونَ ) الكفار تارة ( وَيُقْتَلُونَ ) يقتلهم وَعْداً عَلَيْهِ حَقًّا فِي التَّوْراةِ وَالْإِنْجِيلِ وَالْقُرْآنِ وَمَنْ أَوْفى بِعَهْدِهِ مِنَ اللهِ فَاسْتَبْشِرُوا بِبَيْعِكُمُ الَّذِي بايَعْتُمْ بِهِ الكفار تارة أخرى ، وكون الجنة لهؤلاء ( وَعْداً عَلَيْهِ ) على الله ( حَقًّا ) و « وعدا » منصوب بالمصدر ، لأن « اشترى » يدل على أنه سبحانه وعد بذلك ، فإن المعاملة تستوجب وعد الطرفين ببذل السلعة ، وبذل المال ( فِي التَّوْراةِ ) لموسى عليه‌السلام كان هذا الوعد ( وَالْإِنْجِيلِ ) لعيسى عليه‌السلام ( وَالْقُرْآنِ ) فإن وعد الجنة لمن باع نفسه وماله في سبيل الله مذكور في هذه الكتب الثلاثة لهؤلاء الأنبياء العظام. ( وَمَنْ أَوْفى بِعَهْدِهِ مِنَ اللهِ ) استفهام في معنى الإنكار ، أي لا أحد أكثر وفاء من الله ، فهو إذا وعد لا يخلف البتّة ، أما غيره فإنه وإن كان لا يخلف بإرادته ، لكنه قد يطرأ ما يضطرّه إلى الخلف ( فَاسْتَبْشِرُوا ) أيها المؤمنون ( بِبَيْعِكُمُ الَّذِي بايَعْتُمْ بِهِ ) الضمير في « به » يرجع إلى « بيعكم » أي : افرحوا بهذه المعاملة ، و « الاستبشار » هو شدة الفرح الذي يظهر أثره في وجه الإنسان ، وأي بيع أحسن من هذا ؟ إنه إعطاء المال لمالكه ثم أخذ العوض منه ، ثم إن النفس في سبيل الفناء ، والمال في سبيل الذهاب ، فما أفضل أن يشتري بهما الإنسان شيئا باقيا دائما. قال الإمام علي عليه‌السلام : وإن كانت الأبدان للموت أنشأت فقتل امرئ بالسيف في الله أفضل (1) ( 1) ديوان الإمام علي عليه‌السلام : ص 106. وَذلِكَ هُوَ الْفَوْزُ الْعَظِيمُ (111) و قيل : و إن كانت الأموال لا بد تنفني فتقديمها لله والدين أجمل ( وَذلِكَ ) البيع ( هُوَ الْفَوْزُ الْعَظِيمُ ) والفلاح الذي لا يقابله فلاح. قال الإمام أمير المؤمنين عليه‌السلام في نهج البلاغة : « إنه ليس لأنفسكم ثمن إلا الجنة فلا تبيعوها إلا بها » (1) . و فيه : « فلا أموال بذلتموها للذي رزقها ولا أنفس خاطرتم بها للذي خلقها » (2) . قال الشاعر : أنفاس عمرك أثمان الجنان فلا تشري بها لهبا في الحشر تشتعل وقد كان الإمام أمير المؤمنين عليه‌السلام وأهل بيته الطاهرين من أفضل مصاديق هذه الآية.` },
            { text: "أَفَمَنْ أَسَّسَ بُنْيَٰنَهُۥ عَلَىٰ تَقْوَىٰ مِنَ ٱللَّهِ وَرِضْوَٰنٍ خَيْرٌ أَم مَّنْ أَسَّسَ بُنْيَٰنَهُۥ عَلَىٰ شَفَا جُرُفٍ هَارٍ فَٱنْهَارَ بِهِۦ فِى نَارِ جَهَنَّمَ وَٱللَّهُ لَا يَهْدِى ٱلْقَوْمَ ٱلظَّٰلِمِينَ", tafsir: `` },
            { text: "لَا يَزَالُ بُنْيَٰنُهُمُ ٱلَّذِى بَنَوْا۟ رِيبَةً فِى قُلُوبِهِمْ إِلَّآ أَن تَقَطَّعَ قُلُوبُهُمْ وَٱللَّهُ عَلِيمٌ حَكِيمٌ", tafsir: `` },
            { text: "إِنَّ ٱللَّهَ ٱشْتَرَىٰ مِنَ ٱلْمُؤْمِنِينَ أَنفُسَهُمْ وَأَمْوَٰلَهُم بِأَنَّ لَهُمُ ٱلْجَنَّةَ يُقَٰتِلُونَ فِى سَبِيلِ ٱللَّهِ فَيَقْتُلُونَ وَيُقْتَلُونَ وَعْدًا عَلَيْهِ حَقًّا فِى ٱلتَّوْرَىٰةِ وَٱلْإِنجِيلِ وَٱلْقُرْءَانِ وَمَنْ أَوْفَىٰ بِعَهْدِهِۦ مِنَ ٱللَّهِ فَٱسْتَبْشِرُوا۟ بِبَيْعِكُمُ ٱلَّذِى بَايَعْتُم بِهِۦ وَذَٰلِكَ هُوَ ٱلْفَوْزُ ٱلْعَظِيمُ", tafsir: `` },
            { text: "ٱلتَّٰٓئِبُونَ ٱلْعَٰبِدُونَ ٱلْحَٰمِدُونَ ٱلسَّٰٓئِحُونَ ٱلرَّٰكِعُونَ ٱلسَّٰجِدُونَ ٱلْـَٔامِرُونَ بِٱلْمَعْرُوفِ وَٱلنَّاهُونَ عَنِ ٱلْمُنكَرِ وَٱلْحَٰفِظُونَ لِحُدُودِ ٱللَّهِ وَبَشِّرِ ٱلْمُؤْمِنِينَ", tafsir: `قام رجل إلى النبي صلى‌الله‌عليه‌وآله‌وسلم فقال : يا نبي الله أرأيتك الرجل يأخذ سيفه فيقاتل حتى يقتل ، إلّا أنه يقترف من هذه المحارم أ شهيد هو ؟ فأنزل الله على رسوله : ( التَّائِبُونَ الْعابِدُونَ .. . ) (3) . ( 1) نهج البلاغة : الكلمات القصار رقم 456. ( 2) نهج البلاغة : خطبة 116. ( 3) التوبة : 112. التَّائِبُونَ الْعابِدُونَ الْحامِدُونَ السَّائِحُونَ أقول : قد وصف سبحانه المؤمنين الذين اشترى أنفسهم وأموالهم مقابل الجنة بهذه الأوصاف فقال : ( التَّائِبُونَ ) أي الراجعون إلى طاعة الله ، من « تاب » إذا رجع. ولا يخفى أن الرجوع والتوبة لا يلازمان العصيان ، ولذا ورد في القرآن : ( لَقَدْ تابَ اللهُ عَلَى النَّبِيِّ ) (1) ، فإن العصيان أشد أفراد البعد عنه سبحانه ، وإلّا فكل نومة وأكلة وتكلّم مع الناس مما يسبب الغفلة عنه سبحانه تحتاج إلى التوبة والأوبة. فلا يقال : كيف وصف الإمام عليه‌السلام ـ وهو معصوم ـ بالتوبة ، بعد ما ذكرتم أن الآية نزلت في شأنه ؟ ثم إن « التائبون » رفع بالقطع ، أي هم التائبون ، كما قال ابن مالك : و اقطع أو اتبع إن يكن معينا بدونها أو بعضها اقطع معلنا ( الْعابِدُونَ ) الذين يعبدون الله وحده ولا يشركون به شيئا ( الْحامِدُونَ ) الذين يحمدون الله سبحانه ( السَّائِحُونَ ) الذين يسيحون في الأرض ، أي يسيرون فيها ، للاعتبار ولطلب العلم كما قال سبحانه : ( فَامْشُوا فِي مَناكِبِها وَكُلُوا مِنْ رِزْقِهِ ) (2) . و ينسب إلى الإمام عليه‌السلام : تغرب عن الأوطان في طلب العلا و سافر ففي الأسفار خمس فوائد وفي بعض التفاسير : أن المراد ب « السائح » الصائم ، لقول ( 1) التوبة : 117. ( 2) الملك : 16. الرَّاكِعُونَ السَّاجِدُونَ الْآمِرُونَ بِالْمَعْرُوفِ وَالنَّاهُونَ عَنِ الْمُنْكَرِ وَالْحافِظُونَ لِحُدُودِ اللهِ وَبَشِّرِ الْمُؤْمِنِينَ (112) النبي صلى‌الله‌عليه‌وآله‌وسلم : « سياحة أمتي الصيام » (1) . ( الرَّاكِعُونَ ) الذين يركعون ، إما مطلقا لاستحباب الركوع تعظيما له سبحانه ، أو المراد الركوع في الصلاة ( السَّاجِدُونَ ) في الصلاة أو مطلقا ( الْآمِرُونَ بِالْمَعْرُوفِ ) وهو كل حسن يستحسنه الشرع أو العقل ( وَالنَّاهُونَ عَنِ الْمُنْكَرِ ) وهو كل قبيح يستقبحه الشرع أو العقل. ولا يخفى أنه بهذا المعنى الذي ذكرنا ، ليس ترك كل معروف منكرا ، فقراءة القرآن مثلا في يوم الجمعة معروف فليس تركها منكرا ، كما أنه ليس ترك كل منكر معروفا فأكل الجبن ـ وهو مكروه ـ منكر فليس ترك أكله معروفا. نعم يتلازم الأمران في الواجب والحرام. ( وَالْحافِظُونَ لِحُدُودِ اللهِ ) أي العاملون بالحدود ، القائمون عليها في جميع أبواب العبادة والمعاملة ، وسائر ما ورد في الشريعة ( وَبَشِّرِ ) يا رسول الله ( الْمُؤْمِنِينَ ) الذين يجمعون هذه الصفات ، بأن لهم كل خير وسعادة. [113] ولما سبق حرمة موالاة الكافرين والمنافقين حتى الصلاة عليهم ، والقيام على قبورهم ، والصلاة في مسجدهم ، بيّن سبحانه حرمة الاستغفار لهم أحياء كانوا أم أمواتا ، فإن الاستغفار أي طلب غفران الله لعدو الله لا يصح ، إذ هو غير قابل للمغفرة. وذكر بعض المفسرين : أن بعض المسلمين قالوا للنبي صلى‌الله‌عليه‌وآله‌وسلم : هل ( 1) مستدرك الوسائل : ج 8 ص 115. ما كانَ لِلنَّبِيِّ وَالَّذِينَ آمَنُوا أَنْ يَسْتَغْفِرُوا لِلْمُشْرِكِينَ وَلَوْ كانُوا أُولِي قُرْبى مِنْ بَعْدِ ما تَبَيَّنَ لَهُمْ أَنَّهُمْ أَصْحابُ الْجَحِيمِ (113) لنا أن نستغفر لآبائنا الذين ماتوا في الكفر. فنزلت هذه الآية (1) . لكن الظاهر أن ذلك غير طلب الغفران للكافر الحي ، بمعنى طلب هدايته من الله ليستحق الغفران ، فإذا قال : اللهم اغفر له ، عنى : اهده ، ليكون قابلا للمغفرة. فقد ورد عن الإمام الصادق عليه‌السلام : « أن إبراهيم عليه‌السلام وعده أبوه آزر أن يسلم ، فاستغفر له ، فلما تبيّن له أنه عدو لله ، تبرأ منه » (2) . كما أن الظاهر أن الخيرات للأقارب الكفار الذين ماتوا لا بأس بها ، فإن ذلك موجب لتخفيف العذاب ، وهو غير الاستغفار بطلب المغفرة ، وقد ورد بذلك أحاديث كثيرة. ( ما كانَ لِلنَّبِيِّ وَالَّذِينَ آمَنُوا أَنْ يَسْتَغْفِرُوا لِلْمُشْرِكِينَ ) بأن يطلبوا من الله الغفران لمن أشرك بالله. ومن المعلوم أنه لا خصوصية للمشرك ، بل ذلك لا يجوز بالنسبة إلى كل كافر ( وَلَوْ كانُوا أُولِي قُرْبى ) أي كان المستغفر لأجله صاحب قرابة للمؤمن المستغفر ( مِنْ بَعْدِ ما تَبَيَّنَ لَهُمْ أَنَّهُمْ أَصْحابُ الْجَحِيمِ ) أي من بعد أن علم المؤمنون أن أولئك المشركين هم أصحاب النار. [114] ولما كان هنا موضع سؤال وهو : كيف يحرم الاستغفار للكافر مع أن إبراهيم عليه‌السلام استغفر لأبيه ـ وهو عمّه ، وإنما يسمي العرب العم بالأب ( 1) راجع مجمع البيان : ج 5 ص 132. ( 2) بحار الأنوار : ج 71 ص 47. وَما كانَ اسْتِغْفارُ إِبْراهِيمَ لِأَبِيهِ إِلاَّ عَنْ مَوْعِدَةٍ وَعَدَها إِيَّاهُ فَلَمَّا تَبَيَّنَ لَهُ أَنَّهُ عَدُوٌّ لِلَّهِ تَبَرَّأَ مِنْهُ إِنَّ إِبْراهِيمَ لَأَوَّاهٌ حَلِيمٌ (114) تعظيما ـ والحال أن آزر كان كافرا ؟ ورد قوله سبحانه : ( وَما كانَ اسْتِغْفارُ إِبْراهِيمَ لِأَبِيهِ إِلَّا عَنْ مَوْعِدَةٍ وَعَدَها إِيَّاهُ ) أي وعد الأب إبراهيم بأن يؤمن ( فَلَمَّا تَبَيَّنَ لَهُ ) أي لإبراهيم ( أَنَّهُ ) أي أباه ( عَدُوٌّ لِلَّهِ ) وأنه لا يؤمن ( تَبَرَّأَ مِنْهُ ) وترك الاستغفار له. وقد تقدم الحديث عن الإمام الصادق عليه‌السلام بذلك. و روي : أن إبراهيم قال لأبيه : إن لم تعبد الأصنام استغفرت لك ، فلما لم يدع الأصنام تبرأ منه (1) . ومن المعلوم أنه لا منافاة بين الأمرين. وعلى أي حال فعمل إبراهيم لا ينافي عموم « ما كان للنبي والذين آمنوا » . ( إِنَّ إِبْراهِيمَ لَأَوَّاهٌ ) أي دعّاء ، كثير الدعاء والبكاء ، وأصل « الأواه » مبالغة ـ على وزن ضرّاب ـ من « التأوّه » بمعنى : التوجّع والتحزّن ( حَلِيمٌ ) يحلم عن الناس حتى عن الكفار ، لعلّه يدخلهم في حظيرة الإيمان بحلمه. وأما مناسبة « أواه » للمقام فظاهرة ، إذ مقتضى كثرة الدعاء أن يدعو حتى للكافر الذي يحتمل أن يؤمن. ومن المفسرين من أقحم في الآية ما اختلقته الأهواء الأموية من كفر أبي طالب ، ولقد كان أبو طالب عليه‌السلام من أشد المؤمنين بالله ورسوله حتى أنه قال عليه‌السلام : ( 1) بحار الأنوار : ج 11 ص 77. وَما كانَ اللهُ لِيُضِلَّ قَوْماً بَعْدَ إِذْ هَداهُمْ حَتَّى يُبَيِّنَ لَهُمْ ما يَتَّقُونَ إِنَّ اللهَ بِكُلِّ شَيْءٍ عَلِيمٌ (115) و لقد علمت بأنّ دين محمد من خير أديان البرية دينا وحتى أنه حين مات نزل جبرئيل قائلا للرسول : « مات ناصرك فاخرج من مكة » (1) . وسمى رسول الله صلى‌الله‌عليه‌وآله‌وسلم عام وفاته ووفاة خديجة « عام الحزن » (2) . وإنما الكلام هنا أن ذلك لا يرتبط بالتفسير ، وإنما يرتبط بالتعصّب ، وكم أخفى التعصب الحق. [115] إن ما يستفاد من الآيات السابقة من انقطاع صلة المؤمنين عن الكافرين ، يوجب التساؤل ، وهو : ماذا يعملون بما سلف من الأموات الكافرين ، فقد كانت الوشائح بين المؤمنين والكافرين قوية وكانوا يحسنون إليهم أحياء ويستغفرون لهم أمواتا ؟ ولذا ورد : ( وَما كانَ اللهُ لِيُضِلَّ قَوْماً ) بأن يصرفهم عن طريق الهدى ويحكم بضلالهم ، بأعمال عملوها قبل النهي والتحريم ( بَعْدَ إِذْ هَداهُمْ ) إلى الإيمان ( حَتَّى يُبَيِّنَ لَهُمْ ما يَتَّقُونَ ) من أوامره ونواهيه ، فإذا بيّن لهم ثم خالفوا ، استحقوا العقاب والحكم بالضلال ، وهكذا قوله سبحانه : ( ما كُنَّا مُعَذِّبِينَ حَتَّى نَبْعَثَ رَسُولاً ) (3) ، ( إِنَّ اللهَ بِكُلِّ شَيْءٍ عَلِيمٌ ) يعلم من عمل قبل التحريم ومن عمل بعد التحريم ، فيجزي كلّا حسب عمله. وفي بعض التفاسير : إن سبب نزول هذه الآية ، أنه مات قوم من المسلمين على الإسلام قبل أن تنزل الفرائض ، فقال المسلمون : يا ( 1) إيمان أبي طالب : ص 259. ( 2) بحار الأنوار : ج 19 ص 25. ( 3) الإسراء : 16. إِنَّ اللهَ لَهُ مُلْكُ السَّماواتِ وَالْأَرْضِ يُحْيِي وَيُمِيتُ وَما لَكُمْ مِنْ دُونِ اللهِ مِنْ وَلِيٍّ وَلا نَصِيرٍ (116) رسول الله إخواننا المؤمنون الذين ماتوا قبل الفرائض ما هي منزلتهم ؟ فنزلت : ( وَما كانَ اللهُ لِيُضِلَّ .. ) (1) .` },
            { text: "مَا كَانَ لِلنَّبِىِّ وَٱلَّذِينَ ءَامَنُوٓا۟ أَن يَسْتَغْفِرُوا۟ لِلْمُشْرِكِينَ وَلَوْ كَانُوٓا۟ أُو۟لِى قُرْبَىٰ مِنۢ بَعْدِ مَا تَبَيَّنَ لَهُمْ أَنَّهُمْ أَصْحَٰبُ ٱلْجَحِيمِ", tafsir: `` },
            { text: "وَمَا كَانَ ٱسْتِغْفَارُ إِبْرَٰهِيمَ لِأَبِيهِ إِلَّا عَن مَّوْعِدَةٍ وَعَدَهَآ إِيَّاهُ فَلَمَّا تَبَيَّنَ لَهُۥٓ أَنَّهُۥ عَدُوٌّ لِّلَّهِ تَبَرَّأَ مِنْهُ إِنَّ إِبْرَٰهِيمَ لَأَوَّٰهٌ حَلِيمٌ", tafsir: `` },
            { text: "وَمَا كَانَ ٱللَّهُ لِيُضِلَّ قَوْمًۢا بَعْدَ إِذْ هَدَىٰهُمْ حَتَّىٰ يُبَيِّنَ لَهُم مَّا يَتَّقُونَ إِنَّ ٱللَّهَ بِكُلِّ شَىْءٍ عَلِيمٌ", tafsir: `` },
            { text: "إِنَّ ٱللَّهَ لَهُۥ مُلْكُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ يُحْىِۦ وَيُمِيتُ وَمَا لَكُم مِّن دُونِ ٱللَّهِ مِن وَلِىٍّ وَلَا نَصِيرٍ", tafsir: `المؤمن الذي يبيع نفسه لله قد ربح كل شيء ، وإن قطع صلته بأقرب الناس إليه حتى في الاستغفار ف ( اللهَ لَهُ مُلْكُ السَّماواتِ وَالْأَرْضِ ) لا مالك فيهما سواه ( يُحْيِي ) الجماد ( وَيُمِيتُ ) الأحياء ، فالأرض الميتة يجعل منها نباتا وإنسانا وحيوانا ، كما أنه يرد هذه الأحياء إلى الأرض فيجعلها جمادا ( وَما لَكُمْ ) أيها المسلمون ( مِنْ دُونِ اللهِ ) سواه ( مِنْ وَلِيٍّ وَلا نَصِيرٍ ) فلا يتولّى شؤونكم ولا ينصركم غيره ، فمن له الملك ، وبيده الحياة والموت ، ويتولّى وينصر أحق بأن يربط الإنسان صلته به دون سواه ، ويترك غيره لأجله ، ولو كان أقرب قريب إليه. [117] ثم ذكر سبحانه قصة جماعة تخلفوا عن الرسول صلى‌الله‌عليه‌وآله‌وسلم ثم لحقوا به ، أو تابوا بعد ذلك. فقد ذكر الرواة أن عبد الله بن خيثمة تخلف عن غزوة تبوك إلى أن مضى من مسير رسول الله صلى‌الله‌عليه‌وآله‌وسلم عشرة أيام ، ثم دخل يوما على امرأتين له في يوم حار في عريشين لهما قد رتبتاهما وبرّدتا الماء وهيأتا له الطعام ، فقام على العريشين ثم قال : سبحان الله ، رسول الله قد غفر الله له ما تقدم من ذنبه وما تأخر ، في الفتح والريح والقرّ يحمل سلاحه على عاتقه ، وأبو خيثمة في ظلال باردة وطعام ( 1) بحار الأنوار : ج 22 ص 42. مهيأ وامرأتين حسناوين ، ما هذا بالنصف. ثم قال : والله لا أكلم واحدة منكما كلمة ولا أدخل عريشا حتى ألحق بالنبي صلى‌الله‌عليه‌وآله‌وسلم . فأخ ناضحه واشتد عليه وتزوّد وارتحل وامرأتاه تكلمانه ولا يكلمهما. ثم سار حتى إذا دنا من تبوك قال الناس : هذا راكب على الطريق. فقال النبي صلى‌الله‌عليه‌وآله‌وسلم : كن يا أبا خيثمة أولى لك ، فلما دنا قال الناس : هذا أبو خيثمة يا رسول الله ، فأناخ راحلته وسلّم على رسول الله صلى‌الله‌عليه‌وآله‌وسلم فقال صلى‌الله‌عليه‌وآله‌وسلم : أولى لك. فحدثه الحديث ، فقال له خيرا ودعا له. وهو الذي زاغ قلبه للمقام ثم ثبّته الله (1) . و نقل الرواة : أن ممن لقي العسر في هذه السفرة أبا ذر الغفاري رحمه‌الله فقد كان جمله أعجف تخلف به في الطريق حتى أنه لحق بالرسول صلى‌الله‌عليه‌وآله‌وسلم بعد ثلاثة أيام ووقف عليه جمله في بعض الطريق فتركه وحمل ثيابه على ظهره ، فلما ارتفع النهار نظر المسلمون إلى شخص مقبل ، فقال رسول الله صلى‌الله‌عليه‌وآله‌وسلم : كن أبا ذر فقالوا : هو أبو ذر. فقال رسول الله صلى‌الله‌عليه‌وآله‌وسلم : أدركوه بالماء فإنه عطشان. فأدركوه بالماء ، ووافى أبو ذر رسول الله صلى‌الله‌عليه‌وآله‌وسلم ومعه إداوة فيها ماء فقال رسول الله صلى‌الله‌عليه‌وآله‌وسلم : يا أبا ذر معك ماء وعطشت ؟ فقال : نعم يا رسول الله بأبي أنت وأمي انتهيت إلى صخرة وعليها ماء السماء فذقته فإذا هو عذب بارد ، فقلت : لا أشربه حتى يشربه حبيبي رسول الله صلى‌الله‌عليه‌وآله‌وسلم . فقال رسول الله صلى‌الله‌عليه‌وآله‌وسلم : « يا أبا ذر رحمك الله تعيش وحدك ، وتموت وحدك ، وتدخل الجنة وحدك ، يسعد بك قوم من العراق يتولون ( 1) بحار الأنوار : ج 21 ص 202. لَقَد تَّابَ الله عَلَى النَّبِيِّ وَالْمُهَاجِرِينَ وَالأَنصَارِ الَّذِينَ اتَّبَعُوهُ فِي سَاعَةِ الْعُسْرَةِ مِن بَعْدِ مَا كَادَ يَزِيغُ قُلُوبُ فَرِيقٍ مِّنْهُمْ ثُمَّ تَابَ عَلَيْهِمْ إِنَّهُ غسلك وتجهيزك ودفنك » (1) . ( لَقَدْ تابَ اللهُ ) أي تحنّن ولطف ، فإن « تاب » لغة بمعنى : غفر ، وبمعنى : رجع بفضله ( عَلَى النَّبِيِ ) وما ورد في بعض الأحاديث « بالنبي » إنما أريد به نفي كون معنى التوبة بالنسبة إلى النبي صادرة عن عصيان ( وَالْمُهاجِرِينَ وَالْأَنْصارِ ) فهم بين من يستحق المغفرة لمعصية صدرت عنه ، وبين من يستحقها تفضّلا ( الَّذِينَ اتَّبَعُوهُ ) أي اتبعوا النبي ( فِي ساعَةِ الْعُسْرَةِ ) أي وقت صعوبة الأمر ، وذلك في غزوة تبوك ، فقد كانوا في صعوبة من جهة المركب ، ومن جهة الماء والزاد ، ومن جهة الحر ، ومن جهة التعب للسفر الطويل ، ومن جهة الخوف من الأعداء ، فقد كان العشرة منهم يتراوحون على بعير وزادهم الشعير المسوس ، والتمر المدود ، والإهالة السنخة « وهو ما أذيب من الشحم المتغير الريح » ، وكانوا يمصون تمرة واحدة ، وهم جماعة كثيرة ، يخرجها هذا من فيه فيمصها الآخر وهكذا حتى لا يبقى إلا النواة ( مِنْ بَعْدِ ما كادَ يَزِيغُ ) يميل وينحرف ( قُلُوبُ فَرِيقٍ مِنْهُمْ ) عن الجهاد ، فأرادوا البقاء في المدينة أو بقوا ثم لحقوا بالرسول كأبي خيثمة. ( ثُمَّ تابَ ) الله ( عَلَيْهِمْ ) من بعد ذلك الزيغ والانحراف ( إِنَّهُ ) ( 1) بحار الأنوار : ج 22 ص 429. بِهِمْ رَؤُوفٌ رَّحِيمٌ (117) وَعَلَى الثَّلاَثَةِ الَّذِينَ خُلِّفُواْ حَتَّى إِذَا ضَاقَتْ عَلَيْهِمُ الأَرْضُ بِمَا رَحُبَتْ وَضَاقَتْ عَلَيْهِمْ أَنفُسُهُمْ وَظَنُّواْ أَن لاَّ مَلْجَأَ مِنَ اللّهِ إِلاَّ إِلَيْهِ تعالى ( بِهِمْ رَؤُفٌ رَحِيمٌ ) فلا يؤاخذهم بما كسبت قلوبهم ، وبما عملوه من الكسل والمطل.` },
            { text: "لَّقَد تَّابَ ٱللَّهُ عَلَى ٱلنَّبِىِّ وَٱلْمُهَٰجِرِينَ وَٱلْأَنصَارِ ٱلَّذِينَ ٱتَّبَعُوهُ فِى سَاعَةِ ٱلْعُسْرَةِ مِنۢ بَعْدِ مَا كَادَ يَزِيغُ قُلُوبُ فَرِيقٍ مِّنْهُمْ ثُمَّ تَابَ عَلَيْهِمْ إِنَّهُۥ بِهِمْ رَءُوفٌ رَّحِيمٌ", tafsir: `` },
            { text: "وَعَلَى ٱلثَّلَٰثَةِ ٱلَّذِينَ خُلِّفُوا۟ حَتَّىٰٓ إِذَا ضَاقَتْ عَلَيْهِمُ ٱلْأَرْضُ بِمَا رَحُبَتْ وَضَاقَتْ عَلَيْهِمْ أَنفُسُهُمْ وَظَنُّوٓا۟ أَن لَّا مَلْجَأَ مِنَ ٱللَّهِ إِلَّآ إِلَيْهِ ثُمَّ تَابَ عَلَيْهِمْ لِيَتُوبُوٓا۟ إِنَّ ٱللَّهَ هُوَ ٱلتَّوَّابُ ٱلرَّحِيمُ", tafsir: `لقد تاب الله ( عَلَى الثَّلاثَةِ ) أشخاص ( الَّذِينَ خُلِّفُوا ) عن غزوة تبوك ، كأن الشيطان خلّفهم وهم من تقدم ذكرهم مفصّلا في قوله سبحانه : ( وَآخَرُونَ مُرْجَوْنَ لِأَمْرِ اللهِ )( حَتَّى إِذا ضاقَتْ عَلَيْهِمُ الْأَرْضُ بِما رَحُبَتْ ) « ما » مصدرية ، أي : مع رحبها ـ بالضم ـ وسعتها ، ضاقت عليهم لأن الناس قاطعوهم بأمر الرسول صلى‌الله‌عليه‌وآله‌وسلم والإنسان إذا قاطعه الأصدقاء تضيق نفسه ، حتى يظن أن الأرض ضيقة لا مجال له فيها ( وَضاقَتْ عَلَيْهِمْ أَنْفُسُهُمْ ) كأنهم لم يجدوا لأنفسهم موضعا يخفونها فيه ، وهذا كناية عن شدة غمّهم. ولعل وجه ( ضاقَتْ عَلَيْهِمْ أَنْفُسُهُمْ ) أن الإنسان إذا غمّ غمّا شديدا تسخن شرايينه وأعضاؤه ، فلا يكفي النّفس المجذوب لتبريدها ، فيحسّ بأن نفسه قد ضاقت ، لأنها لم يصل إليها الهواء الكافي. ( وَظَنُّوا أَنْ لا مَلْجَأَ مِنَ اللهِ إِلَّا إِلَيْهِ ) أنه لا موضع للفرار من سخط الله سبحانه إلا إليه نفسه تعالى ، فإنه سبحانه قد أحاط بأقطار الأرض وآفاق السماء فكيف يمكن الفرار منه إلا أن يتوجه الإنسان إليه بالتوبة والاستغفار ، ولعل الإتيان بلفظة « الظن » هنا لإفادة الحالة النفسية للإنسان المجرم حيث أنه لا يفكر في الملاجئ الممكنة ، فهو يتردّد بين هذا أو ذاك ، وإن ترجّح في نفسه الملجأ الحقيقي وهو الله تعالى. ثُمَّ تَابَ عَلَيْهِمْ لِيَتُوبُواْ إِنَّ اللّهَ هُوَ التَّوَّابُ الرَّحِيمُ (118) ( ثُمَّ تابَ عَلَيْهِمْ ) أي تاب الله عليهم ورجع إليهم بعد أن أعرض عنهم بقبوله توبتهم في التخلف عن تبوك ( لِيَتُوبُوا ) أي يرجعوا إلى حالتهم الأولى قبل المعصية ، فيكون لهم ما للمسلمين لا يقاطعون ولا ينبذون ( إِنَّ اللهَ هُوَ التَّوَّابُ ) مبالغة في « التائب » ، فإنه سبحانه كثير الرجوع إلى عباده إن رجعوا إليه ، وليس ككبرياء الناس حيث أنه إن قطعوا عن أحد لا يعودون إليه ، ولو عادوا لم يتكرر ذلك منهم مرات ومرات ، فالإنسان مهما عصى وتاب ، قبل الله توبته إذا كانت توبة نصوحا ، وإن نقض التوبة قبل ذلك ألف مرة ( الرَّحِيمُ ) يرحم العباد ويتفضل عليهم بلطفه ، فليست توبة مجردة ، وإنما مع التفضيل والتكرّم. لقد كان هؤلاء الثلاثة المتخلفون ـ كعب ومرارة وهلال ـ أرجئوا ، في الآية السابقة ( وَآخَرُونَ مُرْجَوْنَ لِأَمْرِ اللهِ ) ثم تاب الله عليهم هنا ، وكان في كلا الأمرين أبلغ حكمة ، وخير تأديب وموعظة. وهنا كلمة لا بد من بيانها وهي أن الناظر في الآيات يرى أن بعض العاصين كان الله والرسول يعفوان عنهم كهؤلاء ، وبعضهم يبقون موضع السخط والغضب ك « ثعلبة » الذي تقدمت أحواله ، إن هذا يكشف عن الفرق بين العصاة ، فمن أصلح منهم وطهر قلبه استحق العفو والغفران ، أما من أبدى التوبة وقلبه ملوّث بالذنوب والنفاق ، فلم يكن تنفعه الندامة ، ولذا كان مطرودا من رحمة الله ، وقد بيّن سبحانه أن قبول التوبة مشروط بالطهارة والنقاء ، كما في قوله تعالى : ( ثُمَّ اتَّقَوْا وَأَحْسَنُوا ) (1) ، وغيرها من الآيات. ( 1) المائدة : 94. يا أَيُّهَا الَّذِينَ آمَنُوا اتَّقُوا اللهَ وَكُونُوا مَعَ الصَّادِقِينَ (119) ما كانَ لِأَهْلِ الْمَدِينَةِ وَمَنْ حَوْلَهُمْ مِنَ الْأَعْرابِ أَنْ يَتَخَلَّفُوا عَنْ رَسُولِ اللهِ وَلا يَرْغَبُوا بِأَنْفُسِهِمْ عَنْ نَفْسِهِ [119] وبمناسبة توبة هؤلاء وصفاء باطنهم في التوبة ، وصدقهم في الرجوع إلى الحق ، يأتي السياق ليبيّن وجوب كون الإنسان متقيا منضما إلى جماعة الصادقين ، لينال الخير والغفران ( يا أَيُّهَا الَّذِينَ آمَنُوا اتَّقُوا اللهَ ) اجتنبوا معاصيه وخذوا بأوامره ( وَكُونُوا مَعَ الصَّادِقِينَ ) و « المعية » هنا تفيد المعية الانضمامية ، والمعية العملية ، بأن يصدق الإنسان ، وينضم مع الزمرة الصادقة ، لينال كل خير وفضل. وقد ورد في أحاديث كثيرة : أن المراد بهم أمير المؤمنين وآله الطاهرين (1) ، وهذا من باب أظهر المصاديق كما لا يخفى. [120] ثم يأتي البيان العام للمسلمين بوجوب اتباع الرسول في كل أمر وعدم التخلّف عنه في غزو أو غيره ( ما كانَ لِأَهْلِ الْمَدِينَةِ ) إنه خبر في معنى النهي ، أي : لا يجوز للمسلمين من أهل المدينة ( وَمَنْ حَوْلَهُمْ مِنَ الْأَعْرابِ ) أهل البدو ، وتخصيص هؤلاء بالذكر ليس لأجل خصوصية فيهما دون سائر المسلمين ، وإنما لأجل كونهما محل أوامر الرسول صلى‌الله‌عليه‌وآله‌وسلم غالبا ، في الجهاد ونحوه ، وإلا فالمسلمون كلهم كذلك ( أَنْ يَتَخَلَّفُوا عَنْ رَسُولِ اللهِ ) في غزوة أو سفرة أو سائر ما يريده منهم ويعمله صلى‌الله‌عليه‌وآله‌وسلم ، ( وَلا ) لهم أن ( يَرْغَبُوا بِأَنْفُسِهِمْ عَنْ نَفْسِهِ ) الكريمة بأن يطلبوا لأنفسهم من الخير والراحة دون نفس الرسول صلى‌الله‌عليه‌وآله‌وسلم ، بأن يؤثروا ( 1) تفسير فرات الكوفي : ص 174. ذلِكَ بِأَنَّهُمْ لا يُصِيبُهُمْ ظَمَأٌ وَلا نَصَبٌ وَلا مَخْمَصَةٌ فِي سَبِيلِ اللهِ وَلا يَطَؤُنَ مَوْطِئاً يَغِيظُ الْكُفَّارَ وَلا يَنالُونَ مِنْ عَدُوٍّ نَيْلاً إِلاَّ كُتِبَ لَهُمْ بِهِ عَمَلٌ صالِحٌ إِنَّ اللهَ لا يُضِيعُ أَجْرَ الْمُحْسِنِينَ (120) أنفسهم على نفسه فإذا أراد الجهاد تركوه يقاسي الحر والبرد ، وهم في مساكنهم هادئون آمنون. يقال : « رغبت بنفسي عن هذا الأمر » أي ترفعت بها عنه. ( ذلِكَ ) النهي لهم والزجر عن التخلف ، ليس بلا عوض ولا مقابل ، وإنما لهم بكل حركة وسكون وتعب أجر وثواب بسبب أنهم ( لا يُصِيبُهُمْ ) في سفرهم ( ظَمَأٌ ) عطش ( وَلا نَصَبٌ ) تعب في أبدانهم ( وَلا مَخْمَصَةٌ ) بمعنى المجاعة ، وأصله ضمور البطن للمجاعة ، يقال : « رجل خميص البطن » ، أي ضامرها من الجوع ، والمعنى : لا يصيبهم جوع ( فِي سَبِيلِ اللهِ ) ولإعلاء كلمته ( وَلا يَطَؤُنَ مَوْطِئاً يَغِيظُ الْكُفَّارَ ) أي لا يضعون أقدامهم موضعا يسبب غيظ الكفار ، والمراد : إما وطي أراضي الأعداء ، فإنهم يغيظون إذا رأوا واحدا يطأ محلّهم ، أو الذهاب مطلقا ، فإن الكفار يغيظون بسير المسلمين إليهم لإرادة الغزو. ( وَلا يَنالُونَ مِنْ عَدُوٍّ نَيْلاً ) لا يصيبون من الكفار أمرا ، من قتل أو جراحة أو مال أو سبي أو ما أشبه ( إِلَّا كُتِبَ لَهُمْ ) لهؤلاء المسلمين المجاهدين ( بِهِ ) بسبب ذلك العمل ( عَمَلٌ صالِحٌ ) وطاعة مقبولة ( إِنَّ اللهَ لا يُضِيعُ أَجْرَ الْمُحْسِنِينَ ) الذين أحسنوا وعملوا الأعمال الحسنة. وَلا يُنْفِقُونَ نَفَقَةً صَغِيرَةً وَلا كَبِيرَةً وَلا يَقْطَعُونَ وادِياً إِلاَّ كُتِبَ لَهُمْ لِيَجْزِيَهُمُ اللهُ أَحْسَنَ ما كانُوا يَعْمَلُونَ (121) وَما كانَ الْمُؤْمِنُونَ لِيَنْفِرُوا كَافَّةً` },
            { text: "يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ ٱتَّقُوا۟ ٱللَّهَ وَكُونُوا۟ مَعَ ٱلصَّٰدِقِينَ", tafsir: `` },
            { text: "مَا كَانَ لِأَهْلِ ٱلْمَدِينَةِ وَمَنْ حَوْلَهُم مِّنَ ٱلْأَعْرَابِ أَن يَتَخَلَّفُوا۟ عَن رَّسُولِ ٱللَّهِ وَلَا يَرْغَبُوا۟ بِأَنفُسِهِمْ عَن نَّفْسِهِۦ ذَٰلِكَ بِأَنَّهُمْ لَا يُصِيبُهُمْ ظَمَأٌ وَلَا نَصَبٌ وَلَا مَخْمَصَةٌ فِى سَبِيلِ ٱللَّهِ وَلَا يَطَـُٔونَ مَوْطِئًا يَغِيظُ ٱلْكُفَّارَ وَلَا يَنَالُونَ مِنْ عَدُوٍّ نَّيْلًا إِلَّا كُتِبَ لَهُم بِهِۦ عَمَلٌ صَٰلِحٌ إِنَّ ٱللَّهَ لَا يُضِيعُ أَجْرَ ٱلْمُحْسِنِينَ", tafsir: `` },
            { text: "وَلَا يُنفِقُونَ نَفَقَةً صَغِيرَةً وَلَا كَبِيرَةً وَلَا يَقْطَعُونَ وَادِيًا إِلَّا كُتِبَ لَهُمْ لِيَجْزِيَهُمُ ٱللَّهُ أَحْسَنَ مَا كَانُوا۟ يَعْمَلُونَ", tafsir: `هؤلاء المسلمون ، في الجهاد ( نَفَقَةً صَغِيرَةً وَلا كَبِيرَةً ) أي قليلة أو كثيرة ( وَلا يَقْطَعُونَ وادِياً ) أي لا يجتازون أرضا في مسيرهم إلى الكفار للجهاد ( إِلَّا كُتِبَ لَهُمْ ) ذلك ليثابوا عليه ( لِيَجْزِيَهُمُ اللهُ ) أي يكتب ذلك للجزاء ب ( أَحْسَنَ ما كانُوا يَعْمَلُونَ ) جزاء أحسن أعمالهم ، أو أحسن جزاء أعمالهم. وعلى الأول : فالسكوت عن سائر الأعمال ليس لعدم الجزاء وإنما لوضوح أن من يجزي على الأحسن يجزي على غيره. وعلى الثاني : يكون المعنى أنه سبحانه يجازيهم بجزاء هو أحسن من عملهم ، فلو استحق عملهم جزاء ألف دينار ، أعطاهم ألفين.` },
            { text: "وَمَا كَانَ ٱلْمُؤْمِنُونَ لِيَنفِرُوا۟ كَآفَّةً فَلَوْلَا نَفَرَ مِن كُلِّ فِرْقَةٍ مِّنْهُمْ طَآئِفَةٌ لِّيَتَفَقَّهُوا۟ فِى ٱلدِّينِ وَلِيُنذِرُوا۟ قَوْمَهُمْ إِذَا رَجَعُوٓا۟ إِلَيْهِمْ لَعَلَّهُمْ يَحْذَرُونَ", tafsir: `هذا نفي معناه النهي ، أي : فَلَوْ لا نَفَرَ مِنْ كُلِّ فِرْقَةٍ مِنْهُمْ طائِفَةٌ لِيَتَفَقَّهُوا فِي الدِّينِ وَلِيُنْذِرُوا قَوْمَهُمْ إِذا رَجَعُوا إِلَيْهِمْ لَعَلَّهُمْ يَحْذَرُونَ (122) ليس للمؤمنين أن ينفروا ويخرجوا إلى الجهاد بأجمعهم ويتركوا النبي صلى‌الله‌عليه‌وآله‌وسلم وحيدا ( فَلَوْ لا ) تحضيض وحث ، بمعنى : أن اللازم ذهاب بعض وبقاء بعض ( نَفَرَ ) وخرج إلى الجهاد ( مِنْ كُلِّ فِرْقَةٍ مِنْهُمْ ) من كل قبيلة ونحوها ( طائِفَةٌ ) جماعة ، ويبقى من كل فرقة جماعة آخرون ( لِيَتَفَقَّهُوا ) أي ليتفقه هؤلاء الباقون ـ المفهوم من قوله : ( نَفَرَ مِنْ كُلِّ فِرْقَةٍ مِنْهُمْ طائِفَةٌ ) ـ ( فِي الدِّينِ ) يبقون خدمة للنبي صلى‌الله‌عليه‌وآله‌وسلم ليتعلموا أحكام الإسلام التي تنزل على النبي صلى‌الله‌عليه‌وآله‌وسلم تدريجا ( وَلِيُنْذِرُوا قَوْمَهُمْ ) ينذر الباقون قومهم النافرين ( إِذا رَجَعُوا ) رجع النافرون ( إِلَيْهِمْ ) أي إلى الباقين ( لَعَلَّهُمْ يَحْذَرُونَ ) أي يحذر النافرون عما أنذروا به. فلنفرض أن زيدا ذهب إلى الجهاد ، وبقي عمرو وتعلم من النبي صلى‌الله‌عليه‌وآله‌وسلم حرمة الاستمناء ـ مدة غياب زيد ـ فإذا رجع زيد حذره عمرو عن الاستمناء حتى يترك وينقلع. ولو كان المعنى على هذا السياق المذكور لكان فهم وجوب الذهاب إلى مراكز العلم لتحصيله ، بالفحوى ، لأن المقصود من البقاء عند النبي صلى‌الله‌عليه‌وآله‌وسلم ليس إلا تعلم الحكمة وإفادتها للغائب ، وكذلك من يسافر في طلب العلم ثم ينذر أهله إذا رجع إليهم. روي عن الإمام الباقر عليه‌السلام أنه قال : « كان هذا حين كثر الناس فأمرهم الله أن ينفر منهم طائفة وتقيم طائفة للتفقه ، وأن يكون الغزو نوبا » (1) . ولا ينافيه ما ورد عن الإمام الصادق ـ لأن الظاهر إرادة ( 1) بحار الأنوار : ج 19 ص 157. يا أَيُّهَا الَّذِينَ آمَنُوا قاتِلُوا الَّذِينَ يَلُونَكُمْ مِنَ الْكُفَّارِ وَلْيَجِدُوا فِيكُمْ غِلْظَةً الفحوى ـ في تفسير الآية ، « فأمرهم أن ينفروا إلى رسول الله ويختلفوا إليه ، فيتعلموا ثم يرجعوا إلى قومهم فيعلموهم .. » (1) . ثم إنه لو قلنا : إن الآية مستقلة برأسها لا ترتبط بما قبلها ، يكون المعنى : أن اللازم على كل طائفة من كل فرقة من المسلمين المنتشرين هنا وهناك أن يذهبوا إلى طلب العلم في مراكزه ثم ينذروا قومهم إذا رجعوا إليهم حتى يحذروا عن ترك الواجبات وإتيان المحرمات. وتكون المناسبة بينها وبين الآيات السابقة بيان أن النفر واجب في مقامين : في مقام الجهاد وفي مقام العلم. ولا يخفى أن الآية تشمل التفقه بنحو الاجتهاد ، وبنحو أخذ الرواية ، ونحو بيان المسائل بعد أخذها عن المجتهد ، فهي أعم من الاجتهاد والوعظ ونشر المسائل. [123] وإلحاقا بما تقدم من أمر الجهاد ، يأتي السياق ليبيّن خطة الإسلام في جهاد الكفار ( يا أَيُّهَا الَّذِينَ آمَنُوا قاتِلُوا الَّذِينَ يَلُونَكُمْ ) من « ولي يلي » إذا قرب ، أي : يقربونكم ـ في الأرض ـ ( مِنَ الْكُفَّارِ ) فقاتلوا الأدنى فالأدنى ، وذلك لتتصل أرض الإسلام بعضها ببعض ولا تحدث بينها فجوة يتّخذها العدو مرصدا وقاعدة لمحاربتكم. وقد دلّ الدليل على جواز مقاتلة الأبعد إذا كان المسلمون في أمن من الأقرب لمهادنة أو معاهدة أو ما أشبه ( وَلْيَجِدُوا ) أي يجد الكفار ( فِيكُمْ غِلْظَةً ) وخشونة ، فإن ذلك مما يسبب انهيار معنويات العدو ، لكن ليست « الغلظة » بالمثلة ونحوها فقد حرّم الإسلام ذلك كما منع عن قتل المرأة ( 1) وسائل الشيعة : ج 27 ص 140. وَاعْلَمُوا أَنَّ اللهَ مَعَ الْمُتَّقِينَ (123) وَإِذا ما أُنْزِلَتْ سُورَةٌ فَمِنْهُمْ مَنْ يَقُولُ أَيُّكُمْ زادَتْهُ هذِهِ والصبي والفاني والراهب وممن لا يساعد المحاربين ( وَاعْلَمُوا أَنَّ اللهَ مَعَ الْمُتَّقِينَ ) فلا تتركوا التقوى كما لا يرعوي المحاربون ـ إذا فتحوا البلاد ـ من كل إثم وشناعة ، فإن الإسلام جاء محرّرا لا فاتحا ، فليس للجيوش الإسلامية أن تفعل ما تشاء إذا غلبت. و قد زجر الرسول صلى‌الله‌عليه‌وآله‌وسلم بلالا حين رأى من بعض النساء اليهوديات ـ من أهل خيبر ـ تغيرا فسألهن ما بالهن ؟ فلما أجبن بأن بلال مرّ بهن على مصارع قتلاهن ـ يعني يهود خيبر ـ قال الرسول لبلال زاجرا : كأن الله نزع الرحمة من قلبك ! [124] ويأتي السياق ليبيّن كلام المنافقين وما يرتسم في قلوبهم وحركاتهم إذا أنزلت سورة ، فإن المنافق إذا أنزلت سورة تريب نفسه وتحمل السورة إلى محامل بعيدة عن الحقيقة والواقع ليثلج صدره بالتكذيب ، وطبق ما في نفسه يطفح كلام مريب على لسانه فيتساءل ممن حوله عن وقع السورة في نفوسهم ، حتى يرتب الأثر ، فإن جذبت السورة ناسا ردّهم ، وإن لم تجذبهم يزيدهم ريبا وشكا. أما حركته فإنه ينزعج من الحضور في مجال تتلى السورة فيه لأن قلبه لا يميل إليهم ولا إليها ، إذن فلينصرف عن المجلس متسلّلا حتى لا يعلم نفاقه ، ويستريح إلى أقرانه ( وَإِذا ما أُنْزِلَتْ سُورَةٌ ) « ما » زائدة جيء بها لتحسين الكلام ، ولعله لنكتة بلاغية هي تصوير حال المنافق المنكر ، فقد نزلت السورة ، لكن في قلب المنافق « ما أنزلت » ( فَمِنْهُمْ ) أي من المنافقين ( مَنْ يَقُولُ ) على وجه الإنكار والاستخبار : ( أَيُّكُمْ زادَتْهُ هذِهِ ) السورة إِيماناً فَأَمَّا الَّذِينَ آمَنُوا فَزادَتْهُمْ إِيماناً وَهُمْ يَسْتَبْشِرُونَ (124) وَأَمَّا الَّذِينَ فِي قُلُوبِهِمْ مَرَضٌ فَزادَتْهُمْ رِجْساً إِلَى رِجْسِهِمْ وَماتُوا وَهُمْ كافِرُونَ (125) أَ وَلا يَرَوْنَ أَنَّهُمْ يُفْتَنُونَ ( إِيماناً ) ؟ ليعلموا وقع أثر السورة في النفوس والمقاومة إذا أرادوا إلقاء الريب والشك. وهنا يأتي الجواب من الله سبحانه ليفصل في الأمر بما هو الواقع ، من غير حاجة إلى جواب المؤمنين أو إلى جواب المنافقين : ( فَأَمَّا الَّذِينَ آمَنُوا فَزادَتْهُمْ إِيماناً ) فإن المؤمن المخلص كلّما ذكر الله سبحانه وكلّما رأى آية من آياته يزداد إيمانا وعقيدة ( وَهُمْ يَسْتَبْشِرُونَ ) يفرحون بنزول السورة فرحا يظهر في وجوههم أثره ، وكيف لا يفرحون وقد زادهم سبحانه دلالة وكرامة ، وقوّى جانبهم بنزول سورة أخرى ؟!` },
            { text: "يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ قَٰتِلُوا۟ ٱلَّذِينَ يَلُونَكُم مِّنَ ٱلْكُفَّارِ وَلْيَجِدُوا۟ فِيكُمْ غِلْظَةً وَٱعْلَمُوٓا۟ أَنَّ ٱللَّهَ مَعَ ٱلْمُتَّقِينَ", tafsir: `` },
            { text: "وَإِذَا مَآ أُنزِلَتْ سُورَةٌ فَمِنْهُم مَّن يَقُولُ أَيُّكُمْ زَادَتْهُ هَٰذِهِۦٓ إِيمَٰنًا فَأَمَّا ٱلَّذِينَ ءَامَنُوا۟ فَزَادَتْهُمْ إِيمَٰنًا وَهُمْ يَسْتَبْشِرُونَ", tafsir: `` },
            { text: "وَأَمَّا ٱلَّذِينَ فِى قُلُوبِهِم مَّرَضٌ فَزَادَتْهُمْ رِجْسًا إِلَىٰ رِجْسِهِمْ وَمَاتُوا۟ وَهُمْ كَٰفِرُونَ", tafsir: `روحي ، وهو الشك والنفاق والإنكار ( فَزادَتْهُمْ ) السورة ( رِجْساً إِلَى رِجْسِهِمْ ) لأن قلوبهم كانت قذرة بإنكار ما سبق من آيات الله ، فإذا أنكروا هذه السورة وشكوا فيها زادت قذارة قلوبهم. ويسمى الكفر رجسا ، لأنه كالنجاسة الظاهرة التي تؤذي ، ويجب على الإنسان أن يتجنّبها ( وَماتُوا وَهُمْ كافِرُونَ ) فإن من لا تنفعه السور لا بد أن يبقى شاكا منافقا حتى يموت في كفره ونفاقه. [126] إن أمر هؤلاء المنافقين عجيب ، فإن السور لا تفيدهم ، والفتنة لا ترجعهم عن غيّهم ( أَ وَلا يَرَوْنَ ) هؤلاء المنافقون ـ على نحو الاستفهام الإنكاري ـ ( أَنَّهُمْ يُفْتَنُونَ ) أي يمتحنون ، تارة بنصر فِي كُلِّ عامٍ مَرَّةً أَوْ مَرَّتَيْنِ ثُمَّ لا يَتُوبُونَ وَلا هُمْ يَذَّكَّرُونَ (126) وَإِذا ما أُنْزِلَتْ سُورَةٌ نَظَرَ بَعْضُهُمْ إِلى بَعْضٍ هَلْ يَراكُمْ مِنْ أَحَدٍ ثُمَّ انْصَرَفُوا صَرَفَ اللهُ قُلُوبَهُمْ بِأَنَّهُمْ قَوْمٌ لا يَفْقَهُونَ (127) المسلمين ، وأخرى بكشف الرسول نواياهم ، وثالثة بالأمراض وما أشبه ، مما ينبغي أن يرجع المنافق عن غيّه إذا أصابه ذلك ( فِي كُلِّ عامٍ مَرَّةً أَوْ مَرَّتَيْنِ ) فالفتنة كثيرة الوقوع في حياتهم ( ثُمَّ لا يَتُوبُونَ ) عن نفاقهم وكفرهم ( وَلا هُمْ يَذَّكَّرُونَ ) نعم الله سبحانه ، وأدلته وحججه ، إن قلوبهم قد تحجّرت فلا تفيدها السورة ولا الفتنة ، فما ذا يصنع بها ؟ [127] ولما فرغ من بيان أقوالهم ونواياهم ، بيّن عملهم النفاقي تجاه نزول السورة ( وَإِذا ما أُنْزِلَتْ سُورَةٌ ) « ما » زائدة كما تقدم ، وهم حضور عند النبي صلى‌الله‌عليه‌وآله‌وسلم ( نَظَرَ بَعْضُهُمْ ) أي بعض هؤلاء المنافقين ( إِلى بَعْضٍ ) ليغمز إليه ويشير إليه بأن لا يؤمن ولا يتزحزح عن نفاقه. فيقول بعضهم لبعض بالقول أو الغمز والإشارة : ( هَلْ يَراكُمْ مِنْ أَحَدٍ ) من المؤمنين المخلصين ؟ والظاهر أن المراد رؤية الالتفات إلى نواياهم وإشاراتهم ، لا رؤية العين ، فإنهم كانوا يريدون عدم التفات المسلمين إلى أحوالهم لئلّا يعرفوا سبب قيامهم عن المجلس وانصرافهم ( ثُمَّ انْصَرَفُوا ) عن المجلس إذا لم يرهم أحد ، أو حين انفضّ المجلس ( صَرَفَ اللهُ قُلُوبَهُمْ ) دعاء عليهم بأن يصرف الله قلوبهم عن فهم الحق وإدراكه ، فإنهم لما نافقوا لم يستحقوا الألطاف الإلهية الخفية بسبب أنهم ( قَوْمٌ لا يَفْقَهُونَ ) الحق ، فقد طبع على قلوبهم بالكفر والعصيان والنفاق. لَقَدْ جاءَكُمْ رَسُولٌ مِنْ أَنْفُسِكُمْ عَزِيزٌ عَلَيْهِ ما عَنِتُّمْ حَرِيصٌ عَلَيْكُمْ بِالْمُؤْمِنِينَ رَؤُفٌ رَحِيمٌ (128) فَإِنْ تَوَلَّوْا فَقُلْ حَسْبِيَ اللهُ لا إِلهَ إِلاَّ هُوَ عَلَيْهِ تَوَكَّلْتُ [128] وفي ختام السورة تأتي آيتان لبيان وظيفة المؤمنين تجاه الرسول صلى‌الله‌عليه‌وآله‌وسلم الذي يحنو عليهم ، فاللازم أن ينصروه ويؤازروه ، ولبيان ما يفعله الرسول صلى‌الله‌عليه‌وآله‌وسلم لو تولّى الناس عنه وأعرضوا ، وكأنها خاتمة لما تقدم من أحوال من آمن وآزر ، ومن نافق وتخلف ( لَقَدْ جاءَكُمْ ) أيها البشر ، أو أيها المؤمنون ( رَسُولٌ مِنْ أَنْفُسِكُمْ ) أي من جنس نفوسكم ، وهو محمد صلى‌الله‌عليه‌وآله‌وسلم . وهذا تحريض لاتباعه والأخذ بأمره حيث أنه من أنفسهم ( عَزِيزٌ عَلَيْهِ ما عَنِتُّمْ ) أي صعب عليه عنتكم وما يلحق بكم من الضرر والأذى ( حَرِيصٌ عَلَيْكُمْ ) أي على حفظكم وتقدمكم وسعادتكم ، فلستم بهيّنين عليه حتى لا يهمّه أمركم ، ويلقي بكم في المهالك اعتباطا ، فإذا أمركم بأمر فإن فيه سعادتكم وخيركم ، لأنه جاء من المشفق الحريص على شؤونكم ( بِالْمُؤْمِنِينَ رَؤُفٌ ) الرأفة شدة الرحمة ( رَحِيمٌ ) للتأكيد وتفهيم من لا يفهم معنى الرؤوف ، فهو وصف توضيحي من قبيل « سعدانة تنبت » .` },
            { text: "أَوَلَا يَرَوْنَ أَنَّهُمْ يُفْتَنُونَ فِى كُلِّ عَامٍ مَّرَّةً أَوْ مَرَّتَيْنِ ثُمَّ لَا يَتُوبُونَ وَلَا هُمْ يَذَّكَّرُونَ", tafsir: `` },
            { text: "وَإِذَا مَآ أُنزِلَتْ سُورَةٌ نَّظَرَ بَعْضُهُمْ إِلَىٰ بَعْضٍ هَلْ يَرَىٰكُم مِّنْ أَحَدٍ ثُمَّ ٱنصَرَفُوا۟ صَرَفَ ٱللَّهُ قُلُوبَهُم بِأَنَّهُمْ قَوْمٌ لَّا يَفْقَهُونَ", tafsir: `` },
            { text: "لَقَدْ جَآءَكُمْ رَسُولٌ مِّنْ أَنفُسِكُمْ عَزِيزٌ عَلَيْهِ مَا عَنِتُّمْ حَرِيصٌ عَلَيْكُم بِٱلْمُؤْمِنِينَ رَءُوفٌ رَّحِيمٌ", tafsir: `` },
            { text: "فَإِن تَوَلَّوْا۟ فَقُلْ حَسْبِىَ ٱللَّهُ لَآ إِلَٰهَ إِلَّا هُوَ عَلَيْهِ تَوَكَّلْتُ وَهُوَ رَبُّ ٱلْعَرْشِ ٱلْعَظِيمِ", tafsir: `وأعرضوا عنك يا رسول الله ، وعن رسالتك ( فَقُلْ ) يا رسول الله : ( حَسْبِيَ اللهُ ) أي كافيّ ، فإنه قادر على أن ينصرني ( لا إِلهَ إِلَّا هُوَ ) لا شريك له أرجوه أو أخافه ، بل هو وحده بيده كل شيء ، فهو قادر على نصري وإعزازي ( عَلَيْهِ تَوَكَّلْتُ ) اتكلت في أموري كلها وَهُوَ رَبُّ الْعَرْشِ الْعَظِيمِ (129) عليه ( وَهُوَ رَبُّ الْعَرْشِ الْعَظِيمِ ) فهو أعظم من كل عظيم ، إذ العرش العظيم ـ أي السلطان الكبير ـ له ، فمن اتصل به لا يخشى أحدا سواه ، وإن أعرض عنه الناس ، فإن العرش كناية عن السلطة والسيادة. (10)` }
        ]
    }
});
